function getFileStatusMeta(status?: number | string | null, label?: string | null) {
  const normalizedStatus = status === null || status === undefined || status === '' ? null : Number(status)
  const statusLabel = label ?? (normalizedStatus === null || Number.isNaN(normalizedStatus) ? '' : `Durum: ${normalizedStatus}`)

  switch (normalizedStatus) {
    case 0:
      return { label: statusLabel, className: 'border-slate-400 bg-slate-500 text-white' }
    case 1:
      return { label: statusLabel, className: 'border-orange-500 bg-orange-500 text-white' }
    case 2:
      return { label: statusLabel, className: 'border-blue-500 bg-blue-600 text-white' }
    case 3:
      return { label: statusLabel, className: 'border-[#6fb744] bg-[#6fb744] text-white' }
    case 4:
      return { label: statusLabel, className: 'border-rose-500 bg-rose-600 text-white' }
    case 5:
      return { label: statusLabel, className: 'border-yellow-300 bg-yellow-200 text-yellow-950' }
    case 6:
      return { label: statusLabel, className: 'border-sky-500 bg-sky-600 text-white' }
    default:
      return { label: statusLabel, className: 'border-[#6fb744] bg-[#6fb744] text-white' }
  }
}

const dgnAssistanceTables = new Set(['yrd_ddgidadosyali', 'yrd_giyim', 'yrd_ayninakti'])

function isDgnAssistanceSource(sourceTable?: string | null) {
  return dgnAssistanceTables.has(sourceTable || '')
}

function getAssistanceStatusBadgeClass(status?: number | string | null, variant: 'default' | 'dgn' = 'default') {
  const normalizedStatus = status === null || status === undefined || status === '' ? '' : String(status)
  const defaultClasses: Record<string, string> = {
    '0': 'border-orange-700 !bg-orange-600 !text-white ring-2 ring-orange-200 shadow-md shadow-orange-300/70',
    '2': 'border-emerald-700 !bg-emerald-600 !text-white ring-2 ring-emerald-200 shadow-md shadow-emerald-300/70',
    '3': 'border-red-700 !bg-red-600 !text-white ring-2 ring-red-200 shadow-md shadow-red-300/70',
    '4': 'border-blue-700 !bg-blue-600 !text-white ring-2 ring-blue-200 shadow-md shadow-blue-300/70',
  }
  const dgnClasses: Record<string, string> = {
    '0': 'border-orange-700 !bg-orange-600 !text-white ring-2 ring-orange-200 shadow-md shadow-orange-300/70',
    '1': 'border-red-700 !bg-red-600 !text-white ring-2 ring-red-200 shadow-md shadow-red-300/70',
    '6': 'border-emerald-700 !bg-emerald-600 !text-white ring-2 ring-emerald-200 shadow-md shadow-emerald-300/70',
  }
  const classes = variant === 'dgn' ? dgnClasses : defaultClasses

  return classes[normalizedStatus] || defaultClasses['0']
}

