function getAssistanceStatusBadgeStyle(status?: number | string | null, variant: 'default' | 'dgn' = 'default') {
  const normalizedStatus = String(status ?? '').trim().toLocaleLowerCase('tr-TR')
  const isActive = variant === 'dgn'
    ? normalizedStatus === '6'
    : normalizedStatus === '2'
  const isCancelled = variant === 'dgn'
    ? normalizedStatus === '1'
    : normalizedStatus === '3'
  const isStopped = variant === 'default' && normalizedStatus === '4'

  if (isActive || normalizedStatus.includes('yardım alıyor') || normalizedStatus.includes('yardim aliyor')) {
    return { backgroundColor: '#059669', borderColor: '#047857', color: '#ffffff', boxShadow: '0 4px 12px rgba(5,150,105,0.35)' }
  }
  if (isCancelled || normalizedStatus.includes('iptal')) {
    return { backgroundColor: '#dc2626', borderColor: '#b91c1c', color: '#ffffff', boxShadow: '0 4px 12px rgba(220,38,38,0.35)' }
  }
  if (isStopped || normalizedStatus.includes('durdur')) {
    return { backgroundColor: '#2563eb', borderColor: '#1d4ed8', color: '#ffffff', boxShadow: '0 4px 12px rgba(37,99,235,0.35)' }
  }
  return { backgroundColor: '#ea580c', borderColor: '#c2410c', color: '#ffffff', boxShadow: '0 4px 12px rgba(234,88,12,0.35)' }
}

function getDgnAssistanceStatusLabel(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  status?: number | string | null,
) {
  if (status === null || status === undefined || status === '') return null
  const rawStatus = String(status)
  const category = Object.keys(values).find((key) => {
    const normalizedKey = normalizePredefinedText(key)
    const normalizedTitle = normalizePredefinedText(titles[key] ?? key)

    return [normalizedKey, normalizedTitle].some((value) => (
      value === 'dgnyardimdurumu' ||
      value.includes('dgnyardimdurumu')
    ))
  })

  return category ? values[category]?.find((item) => item.id === rawStatus)?.name ?? null : null
}

function getAssistanceStatusDisplayLabel(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  status?: number | string | null,
  sourceTable?: string | null,
) {
  if (isDgnAssistanceSource(sourceTable)) {
    return getDgnAssistanceStatusLabel(values, titles, status) ?? String(status ?? '-')
  }

  return getPredefinedValueLabel(values, 'yardim', 'durum', status, titles) ?? String(status ?? '-')
}

// "Yardım Düzenle" penceresindeki "Durumu" alani icin - Ayarlar > Sistem
// Ayarları > Hazır Değerler'de tanimli "Yardım Durumu" (ya da Ayni/Nakdi
// icin ayrica tanimlanmis "DGN Yardım Durumu") kategorisindeki TUM
// secenekleri dondurur - boylece kullanici ham bir sayi yerine, tam olarak
// Hazır Değerler'deki karsiligi olan etiketi gorup secebilir.
function getAssistanceStatusOptions(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  sourceTable?: string | null,
): PredefinedValue[] {
  if (isDgnAssistanceSource(sourceTable)) {
    const category = findPredefinedCategoryByCandidates(values, titles, ['D-G-N Yardım Durumu', 'dgnYardimDurumu', 'dgnAssistanceStatus'])
    return (category ? values[category] : null) ?? []
  }

  // ONEMLI: "resolvePredefinedCategory" burada KULLANILMIYOR - onun
  // bulanik (substring) eslestirmesi, "Dosya Durumu" basligi da ("dosya-
  // DURUM-u") icinde "durum" gectigi ve Object.keys sirasinda "fileStatus"
  // "assistanceStatus"tan ONCE geldigi icin YANLISLIKLA "Dosya Durumu"
  // listesini donduruyordu. findPredefinedCategoryByCandidates ile dogrudan
  // "assistanceStatus" (Yardım Durumu) kategorisi TAM ESLESME ile aranir.
  const category = findPredefinedCategoryByCandidates(values, titles, ['assistanceStatus', 'Yardım Durumu'])
  return (category ? values[category] : null) ?? []
}

function getMaritalStatusDisplayLabel(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  status?: number | string | null,
) {
  if (status === null || status === undefined || status === '') return '-'
  return getPredefinedValueLabel(values, 'person', 'maritalStatus', status, titles) ?? String(status)
}

function getRelationshipDisplayLabel(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  relation?: number | string | null,
  fallback = '-',
) {
  if (relation === null || relation === undefined || relation === '') return fallback
  return getPredefinedValueLabel(values, 'person', 'relation', relation, titles) ?? String(relation)
}

function isSelfRelationship(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  relation?: number | string | null,
) {
  const label = getRelationshipDisplayLabel(values, titles, relation, '')
  return normalizePredefinedText(label) === 'kendisi'
}

function getTodayInputDate() {
  const today = new Date()
  const year = today.getFullYear()
  const month = String(today.getMonth() + 1).padStart(2, '0')
  const day = String(today.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

// Kullanici istegi: "Belge Sahibi" alani artik eklenen belge DOSYASININ ADI
// ile doldurulsun (uzanti haric) - ör. "kimlik_on_yuz.jpg" secilince
// "kimlik_on_yuz" yazilir. Dosya adinda uzanti yoksa oldugu gibi kullanilir.
function deriveBelgeNameFromFileName(fileName: string) {
  const trimmed = (fileName || '').trim()
  if (!trimmed) return ''
  const withoutExtension = trimmed.replace(/\.[^./\\]+$/, '').trim()
  return withoutExtension || trimmed
}

// Belge ekleme sirasinda serbest metin olarak girilen "Gelir" alanini
// ("15.000 TL", "15.000,50", "15000" gibi Turkce bicimlerde) sayiya cevirir.
// Turkce yazim kurali: nokta binlik ayraci, virgul ondalik ayracidir - ancak
// tek basina nokta VE son parcasi 1-2 haneliyse ("1500.5" gibi) ondalik kabul
// edilir. Ayristirilamayan/anlamsiz metinlerde null doner.
function parseFreeFormAmount(text: string | null | undefined): number | null {
  const cleaned = (text || '').replace(/[^\d.,-]/g, '')
  if (!cleaned) return null

  let normalized = cleaned
  if (normalized.includes(',') && normalized.includes('.')) {
    normalized = normalized.replace(/\./g, '').replace(',', '.')
  } else if (normalized.includes(',')) {
    normalized = normalized.replace(',', '.')
  } else if (normalized.includes('.')) {
    const parts = normalized.split('.')
    if (!(parts.length === 2 && parts[1].length <= 2)) {
      normalized = normalized.replace(/\./g, '')
    }
  }

  const value = Number(normalized)
  return Number.isFinite(value) ? value : null
}

// Serbest metin icindeki ilk 4 haneli (1900-2100 arasi) yili yakalar - "Evet
// - 2015", "2015 Model Fiat Egea", "2015" gibi bicimlerin hepsinden model
// yilini cikarmak icin kullanilir (bkz. Otomatik Red kontrolu).
function extractYearFromText(text: string | null | undefined): number | null {
  const match = (text || '').match(/(19|20)\d{2}/)
  if (!match) return null
  const year = Number(match[0])
  return year >= 1900 && year <= 2100 ? year : null
}

// Kullanici istegi: belge eklerken Geliri/Araç Modeli/Tapu Bilgisi
// alanlarina girilen bilgilerden, Açıklama alanina otomatik yazilacak
// cumleyi olusturur - hangi alan(lar) doluysa sadece onlar cumleye girer.
function buildBelgeCriteriaDescription(gelir: string, aracModeli: string, tapuBilgisi: string, vergiMukellefiyeti: string): string {
  const parts: string[] = []

  const gelirTrimmed = gelir.trim()
  if (gelirTrimmed) {
    const numeric = parseFreeFormAmount(gelirTrimmed)
    const gelirText = numeric !== null ? numeric.toLocaleString('tr-TR') : gelirTrimmed
    parts.push(`Şahsın aylık geliri ${gelirText} TL'dir`)
  }

  const aracTrimmed = aracModeli.trim()
  if (aracTrimmed) {
    parts.push(`${aracTrimmed} model araç kaydı vardır`)
  }

  const tapuTrimmed = tapuBilgisi.trim()
  if (tapuTrimmed) {
    parts.push(`${tapuTrimmed} tapu kaydı vardır`)
  }

  if (vergiMukellefiyeti.trim() === 'Var') {
    parts.push('vergi mükellefiyeti kaydı vardır')
  }

  if (parts.length === 0) return ''
  if (parts.length === 1) return `${parts[0]}.`

  const last = parts[parts.length - 1]
  const rest = parts.slice(0, -1)
  return `${rest.join(', ')} ve ${last}.`
}

function isCompleteInputDate(value?: string | null) {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false

  const [yearText, monthText, dayText] = value.split('-')
  const year = Number(yearText)
  const month = Number(monthText)
  const day = Number(dayText)
  const date = new Date(year, month - 1, day)

  return (
    date.getFullYear() === year &&
    date.getMonth() === month - 1 &&
    date.getDate() === day
  )
}


