// WhatsApp'in kendi arayüzündeki tik simgeleriyle tutarlı, mesajın hangi
// aşamada olduğunu (gönderildi / iletildi / OKUNDU) gösteren küçük gösterge -
// bkz. "Mesaj Raporları" penceresi, MessageLogRow.readStatus.
function WhatsappReadStatusBadge({ status, label }: { status: MessageLogRow['readStatus']; label: string }) {
  if (status === 'failed') {
    return (
      <span className="inline-flex items-center gap-1.5 text-rose-700">
        <span className="text-sm font-black">✕</span>
        <span className="text-[11px] font-black uppercase tracking-wide">{label}</span>
      </span>
    )
  }
  if (status === 'read') {
    return (
      <span className="inline-flex items-center gap-1.5 text-sky-600">
        <span className="text-sm font-black tracking-tighter">✓✓</span>
        <span className="text-[11px] font-black uppercase tracking-wide">{label}</span>
      </span>
    )
  }
  if (status === 'delivered') {
    return (
      <span className="inline-flex items-center gap-1.5 text-slate-500">
        <span className="text-sm font-black tracking-tighter">✓✓</span>
        <span className="text-[11px] font-black uppercase tracking-wide">{label}</span>
      </span>
    )
  }
  if (status === 'sent') {
    return (
      <span className="inline-flex items-center gap-1.5 text-slate-400">
        <span className="text-sm font-black">✓</span>
        <span className="text-[11px] font-black uppercase tracking-wide">{label}</span>
      </span>
    )
  }
  return <span className="text-[11px] font-black uppercase tracking-wide text-slate-400">{label}</span>
}

function StatusPill({ children }: { children: string }) {
  const normalizedStatus = children.toLocaleUpperCase('tr-TR')
  const statusClass =
    normalizedStatus.includes('YENİ MÜRACAAT') || normalizedStatus.includes('YENİ KAYIT')
      ? 'border border-amber-200 bg-amber-50 text-amber-800 shadow-sm'
      : normalizedStatus.includes('YARDIM ALIYOR') || normalizedStatus.includes('DEVAM EDİYOR')
        ? 'border border-emerald-200 bg-emerald-50 text-emerald-700 shadow-sm'
        : normalizedStatus.includes('İPTAL EDİLDİ')
          ? 'border border-rose-200 bg-rose-50 text-rose-700 shadow-sm'
          : normalizedStatus.includes('DURDURULDU')
            ? 'border border-sky-200 bg-sky-50 text-sky-700 shadow-sm'
            : 'border border-slate-200 bg-slate-50 text-slate-700 shadow-sm'

  return (
    <span className={`inline-flex h-8 items-center justify-center whitespace-nowrap rounded-full px-3 text-[11px] font-black uppercase tracking-wide ${statusClass}`}>
      {children}
    </span>
  )
}

