function ActionButton({ children, tone = 'primary', onClick }: { children: ReactNode; tone?: 'primary' | 'print' | 'secondary' | 'danger', onClick?: () => void }) {
  const toneClass = {
    primary: 'bg-[#0b86c5] text-white hover:bg-[#056da3]',
    secondary: 'border border-[#0076b6] bg-white text-[#005f95] hover:bg-[#eaf7fd]',
    danger: 'border border-rose-300 bg-rose-50 text-rose-700 hover:bg-rose-100',
    print: 'border border-amber-300 bg-amber-50 text-amber-800 hover:bg-amber-100',
  }[tone]

  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3.5 py-2 text-sm font-bold shadow-sm transition print:hidden ${toneClass}`}
    >
      {children}
    </button>
  )
}

type ActionDropdownIconTone = 'sky' | 'emerald' | 'amber' | 'violet' | 'indigo' | 'rose' | 'cyan'
type ActionDropdownItem = { label: string; onClick: () => void; icon?: ReactNode; variant?: 'default' | 'danger'; iconTone?: ActionDropdownIconTone; disabled?: boolean }

function ActionDropdown({ items, children }: { items: ActionDropdownItem[]; children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false)
  const triggerRef = useRef<HTMLDivElement>(null)
  const menuRef = useRef<HTMLDivElement>(null)
  const [menuPosition, setMenuPosition] = useState({ top: 0, left: 0 })
  // Kullanici istegi: eskiden ikonlar soluk/pastel (bg-{renk}-50) kutular
  // icindeydi - "daha renkli ve profesyonel" olsun diye artik DOLU renkli
  // (gradyanli) rozetlere ve satir uzerine gelince o rengin kendi tonuna
  // gecen bir vurguya cevrildi.
  const iconToneClass: Record<ActionDropdownIconTone, string> = {
    sky: 'bg-[#1E2A38]',
    emerald: 'bg-emerald-700',
    amber: 'bg-[#1E2A38]',
    violet: 'bg-[#1E2A38]',
    indigo: 'bg-[#1E2A38]',
    rose: 'bg-rose-600',
    cyan: 'bg-[#1E2A38]',
  }
  const rowHoverToneClass: Record<ActionDropdownIconTone, string> = {
    sky: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    emerald: 'hover:bg-emerald-50 hover:text-emerald-800',
    amber: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    violet: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    indigo: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    rose: 'hover:bg-rose-50 hover:text-rose-800',
    cyan: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
  }

  const updateMenuPosition = useCallback(() => {
    if (!triggerRef.current) return
    const rect = triggerRef.current.getBoundingClientRect()
    const menuWidth = 256
    const margin = 8
    // Kullanici istegi: menu ekran altinda kaliyordu - eski kod her satir
    // icin 44px TAHMIN ediyordu ama gercek satir yuksekligi (36px ikon +
    // dikey padding) ~52-56px, bu yuzden tahmin gercekten kucuk kaliyor ve
    // menu ekran disina tasabiliyordu. Menu DOM'da zaten varsa (acikken
    // yeniden konumlandirma) GERCEK olculen yukseklik kullanilir; ilk acilis
    // anindaki (henuz DOM'da olmayan) tahmin icin daha cömert bir deger
    // kullanilir - asagidaki useLayoutEffect menu render olur olmaz GERCEK
    // yukseklikle pozisyonu boya (paint) ONCESINDE duzeltir.
    const measuredHeight = menuRef.current?.getBoundingClientRect().height
    const estimatedMenuHeight = measuredHeight ?? Math.min(window.innerHeight - margin * 2, items.length * 56 + 24)
    // Kullanici istegi/hata raporu (2026-09-11): "butonlara basınca buton
    // listesi alakasız yerde açılıyor, butonun tam altında listelensin" -
    // kok neden: menu SOL kenari degil SAG kenari butonun sag kenarina
    // hizalaniyordu (rect.right - menuWidth) - bu, menuWidth (256px) dar bir
    // butondan (ör. "Dosya İşlemleri", ~130px) COK daha genis oldugu icin
    // menuyu butonun SOLUNA, gorunurde "alakasiz" bir yere kaydiriyordu.
    // Artik menunin SOL kenari butonun SOL kenariyla hizalanir (ekran
    // disina tasmaticak sekilde min() ile sinirlanarak) - "butonun tam
    // altinda" beklenen normal davranis.
    const left = Math.max(margin, Math.min(rect.left, window.innerWidth - menuWidth - margin))
    const shouldOpenUp = rect.bottom + margin + estimatedMenuHeight > window.innerHeight
    const top = shouldOpenUp
      ? Math.max(margin, rect.top - estimatedMenuHeight - margin)
      : Math.min(rect.bottom + margin, Math.max(margin, window.innerHeight - estimatedMenuHeight - margin))
    setMenuPosition({ top, left })
  }, [items.length])

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node
      if (
        triggerRef.current &&
        !triggerRef.current.contains(target) &&
        menuRef.current &&
        !menuRef.current.contains(target)
      ) {
        setIsOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // useLayoutEffect (useEffect DEGIL): menu portal'a eklendikten hemen
  // sonra, TARAYICI BOYAMADAN (paint) once GERCEK yukseklikle yeniden
  // konumlanir - boylece kullanici "once yanlis yerde, sonra dogru yere
  // ziplayan" bir titreme GORMEZ.
  useLayoutEffect(() => {
    if (!isOpen) return
    updateMenuPosition()
    window.addEventListener('resize', updateMenuPosition)
    window.addEventListener('scroll', updateMenuPosition, true)
    return () => {
      window.removeEventListener('resize', updateMenuPosition)
      window.removeEventListener('scroll', updateMenuPosition, true)
    }
  }, [isOpen, updateMenuPosition])

  return (
    <div className="relative z-[1000] inline-block text-left" ref={triggerRef}>
      <div
        onClick={() => {
          updateMenuPosition()
          setIsOpen(!isOpen)
        }}
        className="cursor-pointer"
      >
        {children}
      </div>
      {isOpen && typeof document !== 'undefined' && createPortal(
        <div
          ref={menuRef}
          className="dy-base-16 fixed z-[2147483647] max-h-[calc(100vh-1rem)] w-64 origin-top-right overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_16px_40px_rgba(16,30,43,0.25)] ring-1 ring-slate-950/5 animate-in fade-in zoom-in-95 duration-100"
          style={{ top: menuPosition.top, left: menuPosition.left }}
        >
          <div className="h-1 bg-[#1E2A38]" />
          <div className="max-h-[calc(100vh-2.5rem)] overflow-y-auto p-0.5">
            {items.map((item, index) => {
              const isDanger = item.variant === 'danger'
              const hoverClass = item.iconTone
                ? rowHoverToneClass[item.iconTone]
                : isDanger
                ? 'hover:bg-rose-50 hover:text-rose-700'
                : 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]'
              return (
                <button
                  key={index}
                  onClick={() => {
                    if (item.disabled) return
                    item.onClick()
                    setIsOpen(false)
                  }}
                  disabled={item.disabled}
                  className={`group flex w-full items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-1 text-left !text-[14px] font-black transition-all disabled:cursor-not-allowed disabled:opacity-45 ${
                    item.disabled
                      ? 'text-slate-400'
                      : isDanger
                      ? `text-rose-600 ${hoverClass}`
                      : `text-slate-700 ${hoverClass}`
                  } ${isDanger && index > 0 ? 'mt-0.5 border-t border-slate-100 pt-1.5' : ''}`}
                >
                  <div className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-lg text-white transition-transform group-hover:scale-105 ${
                    item.iconTone
                      ? iconToneClass[item.iconTone]
                      : isDanger
                      ? 'bg-rose-600'
                      : 'bg-slate-500'
                  }`}>
                    {item.icon && <span className="flex items-center justify-center [&_svg]:h-3.5 [&_svg]:w-3.5">{item.icon}</span>}
                  </div>
                  {item.label}
                </button>
              )
            })}
          </div>
        </div>,
        document.body
      )}
    </div>
  )
}

function ContextActionMenu({
  items,
  position,
  onClose,
}: {
  items: ActionDropdownItem[]
  position: { x: number; y: number }
  onClose: () => void
}) {
  const menuRef = useRef<HTMLDivElement>(null)
  const [menuPosition, setMenuPosition] = useState(position)
  // ActionDropdown ile AYNI gorsel dil (dolu/gradyanli rozetler) - bkz.
  // oradaki ayni-isimli sabitin yorumu.
  const iconToneClass: Record<ActionDropdownIconTone, string> = {
    sky: 'bg-[#1E2A38]',
    emerald: 'bg-emerald-700',
    amber: 'bg-[#1E2A38]',
    violet: 'bg-[#1E2A38]',
    indigo: 'bg-[#1E2A38]',
    rose: 'bg-rose-600',
    cyan: 'bg-[#1E2A38]',
  }
  const rowHoverToneClass: Record<ActionDropdownIconTone, string> = {
    sky: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    emerald: 'hover:bg-emerald-50 hover:text-emerald-800',
    amber: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    violet: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    indigo: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
    rose: 'hover:bg-rose-50 hover:text-rose-800',
    cyan: 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]',
  }

  // Kullanici istegi: menu ekran altinda kaliyordu - eski kod satir basina
  // 44px TAHMIN ediyordu ama gercek satir yuksekligi (36px ikon + dikey
  // padding) daha fazla, bu yuzden tahmin kucuk kaliyor ve menu ekran
  // disina tasabiliyordu. useLayoutEffect (useEffect DEGIL) sayesinde menu
  // portal'a eklendikten hemen sonra, TARAYICI BOYAMADAN once GERCEK
  // olculen yukseklikle konumlanir - hem dogru hem titremesiz.
  useLayoutEffect(() => {
    const menuWidth = 256
    const margin = 8
    const measuredHeight = menuRef.current?.getBoundingClientRect().height
    const menuHeight = measuredHeight ?? Math.min(window.innerHeight - margin * 2, items.length * 56 + 24)
    setMenuPosition({
      x: Math.max(margin, Math.min(position.x, window.innerWidth - menuWidth - margin)),
      y: Math.max(margin, Math.min(position.y, window.innerHeight - menuHeight - margin)),
    })
  }, [items.length, position.x, position.y])

  useEffect(() => {
    const closeOnMouseDown = (event: MouseEvent) => {
      const target = event.target as Node
      if (menuRef.current && !menuRef.current.contains(target)) onClose()
    }
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }

    document.addEventListener('mousedown', closeOnMouseDown)
    document.addEventListener('keydown', closeOnEscape)
    window.addEventListener('scroll', onClose, true)
    return () => {
      document.removeEventListener('mousedown', closeOnMouseDown)
      document.removeEventListener('keydown', closeOnEscape)
      window.removeEventListener('scroll', onClose, true)
    }
  }, [onClose])

  if (typeof document === 'undefined') return null

  return createPortal(
    <div
      ref={menuRef}
      className="dy-base-16 fixed z-[2147483647] w-64 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_16px_40px_rgba(16,30,43,0.25)] ring-1 ring-slate-950/5"
      style={{ top: menuPosition.y, left: menuPosition.x }}
    >
      <div className="h-1 bg-[#1E2A38]" />
      <div className="max-h-[calc(100vh-2.5rem)] overflow-y-auto p-0.5">
        {items.map((item, index) => {
          const isDanger = item.variant === 'danger'
          const hoverClass = item.iconTone
            ? rowHoverToneClass[item.iconTone]
            : isDanger
            ? 'hover:bg-rose-50 hover:text-rose-700'
            : 'hover:bg-[#EEF1F3] hover:text-[#1E2A38]'
          return (
            <button
              key={index}
              type="button"
              disabled={item.disabled}
              onClick={() => {
                if (item.disabled) return
                item.onClick()
                onClose()
              }}
              className={`group flex w-full items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-1 text-left !text-[14px] font-black transition-all disabled:cursor-not-allowed disabled:opacity-45 ${
                item.disabled
                  ? 'text-slate-400'
                  : isDanger
                  ? `text-rose-600 ${hoverClass}`
                  : `text-slate-700 ${hoverClass}`
              } ${isDanger && index > 0 ? 'mt-0.5 border-t border-slate-100 pt-1.5' : ''}`}
            >
              <div className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-lg text-white transition-transform group-hover:scale-105 ${
                item.iconTone
                  ? iconToneClass[item.iconTone]
                  : isDanger
                  ? 'bg-rose-600'
                  : 'bg-slate-500'
              }`}>
                {item.icon && <span className="flex items-center justify-center [&_svg]:h-3.5 [&_svg]:w-3.5">{item.icon}</span>}
              </div>
              {item.label}
            </button>
          )
        })}
      </div>
    </div>,
    document.body
  )
}

// Kullanici istegi (Ekim 2026): "Belgeler / Dosya Yönetimi / Yardım
// Hareketleri / Müracaatlar pencerelerini ana ekrandan bağımsız olarak
// taşıyıp köşesinden tutarak büyütüp küçültebilelim" - "Kurum İçi
// Haberleşme" penceresinde ZATEN çalışan sürükle/yeniden-boyutlandır
// mekanizması (bkz. communicationWindowRect/startCommunicationDrag/
// moveCommunicationWindow) burada GENELLENDİ, boylece her pencere kendi
// state'ini tutan bagimsiz bir "yuzen pencere" olur. Yeniden boyutlandirma
// tarayicinin kendi CSS "resize" ozelligiyle (sag-alt kose tutamaci) olur -
// kullanim yerinde ".resize" sinifi eklenir.
function useFloatingWindow(defaultRect: { x: number; y: number; width: number; height: number }) {
  const [rect, setRect] = useState(defaultRect)
  // Kullanici istegi (Ekim 2026): "pencerenin sag ust kosesine ekrani kapla
  // ve kucult butonlari ekleyelim" - "kapla" tiklaninca mevcut konum/boyut
  // kaydedilir ve pencere ekrana (viewport) yayilir; "kucult" (geri yukle)
  // tiklaninca kaydedilen onceki konum/boyuta doner.
  const [isMaximized, setIsMaximized] = useState(false)
  const preMaximizeRectRef = useRef(defaultRect)
  const toggleMaximize = () => {
    if (isMaximized) {
      setRect(preMaximizeRectRef.current)
      setIsMaximized(false)
      return
    }
    preMaximizeRectRef.current = rect
    setRect({ x: 4, y: 4, width: Math.max(320, window.innerWidth - 8), height: Math.max(240, window.innerHeight - 8) })
    setIsMaximized(true)
  }
  const dragRef = useRef<{ pointerId: number; startX: number; startY: number; originX: number; originY: number; width: number; height: number } | null>(null)
  // Kullanici istegi (Ekim 2026): "pencerenin köşesinden tutup boyutunu
  // degistirdigimizde icindeki yazi/alan boyutlari pencereye sigacak
  // sekilde buyuyup kucusun" - tarayicinin yerli "resize" ozelligi pencereyi
  // buyutup kucultunce React state'i TETIKLEMEDIGI icin (duz CSS), gercek
  // boyut degisikligini yakalamak icin ResizeObserver kullanilir; olcek,
  // GERCEK genislik / TASARIM genisligi oraniyla hesaplanip icerige "zoom"
  // (bkz. ScaledArea.tsx'teki AYNI teknik - layout'u GERCEKTEN kucultur,
  // transform:scale gibi koordinat/tasma sorunlari cikarmaz) olarak uygulanir.
  const containerRef = useRef<HTMLDivElement>(null)
  const [scale, setScale] = useState(1)
  const designSizeRef = useRef({ width: defaultRect.width, height: defaultRect.height })

  useEffect(() => {
    const element = containerRef.current
    if (!element) return
    const compute = () => {
      const { width: designWidth, height: designHeight } = designSizeRef.current
      const widthScale = element.clientWidth / designWidth
      const heightScale = element.clientHeight / designHeight
      const next = Math.min(widthScale, heightScale)
      setScale((prev) => {
        const clamped = Math.min(1.6, Math.max(0.55, next))
        return Math.abs(prev - clamped) < 0.01 ? prev : +clamped.toFixed(3)
      })
    }
    compute()
    const ro = new ResizeObserver(compute)
    ro.observe(element)
    return () => ro.disconnect()
  }, [])

  const startDrag = (event: React.PointerEvent<HTMLElement>) => {
    if (window.innerWidth < 640 || (event.target as HTMLElement).closest('button')) return
    const windowElement = event.currentTarget.parentElement
    const bounds = windowElement?.getBoundingClientRect()
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      originX: bounds?.left ?? rect.x,
      originY: bounds?.top ?? rect.y,
      width: bounds?.width ?? rect.width,
      height: bounds?.height ?? rect.height,
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  const onDrag = (event: React.PointerEvent<HTMLElement>) => {
    const drag = dragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return
    setRect((current) => ({
      ...current,
      width: drag.width,
      height: drag.height,
      x: Math.max(0, Math.min(window.innerWidth - 120, drag.originX + event.clientX - drag.startX)),
      y: Math.max(0, Math.min(window.innerHeight - 64, drag.originY + event.clientY - drag.startY)),
    }))
  }

  const endDrag = (event: React.PointerEvent<HTMLElement>) => {
    dragRef.current = null
    event.currentTarget.releasePointerCapture(event.pointerId)
  }

  return { rect, setRect, startDrag, onDrag, endDrag, containerRef, scale, isMaximized, toggleMaximize }
}

// Kullanici istegi (Ekim 2026): "pencerenin sag ust kosesine ekrani
// kapla/kucult butonlari ekleyelim" - 5 pencerenin (Kurum Ici Haberlesme,
// Belgeler, Dosya Guncelle, Yardim Hareketleri, Muracaatlar) basliginda
// tekrar eden kod yerine TEK bir paylasilan buton bileseni.
function WindowMaximizeButton({
  isMaximized,
  onToggle,
  className = 'h-8 w-8',
  iconClassName = 'h-4 w-4',
}: {
  isMaximized: boolean
  onToggle: () => void
  className?: string
  iconClassName?: string
}) {
  return (
    <button
      type="button"
      onClick={onToggle}
      title={isMaximized ? 'Küçült' : 'Ekranı Kapla'}
      aria-label={isMaximized ? 'Pencereyi küçült' : 'Pencereyi ekrana kapla'}
      className={`inline-flex shrink-0 items-center justify-center rounded-lg border border-white/25 bg-white/10 text-white transition hover:bg-white/25 ${className}`}
    >
      {isMaximized ? (
        <svg className={iconClassName} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M9 9V4.5M9 9H4.5M9 9L3.75 3.75M9 15v4.5M9 15H4.5M9 15l-5.25 5.25M15 9h4.5M15 9V4.5M15 9l5.25-5.25M15 15h4.5M15 15v4.5M15 15l5.25 5.25" />
        </svg>
      ) : (
        <svg className={iconClassName} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9M20.25 20.25h-4.5m4.5 0v-4.5m0 4.5L15 15" />
        </svg>
      )}
    </button>
  )
}

function Section({
  title,
  children,
  actions,
  tone = 'default',
  icon,
  compactHeader = false,
  stackedHeader = false,
}: {
  title: string
  children: ReactNode
  actions?: ReactNode
  tone?: 'default' | 'applications' | 'assistance' | 'reports' | 'notes'
  icon?: ReactNode
  compactHeader?: boolean
  stackedHeader?: boolean
}) {
  // Kullanici istegi (Ekim 2026, 2. tur - "başlık alanları... daha belirgin
  // ve renklendirelim"): tamamen duz beyaz baslik gecici olarak denendi
  // ama kullanici PANELLERIN birbirinden AYIRT EDILEBILIR, RENKLI olmasini
  // istedi - bu yuzden her "tone" icin DUZ (gradyansiz, tek renk) bir
  // baslik zemini geri getirildi: eski parlak 3 renkli degradeler DEGIL,
  // kurumsal/sade TEK bir dogru renk + beyaz yazi.
  // Kullanici istegi (2026-09-29): "daha profesyonel görünsün" - AYNI
  // renk ailesi (her tone hala birbirinden AYIRT EDILEBILIR) korunur, ama
  // her biri daha KOYU/DUŞUK DOYGUNLUKTA (parlak degil, "kurumsal") bir
  // tona cekildi.
  // Kullanici istegi (2026-09-30): "Raporlar ve Tahkikatlar" basligi hala
  // hosuna gitmedi, "yazi fontunu degistirelim, renk ve sekil olarak daha
  // kurumsal yapalim" - SADECE "reports" tonu icin koyu lacivert/antrasit
  // zemine + ince harf araliklibuyuk harf, daha az kalin (semibold) bir
  // baslik yazisina gecildi (banka/devlet dairesi hissi). Digger tum
  // tonlar (default/applications/assistance/notes) AYNEN eskisi gibi
  // kaldi - "title" alani boş ise <h2> eski "font-bold" varsayilanini kullanir.
  const toneClass = {
    default: { header: 'bg-[#0B5F68]', icon: 'bg-white/15 text-white', title: 'font-bold' },
    applications: { header: 'bg-[#0B5F68]', icon: 'bg-white/15 text-white', title: 'font-bold' },
    assistance: { header: 'bg-[#0C5F48]', icon: 'bg-white/15 text-white', title: 'font-bold' },
    reports: { header: 'bg-[#1E2A38]', icon: 'bg-white/15 text-white', title: 'font-semibold uppercase tracking-wide' },
    notes: { header: 'bg-[#54397F]', icon: 'bg-white/15 text-white', title: 'font-bold' },
  }[tone]

  return (
    <section className="relative flex h-full flex-col overflow-visible rounded-xl border border-[#E2E5DE] bg-white shadow-[0_1px_2px_rgba(16,30,43,0.04),0_8px_24px_rgba(16,30,43,0.06)] print:m-0 print:border-none print:shadow-none">
      {/* Kullanici istegi (28 Agustos 2026 - tablet): baslik yazisi ile
          islem butonlari TABLETTE (ve dar ekranlarda) "ic ice geciyordu".
          Cozum: serit artik "flex-wrap" - dar ekranda butonlar alt satira
          iner (sabit "h-14" -> "min-h-14"), baslik ise "flex-1 min-w-0" +
          truncate ile daralir; ust uste binme kalkti. Genis ekranda
          gorunum AYNEN eskisi gibi (tek satir, yanda butonlar). */}
      {/* Kullanici istegi (2026-09-30, devam): "Raporlar ve Tahkikatlar"
          basligi hala hosa gitmiyordu - kok neden renk/font degildi: bu
          panel dar oldugu icin (3 panelli satirda), sekmeler + "İşlemler"
          butonu (shrink-0) ayni satirda basligin (flex-1 min-w-0) TÜM
          genisligini yiyip baslik metnini "truncate" ile GORUNMEZ hale
          getiriyordu (sadece ikon goruntuleniyordu). "stackedHeader" modu
          bu panel icin baslik ve islem satirini AYRI satirlara ayirir -
          baslik artik HER ZAMAN tam genislikte ve okunabilir. */}
      {stackedHeader ? (
        <div className={`relative z-[500] flex shrink-0 flex-col gap-1 ${toneClass.header} px-4 py-1 print:border-b-2 print:border-black print:bg-transparent print:px-0`}>
          <h2 className={`flex min-w-0 items-center gap-2.5 ${toneClass.title} ${compactHeader ? 'text-[13px] sm:text-[14.5px]' : 'text-[13.5px] sm:text-[15px]'} text-white print:text-black`}>
            {icon && (
              <span className={`inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${toneClass.icon} print:hidden`}>
                {icon}
              </span>
            )}
            <span className="truncate">{title}</span>
          </h2>
          {actions && <div className="flex flex-wrap items-center justify-end gap-1.5 print:hidden">{actions}</div>}
        </div>
      ) : (
        <div className={`relative z-[500] flex shrink-0 flex-wrap items-center justify-between gap-x-3 gap-y-1.5 ${toneClass.header} ${compactHeader ? 'min-h-14 px-4 py-2' : 'min-h-12 px-4 py-2.5'} print:border-b-2 print:border-black print:bg-transparent print:px-0`}>
          <h2 className={`flex min-w-0 flex-1 items-center gap-2.5 ${toneClass.title} ${compactHeader ? 'text-[13px] sm:text-[14.5px]' : 'text-[13.5px] sm:text-[15px]'} text-white print:text-black`}>
            {icon && (
              <span className={`inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${toneClass.icon} print:hidden`}>
                {icon}
              </span>
            )}
            <span className="truncate">{title}</span>
          </h2>
          {actions && <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5 print:hidden">{actions}</div>}
        </div>
      )}
      {/* Kullanici istegi: "Hanedeki Bireyler" gibi genis/kirpilamayan
          (min-w-max) tablolar iceren paneller, Tasarim Modu'nda kullanicinin
          ayarladigi genisligi yok sayip icerigin dogal genisligine gore
          BUYUYORDU - kok neden, bir flex-col zincirindeki (dikey eksende
          "min-h-0" ile zaten cozulmus olan) AYNI sorunun YATAY (genislik)
          esdegeriydi: flex ogelerinin varsayilan "min-width: auto" davranisi,
          icerideki genis tabloyu kapsayacak sekilde konteynerin kendisini
          genisletmeye calisiyordu. "min-w-0" eklenerek bu oge, disaridan
          (Tasarim Modu'nda) belirlenen genislige HER ZAMAN sadik kalir,
          genis icerik ise (DataTable'in kendi "overflow-x-auto" alaninda)
          YATAY kaydirma ile gorunur - konteyner genislemez. */}
      <div className="min-h-0 min-w-0 flex-1 bg-white">
        {children}
      </div>
    </section>
  )
}

function DataTable<T extends object>({
  columns,
  rows,
  emptyText,
  highlight,
  tableName,
  ownerAddressNo,
  onRowSelect,
  onRowDoubleClick,
  onRowContextMenu,
  actionColumnLabel,
  renderRowAction,
  predefinedValues = DEFAULT_PREDEFINED_VALUES,
  predefinedValueTitles = DEFAULT_PREDEFINED_VALUE_TITLES,
  colorTone,
  minimumRowsViewport,
  gulkartLookup,
  reorderTableId,
  columnCustomizationEnabled = false,
  headerAccentColor,
  reserveScrollGutter = false,
}: {
  columns: TableColumn<T>[]
  rows: T[]
  emptyText?: string
  highlight?: boolean
  tableName?: string
  ownerAddressNo?: string
  onRowSelect?: (row: T, index: number) => void
  onRowDoubleClick?: (row: T, index: number) => void
  onRowContextMenu?: (event: React.MouseEvent<HTMLTableRowElement>, row: T, index: number) => void
  actionColumnLabel?: string
  renderRowAction?: (row: T, index: number) => React.ReactNode
  predefinedValues?: PredefinedValuesMap
  predefinedValueTitles?: PredefinedValueTitlesMap
  colorTone?: 'amber' | 'violet' | 'cyan'
  minimumRowsViewport?: 'three' | 'five'
  // Kullanici istegi: "Müracaatlar" tablosunda Ayni/Nakdi (Nakit Yardımı)
  // satirlarinda "Yardım Başlangıç/Bitiş Tarihi"/"Durumu" yerine, basvuru
  // sahibinin TC'sine kayitli Gülkart NUMARASI (varsa) gosterilir - bkz.
  // gulkartCardByTc (TC -> kart no eslemesi).
  gulkartLookup?: Record<string, string>
  // Kullanici istegi: "bu alandaki başlıkların yerlerini değiştirebilelim
  // ve değiştirdiğimiz gibi kaydetsin" - sutun basliklari SURUKLE-BIRAK ile
  // yeniden siralanabilsin/boyutlandirilabilsin ve bu KALICI olsun. Verilirse
  // (bir tableId), KAYITLI duzen HER ZAMAN yuklenip uygulanir (Tasarim
  // Modu'ndan BAGIMSIZ - kullanici sayfayi actiginda daha once ayarladigi
  // duzeni GORMELI, sadece Tasarim Modu'na tekrar girince gorunmemeli).
  // Yeni siralama/genislik HEM localStorage'a HEM de sunucuya (bkz.
  // app/api/table-settings/route.ts - Raporlar sayfalarindaki "Sütun
  // Ayarları" ile AYNI, zaten var olan genel mekanizma) OTOMATIK (ayrica bir
  // "Kaydet" tusuna basmaya GEREK KALMADAN) kaydedilir.
  reorderTableId?: string
  // Kullanici istegi (2. tur): "bu işlemi herzaman değil sadece tasarım
  // modundayken yapalım" - surukle-birak/boyutlandirma ETKILESIMI (baslik
  // draggable olmasi, sag kenardaki tutamac) SADECE bu true iken aktiftir;
  // false ise basliklar KAYITLI duzeni GOSTERMEYE devam eder ama
  // degistirilemez (yanlislikla normal kullanimda duzenin bozulmasini
  // onlemek icin).
  columnCustomizationEnabled?: boolean
  // Kullanici istegi (Ekim 2026): alt sekmelerde bir sekme acildiginda,
  // tablo basligi da o sekmenin RENGIYLE (acik tonlu zemin + renkli metin +
  // renkli alt kenarlik) boyansin - verilirse "head" temasini ezer.
  headerAccentColor?: string
  // Kullanici istegi (2026-09-16): "verilerle kaydırma çubuğu arasında en
  // az 1 cm boşluk olsun" - bu, DataTable'i "flex-1" ile GERCEKTEN
  // gerilebilen bir ust ogeye saran cagri yerlerinde (bkz. Dosya
  // Yonetimi'ndeki Hane Bilgileri/Müracaatlar/Yardımlar/Diğer Kurum
  // Yardımları sekmeleri) verilir - true ise kaydirma kutusunun EN ALTINA
  // sabit 1cm bosluk eklenir, boylece hem "alan neredeyse bos" durumunda
  // (min-height tabani zaten bosluk birakiyor) HEM DE "icerik tabani asip
  // buyudugu" durumda (aksi halde bosluk SIFIRLANIRDI) GARANTILI bir
  // bosluk kalir. Varsayilan false - DIGER (bu sekilde gerilmeyen)
  // DataTable kullanimlarini ETKILEMEZ.
  reserveScrollGutter?: boolean
}) {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null)
  const activeSelectedIndex = selectedIndex !== null && selectedIndex < rows.length ? selectedIndex : null

  // Kullanici istegi: sutun basliklarini surukle-birak ile yeniden
  // siralayabilme + siralamanin KALICI olmasi - bkz. yukaridaki
  // reorderTableId notu. "columnOrder" SADECE sutun ANAHTARLARININ
  // sirasini tutar (etiket/icerik degil) - boylece disaridan gelen
  // "columns" prop'u disaridan degisebildiginde de her zaman GUNCEL kalir, sadece SIRASI
  // kullanicinin en son biraktigi sekilde uygulanir.
  const columnReorderStorageKey = reorderTableId ? `table_layout_${reorderTableId}` : null
  const [columnOrder, setColumnOrder] = useState<string[] | null>(null)
  const [draggedColumnKey, setDraggedColumnKey] = useState<string | null>(null)
  const [dragOverColumnKey, setDragOverColumnKey] = useState<string | null>(null)

  useEffect(() => {
    if (!columnReorderStorageKey) return
    let cancelled = false

    try {
      const localRaw = window.localStorage.getItem(columnReorderStorageKey)
      if (localRaw) {
        const parsed = JSON.parse(localRaw) as string[]
        if (Array.isArray(parsed)) setColumnOrder(parsed)
      }
    } catch {
      // yoksay - localStorage bozuksa sunucudan gelen (asagida) esas alinir
    }

    fetch(`/api/table-settings?tableId=${encodeURIComponent(reorderTableId!)}`)
      .then((response) => (response.ok ? response.json() : null))
      .then((remote: string[] | null) => {
        if (!cancelled && Array.isArray(remote) && remote.length > 0) {
          setColumnOrder(remote)
          window.localStorage.setItem(columnReorderStorageKey, JSON.stringify(remote))
        }
      })
      .catch(() => { /* yoksay - localStorage'daki (varsa) ya da varsayilan sira kullanilir */ })

    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [columnReorderStorageKey])

  // Disaridan gelen "columns" prop'u (guncel/dogru etiket-icerik seti) ile
  // kullanicinin KAYITLI sira tercihini birlestirir - kayitli sirada olup
  // ARTIK columns icinde olmayan anahtarlar yoksayilir, columns icinde olup
  // kayitli sirada HENUZ olmayan (ör. sonradan eklenmis) anahtarlar sona
  // eklenir - boylece "columns" degisse bile hicbir sutun kaybolmaz/hata
  // vermez.
  const orderedColumns = useMemo(() => {
    if (!columnOrder || columnOrder.length === 0) return columns
    const byKey = new Map(columns.map((column) => [String(column.key), column]))
    const ordered = columnOrder.map((key) => byKey.get(key)).filter((column): column is TableColumn<T> => Boolean(column))
    const orderedKeySet = new Set(ordered.map((column) => String(column.key)))
    const remaining = columns.filter((column) => !orderedKeySet.has(String(column.key)))
    return [...ordered, ...remaining]
  }, [columns, columnOrder])

  const persistColumnOrder = (nextOrder: string[]) => {
    setColumnOrder(nextOrder)
    if (!columnReorderStorageKey || !reorderTableId) return
    try {
      window.localStorage.setItem(columnReorderStorageKey, JSON.stringify(nextOrder))
    } catch {
      // yoksay
    }
    void fetch('/api/table-settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tableId: reorderTableId, layout: nextOrder }),
    }).catch(() => { /* yoksay - siralama en azindan bu tarayicida (localStorage) kalici kalir */ })
  }

  const handleColumnDrop = (targetKey: string) => {
    if (!draggedColumnKey || draggedColumnKey === targetKey) {
      setDraggedColumnKey(null)
      setDragOverColumnKey(null)
      return
    }
    const currentOrder = orderedColumns.map((column) => String(column.key))
    const fromIndex = currentOrder.indexOf(draggedColumnKey)
    const toIndex = currentOrder.indexOf(targetKey)
    if (fromIndex === -1 || toIndex === -1) {
      setDraggedColumnKey(null)
      setDragOverColumnKey(null)
      return
    }
    const nextOrder = [...currentOrder]
    const [removed] = nextOrder.splice(fromIndex, 1)
    nextOrder.splice(toIndex, 0, removed)
    persistColumnOrder(nextOrder)
    setDraggedColumnKey(null)
    setDragOverColumnKey(null)
  }

  // Kullanici istegi: "bu alanların boyutlarını da ayarlayabilelim" -
  // sutunlar SURUKLE-BIRAK ile siralanmanin YANI SIRA, kenarindan tutup
  // GENISLIK olarak da yeniden boyutlandirilabilsin, bu da KALICI olsun.
  // Ayri bir "table_layout_<id>_widths" anahtari altinda (siralamadan BAGIMSIZ
  // ayri bir kayit - az once yayina alinan siralama ozelligini bozma riskini
  // en aza indirmek icin) HEM localStorage'a HEM sunucuya (AYNI /api/table-
  // settings genel mekanizmasi) kaydedilir.
  const columnWidthStorageKey = reorderTableId ? `table_layout_${reorderTableId}_widths` : null
  const columnWidthTableId = reorderTableId ? `${reorderTableId}-widths` : null
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({})
  const [resizingColumnKey, setResizingColumnKey] = useState<string | null>(null)
  const columnWidthsRef = useRef<Record<string, number>>({})
  const resizeStartRef = useRef<{ startX: number; startWidth: number } | null>(null)

  useEffect(() => {
    columnWidthsRef.current = columnWidths
  }, [columnWidths])

  useEffect(() => {
    if (!columnWidthStorageKey || !columnWidthTableId) return
    let cancelled = false

    try {
      const localRaw = window.localStorage.getItem(columnWidthStorageKey)
      if (localRaw) {
        const parsed = JSON.parse(localRaw) as Record<string, number>
        if (parsed && typeof parsed === 'object') setColumnWidths(parsed)
      }
    } catch {
      // yoksay - localStorage bozuksa sunucudan gelen (asagida) esas alinir
    }

    fetch(`/api/table-settings?tableId=${encodeURIComponent(columnWidthTableId)}`)
      .then((response) => (response.ok ? response.json() : null))
      .then((remote: Record<string, number> | null) => {
        if (!cancelled && remote && typeof remote === 'object') {
          setColumnWidths(remote)
          window.localStorage.setItem(columnWidthStorageKey, JSON.stringify(remote))
        }
      })
      .catch(() => { /* yoksay - localStorage'daki (varsa) ya da varsayilan genislikler kullanilir */ })

    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [columnWidthStorageKey, columnWidthTableId])

  const persistColumnWidths = (nextWidths: Record<string, number>) => {
    if (!columnWidthStorageKey || !columnWidthTableId) return
    try {
      window.localStorage.setItem(columnWidthStorageKey, JSON.stringify(nextWidths))
    } catch {
      // yoksay
    }
    void fetch('/api/table-settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tableId: columnWidthTableId, layout: nextWidths }),
    }).catch(() => { /* yoksay - genislik en azindan bu tarayicida (localStorage) kalici kalir */ })
  }

  const startColumnResize = (event: React.MouseEvent<HTMLDivElement>, columnKey: string) => {
    event.preventDefault()
    event.stopPropagation()
    const th = (event.currentTarget as HTMLElement).closest('th')
    const currentWidth = th?.getBoundingClientRect().width ?? 120
    resizeStartRef.current = { startX: event.clientX, startWidth: currentWidth }
    setResizingColumnKey(columnKey)
  }

  useEffect(() => {
    if (!resizingColumnKey) return

    const handleMouseMove = (event: MouseEvent) => {
      if (!resizeStartRef.current) return
      const delta = event.clientX - resizeStartRef.current.startX
      const nextWidth = Math.round(Math.max(60, resizeStartRef.current.startWidth + delta))
      setColumnWidths((prev) => ({ ...prev, [resizingColumnKey]: nextWidth }))
    }
    const handleMouseUp = () => {
      persistColumnWidths(columnWidthsRef.current)
      setResizingColumnKey(null)
      resizeStartRef.current = null
    }

    window.addEventListener('mousemove', handleMouseMove)
    window.addEventListener('mouseup', handleMouseUp)
    return () => {
      window.removeEventListener('mousemove', handleMouseMove)
      window.removeEventListener('mouseup', handleMouseUp)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resizingColumnKey])

  // TC Kimlik No / Doğum Tarihi sutunlarina cift tiklandiginda kopyalama -
  // Kişi Bilgileri panelindeki Field bileseninde kullanilan AYNI davranis
  // (copyTextToClipboard) burada da (ör. Hane Bilgileri tablosu) sunulur.
  const [copiedCellKey, setCopiedCellKey] = useState<string | null>(null)
  const handleCellDoubleClick = async (cellKey: string, value: string) => {
    if (!value) return
    const success = await copyTextToClipboard(value)
    if (success) {
      setCopiedCellKey(cellKey)
      window.setTimeout(() => setCopiedCellKey((current) => (current === cellKey ? null : current)), 1200)
    }
  }
  const COPYABLE_COLUMNS = new Set(['identityNumber', 'birthDate'])
  // Kullanici istegi (Ekim 2026): "dosya-yonetimi-redesign" referans
  // gorseline uygun sade tablo basligi - eski renk-kodlu (sky/emerald/
  // violet/cyan/amber degrade) basliklar yerine TEK tip acik gri zemin +
  // buyuk harf/harf araligi acik gri metin (bkz. referanstaki .simple-table
  // th kurali). tableTone.table/border alanlari genislik/kenarlik icin
  // asagida ayni sekilde kullanilmaya devam eder, sadece renkler degisti.
  const tableTone = tableName === 'requests'
    ? {
      table: 'min-w-[980px]',
      head: 'bg-[#F1F3EF] text-[#16232B]',
      border: 'border-[#E2E5DE]',
    }
    : tableName === 'assistance'
      ? {
        table: 'min-w-[980px]',
        head: 'bg-[#F1F3EF] text-[#16232B]',
        border: 'border-[#E2E5DE]',
      }
      : tableName === 'reports'
        ? {
          table: colorTone === 'cyan' ? 'min-w-[1180px] table-auto' : 'w-full table-auto',
          head: 'bg-[#F1F3EF] text-[#16232B]',
          border: 'border-[#E2E5DE]',
        }
        : {
          table: tableName === 'person' ? 'min-w-max table-auto' : 'min-w-[980px]',
          head: 'bg-[#F1F3EF] text-[#16232B]',
          border: 'border-[#E2E5DE]',
        }
  const isCompactTable = tableName === 'reports'
  const isRequestTable = tableName === 'requests'
  const externalAidTotal = tableName === 'reports' && colorTone === 'cyan'
    ? rows.reduce((total, row) => {
        const rawAmount = cleanDisplayValue((row as Record<string, unknown>).amount as string | number | null | undefined)
          .replace(/\s/g, '')
          .replace(/₺|TL/gi, '')
        const normalizedAmount = rawAmount.includes(',')
          ? rawAmount.replace(/\./g, '').replace(',', '.')
          : rawAmount
        const amount = Number(normalizedAmount)
        return total + (Number.isFinite(amount) ? amount : 0)
      }, 0)
    : 0
  const reportColumnClass = (columnName: string) => {
    if (tableName !== 'reports') return ''
    if (colorTone !== 'cyan') {
      if (columnName === 'no') return 'w-px whitespace-nowrap text-center'
      // Kullanici istegi (Ekim 2026, 9. tur): "veriler belirlenen alana
      // sığmıyorsa bir alt satıra geçsin, aynı Rapor sütununda olduğu
      // gibi" - "Tarih"/"Konu" sutunlari da (asagidaki "report" sutunuyla
      // AYNI) artik whitespace-nowrap yerine whitespace-normal/break-words
      // kullanir - uzun bir deger artik yatay tasip kirpilmek/kaydirma
      // cubugu cikarmak yerine ikinci satira sarar.
      // Kullanici istegi (Eylul 2026, sonraki tur): "Tarih" degeri kisa/sabit
      // bicimli (ör. 13.05.2026) - satir icinde sarilinca ortasindan ikiye
      // bolunup okunmuyordu. "w-px" (sadece icerige gore daralt) burada
      // KULLANILAMAZ - bu tablo reorderTableId tasidigi icin table-fixed
      // (bkz. yukarida "table-fixed" satiri), ve table-fixed altinda
      // "w-px" (width:1px) ilk satirin GERCEK genislik ipucu olarak
      // alinip sutunu asiri daraltiyor, tarihin son hanesi kirpiliyordu
      // (kullanici bildirimi: "14.09.202" gibi goruntuleniyordu). Sabit
      // bir min-genislik ile GARANTI altina alindi.
      if (columnName === 'date') return 'w-[100px] min-w-[100px] whitespace-nowrap px-2 text-center'
      if (columnName === 'subject') return 'whitespace-normal break-words'
      if (columnName === 'report') return 'w-full whitespace-normal break-words'
    }
    // "no" ve "tarih" sabit piksel genislige ("w-[40px]"/"w-[92px]") zorlanmiyordu -
    // "w-px" (table-auto ile birlikte "sadece icerigi kadar yer kapla" anlamina
    // gelen bilinen bir teknik) ile sutun, o sutundaki EN UZUN degerin
    // genisligi kadar dogal olarak boyutlaniyor.
    if (columnName === 'no') return 'w-px whitespace-nowrap px-2 text-center'
    if (columnName === 'date') return 'w-px whitespace-nowrap px-2 text-center'
    return 'whitespace-normal'
  }
  // Kisa/sabit bicimli "kod gibi" degerler (dosya no, kayit no, dosyaid,
  // TC kimlik no, inceleme puani, cinsiyet, yakinlik, medeni hali, adres no,
  // tarih) - hangi tablo (person/assistance/requests/documents/reports)
  // oldugundan bagimsiz olarak - sola dayali degil, sutun icinde ORTALI
  // gosterilir; bu tur degerler icin ortalama okunurlugu artirir.
  const CENTERED_SHORT_VALUE_COLUMNS = new Set([
    'no', 'dosyaId', 'dosyaNo', 'identityNumber', 'tc', 'tckimlikno',
    'incelemePuani', 'gender', 'relation', 'maritalStatus', 'addressNo',
    'birthDate', 'deathDate', 'date', 'olusturmaTarihi', 'guncellemeTarihi',
    'muracaatTarihi', 'status', 'durum', 'amount', 'miktar',
  ])
  const centeredShortValueColumnClass = (columnName: string) => (
    CENTERED_SHORT_VALUE_COLUMNS.has(columnName) ? 'text-center' : ''
  )
  // "Kayit no, TC kimlik no, yakinlik, medeni hali, adres no, tarih" gibi
  // kisa/sabit bicimli degerler icin ONCEDEN sabit bir "min-w-*" tabani
  // zorlaniyordu - bu, degerin gercekte ihtiyaci olandan DAHA GENIS bir
  // sutuna yol aciyordu. Bu sutunlar artik sadece "whitespace-nowrap" ile
  // (satir icinde, sarilmadan) tutuluyor - tablo dogal olarak (table-auto)
  // sutunu, o sutundaki EN UZUN degerin genisligi kadar boyutlandiriyor,
  // fazladan bosluk kalmiyor. Isim/soyisim/anne-baba adi/adres gibi
  // uzunlugu degisken metin alanlarina DOKUNULMADI (kucuk bir taban genislik
  // orada hala anlamli).
  const personCompactColumnClass = (columnName: string) => {
    if (columnName === 'address') return 'min-w-max px-3'
    if (columnName === 'no') return 'whitespace-nowrap px-1.5'
    if (columnName === 'relation') return 'whitespace-nowrap px-2'
    if (columnName === 'identityNumber') return 'whitespace-nowrap px-2'
    if (columnName === 'firstName' || columnName === 'lastName') return 'min-w-32 px-2'
    if (columnName === 'birthDate' || columnName === 'deathDate') return 'whitespace-nowrap px-2'
    if (columnName === 'fatherName' || columnName === 'motherName') return 'min-w-32 px-2'
    if (columnName === 'maritalStatus') return 'whitespace-nowrap px-2'
    if (columnName === 'mobilePhone') return 'min-w-28 px-2'
    if (columnName === 'addressNo') return 'whitespace-nowrap px-2'
    return 'px-2'
  }
  const reportRowsForMobile = tableName === 'reports'
    ? rows.map((row, index) => {
        const reportRow = row as Record<string, unknown>
        const noValue = reportRow.no as string | number | null | undefined
        const dateValue = reportRow.date as string | number | null | undefined
        const subjectValue = reportRow.subject as string | number | null | undefined
        const reportValue = reportRow.report as string | number | null | undefined

        return {
          row,
          index,
          no: cleanDisplayValue(noValue) || String(index + 1),
          date: cleanDisplayValue(dateValue) || '-',
          subject: cleanDisplayValue(subjectValue) || '-',
          report: cleanDisplayValue(reportValue) || '-',
          selected: activeSelectedIndex === index,
        }
      })
    : []

  return (
    // Kullanici istegi: bu tablo, disaridan (bkz. Dosya Yonetimi'ndeki
    // Tasarim Modu sarmalayicilari) "h-full" ile sarildiginda TAM verilen
    // alani doldursun ki yatay kaydirma cubugu her zaman o alanin GERCEK
    // altinda gorunsun. "h-full" (height:100%), tanimli bir yukseklige
    // sahip OLMAYAN (auto) bir ust ogenin altinda CSS geregi otomatik
    // olarak "auto"ya (etkisiz) doner - bu yuzden bu ekleme, DataTable'in
    // KULLANILDIGI DIGER (h-full VERMEYEN) tum yerlerde ZARARSIZDIR, sadece
    // gercekten h-full saglayan bir sarmalayici icindeyken devreye girer.
    <div className={`h-full ${minimumRowsViewport === 'five' ? 'min-h-[250px]' : minimumRowsViewport === 'three' ? 'min-h-[170px]' : ''} ${minimumRowsViewport ? '[scrollbar-color:#475569_#e2e8f0] [scrollbar-width:auto] [&::-webkit-scrollbar]:h-4 [&::-webkit-scrollbar-track]:rounded-full [&::-webkit-scrollbar-track]:bg-slate-200 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:border-2 [&::-webkit-scrollbar-thumb]:border-slate-200 [&::-webkit-scrollbar-thumb]:bg-slate-600' : ''} ${reserveScrollGutter ? 'pb-[1cm]' : ''} overflow-x-auto print:overflow-visible`}>
      {reportRowsForMobile.length > 0 && (
        // Kullanici istegi (2026-09-29): "Tarih ve Konu alanı Rapor
        // kısmının üstünde olsun ve her rapor renk tonu ile ayrılsın" -
        // eskiden bu kart gorunumu SADECE mobilde (md:hidden) kullanilirdi,
        // masaustunde duz bir tablo gosteriliyordu. Artik TUM genisliklerde
        // (masaustu dahil) bu kart duzeni kullanilir - Konu+Tarih ustte,
        // Rapor metni altta; renk tonu (amber/violet/cyan) sekmeye
        // (Inceleme/Onay/Ev Ziyareti) gore degisir ve satirlar KENDI tonu
        // icinde ACIK/KOYU alternatif renklerle (asagidaki desktop
        // tablosundaki AYNI index%2 mantigi) birbirinden ayrilir.
        <div className="space-y-2">
          {reportRowsForMobile.map((item) => {
            const toneClasses = colorTone === 'violet'
              ? {
                border: 'border-violet-200', hoverBorder: 'hover:border-violet-400',
                bgEven: 'bg-violet-50/50', bgOdd: 'bg-fuchsia-50/40', hoverBg: 'hover:bg-violet-50',
                subject: 'text-violet-900', date: 'text-violet-700',
              }
              : colorTone === 'cyan'
                ? {
                  border: 'border-cyan-200', hoverBorder: 'hover:border-cyan-400',
                  bgEven: 'bg-cyan-50/50', bgOdd: 'bg-teal-50/40', hoverBg: 'hover:bg-cyan-50',
                  subject: 'text-cyan-900', date: 'text-cyan-700',
                }
                : {
                  border: 'border-amber-100', hoverBorder: 'hover:border-amber-300',
                  bgEven: 'bg-white', bgOdd: 'bg-amber-50/70', hoverBg: 'hover:bg-amber-50/40',
                  subject: 'text-amber-900', date: 'text-[#005f95]',
                }
            const baseBg = item.index % 2 === 0 ? toneClasses.bgEven : toneClasses.bgOdd
            return (
              <button
                key={`${item.no}-${item.index}`}
                type="button"
                onClick={() => {
                  setSelectedIndex(item.index)
                  onRowSelect?.(item.row, item.index)
                  onRowDoubleClick?.(item.row, item.index)
                }}
                className={`w-full rounded-lg border px-3 py-2.5 text-left shadow-sm transition ${
                  item.selected
                    ? 'border-[#6fb744] bg-[#f1faed] ring-1 ring-[#6fb744]/40'
                    : `${toneClasses.border} ${baseBg} ${toneClasses.hoverBorder} ${toneClasses.hoverBg}`
                }`}
              >
                {/* Kullanici istegi (2026-09-29, devam): "üstteki Rapor 1
                    gibi başlıkları kaldıralım, tarih önde konu ise onun
                    yanda tek satırda farklı renkte olsun" - "Rapor #N"
                    etiketi kaldirildi; Tarih ve Konu ARTIK aralarinda ayrac
                    ile TEK satirda (tarih sabit/notr renk, konu tonun
                    kendi koyu rengi) gosteriliyor. "Oku" rozeti sadeleşip
                    kucuk bir ikona indirildi, sag ustte kalmaya devam eder. */}
                <div className="flex items-center justify-between gap-3">
                  <div className="flex min-w-0 flex-1 items-baseline gap-2">
                    <span className={`shrink-0 text-[12px] font-black tabular-nums ${toneClasses.date}`}>{item.date}</span>
                    <span className="shrink-0 text-slate-300">•</span>
                    <span className={`min-w-0 flex-1 truncate text-[14px] font-black uppercase leading-snug ${toneClasses.subject}`}>{item.subject}</span>
                  </div>
                  <span className="shrink-0 rounded-md bg-[#0076b6]/10 px-2 py-1 text-[11px] font-black uppercase text-[#0076b6]">
                    Oku
                  </span>
                </div>
                {/* Kullanici istegi (Ekim 2026): "yazi boyutu bir kademe
                    buyusun, koyu renkte bold olsun" - rapor metni oncesinde
                    en soluk/zayif kontrastli eleman (slate-600, semibold,
                    12px) idi; artik slate-800/bold/13px. */}
                <p className="mt-1.5 line-clamp-3 text-[13px] font-bold leading-5 text-slate-800">{item.report}</p>
              </button>
            )
          })}
        </div>
      )}
      {tableName === 'reports' && rows.length === 0 && (
        <div className="rounded-lg border border-amber-100 bg-white px-3 py-4 text-center text-xs font-bold text-slate-500">
          {emptyText || 'Kayit bulunamadi.'}
        </div>
      )}
      <table className={`${tableName === 'reports' ? 'hidden' : 'table border-collapse'} w-full text-left ${isCompactTable || isRequestTable ? 'text-[14px] sm:text-[14.5px]' : 'text-[14px] sm:text-[15.5px]'} font-bold text-black ${tableTone.table} ${reorderTableId ? 'table-fixed' : ''}`}>
        {reorderTableId && (
          // Kullanici istegi: sutunlarin GERCEKTEN elle ayarlanan genislikte
          // kalabilmesi icin (aksi halde varsayilan "table-layout: auto"
          // genislikleri icerige gore KENDI HESAPLAR, verilen width sadece
          // bir "ipucu" sayilir) tabloya table-fixed + her sutun icin acik
          // bir <col> genisligi verilir - elle ayarlanmamis sutunlar icin
          // width belirtilmez, kalan alani esit paylasirlar.
          <colgroup>
            {orderedColumns.map((column) => {
              const key = String(column.key)
              // Kullanici elle ayarladiysa (columnWidths) HER ZAMAN o esas
              // alinir; ayarlamadiysa TableColumn.defaultWidth (bkz. yukarida
              // tanim) kullanilir - o da yoksa (bilerek tek bir "serbest
              // metin" sutununda oldugu gibi) width verilmez, kalan alani alir.
              const width = columnWidths[key] ?? column.defaultWidth
              return <col key={key} style={width ? { width: `${width}px` } : undefined} />
            })}
            {/* Kullanici istegi (2026-09-30, devam): "Yazdır" sutunu TEKRAR EN
                SONA tasindi (bir onceki turda basa alinmisti). Genislik,
                DURUMU rozetiyle AYNI boyuta kucultulen "Onaya Gönder"
                butonunun hassas olcumune (168px) + DARALTILMIŞ hucre
                dolgusuna (px-2) gore ayarlandi; tablonun konteyner genisligi
                butun sutunlarin toplamindan DAR oldugu icin tarayici TUM
                sutunlari orantili ~%10 kucultuyor - bu yuzden 184px yerine
                ~%11 daha genis (205px) verildi. */}
            {renderRowAction && <col style={{ width: '205px' }} />}
          </colgroup>
        )}
        <thead
          className={`${tableName === 'reports' ? 'sticky top-0 z-10 shadow-sm text-[11px]' : 'text-[13px]'} ${headerAccentColor ? 'border-b-2' : tableTone.head} font-black uppercase leading-tight`}
          style={headerAccentColor ? { backgroundColor: `${headerAccentColor}1f`, color: headerAccentColor, borderColor: headerAccentColor } : undefined}
        >
          <tr>
            {orderedColumns.map((column) => {
              const columnName = String(column.key)

              return (
                <th
                  key={columnName}
                  draggable={columnCustomizationEnabled}
                  onDragStart={columnCustomizationEnabled ? () => setDraggedColumnKey(columnName) : undefined}
                  onDragOver={columnCustomizationEnabled ? (event) => { event.preventDefault(); setDragOverColumnKey(columnName) } : undefined}
                  onDragLeave={columnCustomizationEnabled ? () => setDragOverColumnKey((current) => (current === columnName ? null : current)) : undefined}
                  onDrop={columnCustomizationEnabled ? (event) => { event.preventDefault(); handleColumnDrop(columnName) } : undefined}
                  onDragEnd={columnCustomizationEnabled ? () => { setDraggedColumnKey(null); setDragOverColumnKey(null) } : undefined}
                  title={columnCustomizationEnabled ? 'Sürükleyip bırakarak sütun sırasını değiştirebilir, sağ kenarından tutup genişliğini ayarlayabilirsiniz' : undefined}
                  // Kullanici istegi (2026-09-30, devam): "alan başlıklarını
                  // ortalayalım" - baslik hucreleri artik ortali (text-center).
                  className={`relative border-b border-r ${tableTone.border} text-center ${isCompactTable ? 'py-2' : isRequestTable ? 'py-1.5' : 'py-2'} ${tableName === 'person' ? personCompactColumnClass(columnName) : isRequestTable ? 'px-2' : 'px-3'} ${reportColumnClass(columnName)} ${reorderTableId ? 'overflow-hidden text-ellipsis' : ''} ${columnCustomizationEnabled ? 'cursor-move select-none' : ''} ${draggedColumnKey === columnName ? 'opacity-40' : ''} ${dragOverColumnKey === columnName && draggedColumnKey && draggedColumnKey !== columnName ? 'bg-sky-100/80 ring-2 ring-inset ring-sky-400' : ''}`}
                >
                  {tableName === 'reports' && colorTone === 'cyan' && columnName === 'no' ? <span className="block leading-tight">Sıra<br />No</span> : column.label}
                  {columnCustomizationEnabled && (
                    <div
                      draggable={false}
                      onMouseDown={(event) => startColumnResize(event, columnName)}
                      onClick={(event) => event.stopPropagation()}
                      title="Sürükleyerek sütun genişliğini ayarlayın"
                      className={`absolute right-0 top-0 h-full w-2 cursor-col-resize select-none hover:bg-sky-400/50 ${resizingColumnKey === columnName ? 'bg-sky-500/60' : ''}`}
                    />
                  )}
                </th>
              )
            })}
            {/* Kullanici istegi (2026-09-30, devam): "Yazdır" sutunu TEKRAR EN
                SONA tasindi. */}
            {renderRowAction && <th className={`border-b border-r ${tableTone.border} px-2 py-2 text-center`}>{actionColumnLabel || 'İşlem'}</th>}
          </tr>
        </thead>
        <tbody>
          {rows.length > 0 ? (
            rows.map((row, index) => {
              const selected = activeSelectedIndex === index
              const rowAddressNo = cleanDisplayValue((row as { addressNo?: string | number | null }).addressNo)
              const normalizedOwnerAddressNo = cleanDisplayValue(ownerAddressNo)
              const rowMaritalStatus = cleanDisplayValue((row as { maritalStatus?: string | number | null }).maritalStatus).toLocaleLowerCase('tr-TR')
              const rowDeathDate = cleanDisplayValue((row as { deathDate?: string | number | null }).deathDate)
              const hasAddressNoMismatch =
                tableName === 'person' &&
                Boolean(normalizedOwnerAddressNo) &&
                (!rowAddressNo || rowAddressNo !== normalizedOwnerAddressNo)
              const isMarriedPerson = tableName === 'person' && (rowMaritalStatus === '2' || rowMaritalStatus.includes('evli'))
              const hasDeathDate = tableName === 'person' && Boolean(rowDeathDate)
              const rowClass = selected
                ? 'bg-[#e6f3dd] outline outline-2 outline-[#6fb744]/60'
                : hasDeathDate
                  ? 'bg-slate-900 text-white'
                : isMarriedPerson
                  ? 'bg-red-100'
                : hasAddressNoMismatch
                  ? 'bg-blue-200'
                : highlight
                  ? 'bg-[#f1faed]'
                    : tableName === 'reports' && colorTone === 'violet'
                      ? index % 2 === 0 ? 'bg-violet-50/70' : 'bg-fuchsia-50/60'
                      : tableName === 'reports' && colorTone === 'cyan'
                        ? index % 2 === 0 ? 'bg-cyan-50/70' : 'bg-teal-50/60'
                        : tableName === 'reports' && colorTone === 'amber'
                          ? index % 2 === 0 ? 'bg-white' : 'bg-amber-50'
                          : index % 2 === 0
                            ? 'bg-white'
                            : 'bg-slate-50/60'
              const hoverClass =
                hasDeathDate && !selected
                  ? 'hover:bg-black'
                  : isMarriedPerson && !selected
                    ? 'hover:bg-red-200'
                    : hasAddressNoMismatch && !selected
                      ? 'hover:bg-blue-300'
                      : 'hover:bg-[#eaf7fd]'
              const cellTextClass = hasDeathDate && !selected ? 'text-white' : 'text-slate-900'

              return (
                <tr
                  key={index}
                  aria-selected={selected}
                  onClick={() => {
                    setSelectedIndex(index)
                    onRowSelect?.(row, index)
                  }}
                  onDoubleClick={() => onRowDoubleClick?.(row, index)}
                  onContextMenu={(event) => onRowContextMenu?.(event, row, index)}
                  className={`${rowClass} cursor-pointer transition-colors ${hoverClass}`}
                >
                  {orderedColumns.map((column) => {
                    const rawValue = row[column.key]
                    const columnName = String(column.key)
                    const rowType = cleanDisplayValue((row as { type?: string | number | null }).type)
                    const cashStageLabel =
                      tableName === 'requests' && columnName === 'stage' && rowType === 'Ayni/Nakdi'
                        ? findPredefinedOptions(predefinedValues, predefinedValueTitles, ['nakit asama', 'nakit asamasi', 'nakit durumu'])
                            .find((option) => option.id === String(rawValue))?.name
                        : null
                    // Kullanici istegi: "Müracaatlar" listesinde Nakit Yardımı
                    // (Ayni/Nakdi) satirlarinda "Yardım Başlangıç/Bitiş Tarihi"
                    // alanlari ANLAMSIZ (bunlar donemsel/sureli yardimlar
                    // icindir) - bos gosterilir. Ayrica "Durumu" (ham durum
                    // bilgisi/pill) Müracaatlar tablosunda HIC ISTENMIYOR -
                    // sutun HER ZAMAN "Gülkart" basligiyla gorunur: nakit
                    // yardimi satirlarinda basvuru sahibinin TC'sine kayitli
                    // bir Gülkart VARSA numarasi gosterilir (bkz.
                    // gulkartLookup, gulkartCardByTc), nakit DISINDAKI
                    // turlerde ve kayitli kart yoksa bos ("-") kalir.
                    const isNakitApplicationRow = tableName === 'requests' && rowType === 'Ayni/Nakdi'
                    const isRequestsStatusColumn = tableName === 'requests' && columnName === 'status'
                    const nakitGulkartCardNo = isNakitApplicationRow && isRequestsStatusColumn
                      ? gulkartLookup?.[cleanDisplayValue((row as { identityNumber?: string | number | null }).identityNumber)]
                      : undefined
                    const predefinedColumnName =
                      columnName === 'status' && (tableName === 'requests' || tableName === 'assistance')
                        ? 'ydurumu'
                        : columnName
                    const value =
                      isNakitApplicationRow && (columnName === 'startDate' || columnName === 'endDate')
                        ? ''
                      : isRequestsStatusColumn
                        ? (nakitGulkartCardNo || '')
                      : columnName === 'dosyaNo'
                        ? formatFileNo(rawValue as string | number | null)
                      : cashStageLabel
                        ? cashStageLabel
                      : tableName === 'person' && columnName === 'no'
                        ? String(index + 1)
                        : tableName === 'person' && columnName === 'maritalStatus'
                        ? getMaritalStatusDisplayLabel(predefinedValues, predefinedValueTitles, rawValue as string | number | null)
                        : tableName
                        ? getPredefinedValueLabel(
                            predefinedValues,
                            tableName,
                            predefinedColumnName,
                            rawValue,
                            predefinedValueTitles
                          ) ?? String(rawValue ?? '')
                        : String(rawValue ?? '')
                    const isPersonAddressColumn = tableName === 'person' && columnName === 'address'
                    // "Ödeme Açıklama" (ve benzeri uzun serbest metin) alani uzun
                    // oldugunda tek satirda whitespace-nowrap ile tabloyu asiri
                    // genisletiyor, "Yazdır" butonu ve digerlerini yatay kaydirma
                    // gerektirmeden gorulemez hale getiriyordu. Bu sutunlarda
                    // tek satir yerine en fazla 2 satira sarilsin, genislik
                    // sinirli kalsin diye ozel davraniyoruz.
                    const isWrappingLongTextColumn = tableName === 'assistance' && columnName === 'paymentDescription'
                    const cellClassName = [
                      // Rapor tablosunda (İnceleme Raporları vb.) "RAPOR" sutunundaki
                      // uzun/sarilan metin satiri cok uzatiyor - digger kisa sutunlar
                      // (SIRA NO, TARİH, KONU) "align-top" ile satirin en üstüne
                      // yapisip, altinda buyuk bir bosluk kalarak dengesiz duruyordu.
                      // Bu tabloda dikey ortalama (align-middle) ile kisa degerler
                      // satirin ortasinda, alan icinde ortali goruntuleniyor.
                      // Kullanici istegi: "Hanedeki Bireyler" (person) tablosunda
                      // satirlar arasi bosluk COK genisti - kutu boyu sabit
                      // kaldiginda (13 kisilik bir hanede) sadece ~11 satir
                      // sigiyor, geri kalani gormek icin kutuyu buyutmek
                      // gerekiyordu. Digerleri kadar genis "py-3" yerine, en
                      // sik satir araligi (isRequestTable ile ayni "py-1")
                      // kullanilarak DAHA FAZLA satir ayni yukseklige sigar -
                      // kutu tasan geri kalan bireyler icin (mevcut
                      // overflow-y-auto sayesinde) kaydirma cubugu ile
                      // gorulebilir kalir.
                      // Kullanici istegi (Eylul 2026): "Raporlar ve Tahkikatlar"
                      // satirlari "ic ice girmis gibi" gorunuyordu - kok neden:
                      // (1) uzun "Rapor" metni 5-6 satira sariyor ama "align-middle"
                      // kisa hucreleri (Tarih/Konu) bu blogun ORTASINA hizaliyordu,
                      // satir basi belirsizlesiyordu; (2) "leading-snug" + soluk
                      // "border-slate-100" ayrac, ozellikle yazi boyutu buyutulunce
                      // satirlari birbirine yapistiriyordu. Cozum: reports icin
                      // align-top + leading-normal + belirgin ayrac + biraz daha
                      // dikey bosluk.
                      // Kullanici istegi (Eylul 2026): Raporlar satirlari "ic
                      // ice giriyor, cirkin". Cozum: (1) tablo "border-separate
                      // + border-spacing-y" ile satirlar arasi GERCEK bosluk,
                      // (2) her satir kendi zebra zemininde ayri bir "kart"
                      // gibi (ilk/son hucre yuvarlak kose), (3) dikey dolgu
                      // "em" (yazi buyudukce orantili acilir), (4) yazi tipi
                      // ekranda kucuk metin icin ozel tasarlanmis Verdana
                      // (bkz. asagidaki style) -> harfler daha ferah.
                      // Kullanici istegi (2026-09-30, devam): "bu listeler de
                      // Nakit Yardımı listesi gibi Excel tarzında olsun,
                      // satır araları daralsın" - Hane Bilgileri/Müracaatlar/
                      // Yardımlar/Diğer Kurum Yardımları icin (reports HARIC,
                      // o zaten kendi "kart" tasarimini koruyor) dikey izgara
                      // cizgisi (border-r) eklendi ve en genis dikey dolgu
                      // ("py-3") daraltildi.
                      tableName === 'reports'
                        ? 'py-[1.05em] leading-[1.55] align-top border-y border-amber-200/80 first:border-l first:rounded-l-xl last:border-r last:rounded-r-xl'
                        : `border-b border-r border-slate-200 ${isCompactTable ? 'py-2.5 leading-snug' : isRequestTable ? 'py-1.5 leading-snug' : tableName === 'person' ? 'py-1 leading-snug' : 'py-1.5'} align-top`,
                      cellTextClass,
                      isWrappingLongTextColumn
                        ? 'whitespace-normal break-words max-w-[260px]'
                        // Kullanici istegi (Ekim 2026, 9. tur): "veriler
                        // sığmıyorsa alt satıra geçsin, aynı Rapor
                        // sütununda olduğu gibi" - Raporlar tablosunda
                        // (amber/violet TONU DAHIL, sadece "cyan"/Dış Kurum
                        // DEGIL) artik TUM sutunlar "report" sutunuyla AYNI
                        // sekilde sarar; eskiden burada SADECE "report"
                        // disindaki sutunlar (Sıra No, Tarih, Konu...)
                        // whitespace-nowrap'e ZORLANIYORDU (reportColumnClass'taki
                        // yeni "whitespace-normal" ile CATISIYORDU).
                        : tableName === 'reports'
                          ? 'whitespace-normal break-words'
                          : 'whitespace-nowrap',
                      tableName === 'person' ? 'text-[14px] sm:text-[12px] leading-snug' : '',
                      tableName === 'person' ? personCompactColumnClass(columnName) : isRequestTable ? 'px-2' : 'px-3',
                      reportColumnClass(columnName),
                      isPersonAddressColumn ? 'text-[14px] sm:text-[11px]' : '',
                      centeredShortValueColumnClass(columnName),
                      // Kullanici istegi: sutun eliyle daraltilabildigi icin
                      // (bkz. reorderTableId/table-fixed) icerik tasarsa bile
                      // komsu hucreye tasmasin, kesilip "..." ile gosterilsin.
                      reorderTableId ? 'overflow-hidden text-ellipsis' : '',
                    ].filter(Boolean).join(' ')

                    return (
                      <td
                        key={columnName}
                        className={cellClassName}
                        // Kullanici istegi (2026-09-16): "satirlar arasi cok
                        // dar, yazilar birbirine girmis" - KOK NEDEN: bu
                        // hucrenin fontSize'i --dy-fs (Tasarim Modu yazi
                        // boyutu kontrolu) ile oranli BUYUYUP KUCULUYORDU
                        // ama asagidaki ic <span>'in "leading-5" sinifi SABIT
                        // bir piksel yuksekligi (20px) dayatiyordu - yazi
                        // buyuyunce satir araligi ORANTILI BUYUMEDIGI icin
                        // satirlar ust uste biniyormus gibi gorunuyordu.
                        // Cozum: sabit "leading-5" KALDIRILDI (asagida), bu
                        // "lineHeight" (birimsiz oran, fontSize ile birlikte
                        // otomatik olcekleniyor) miras yoluyla ona uygulanir.
                        // Ayrica yazi tipi Verdana'dan (kullanici istegi) Arial'a
                        // cevrildi, boyut da daha sade/profesyonel durmasi icin
                        // 12px'ten 11px'e kucultuldu.
                        style={tableName === 'reports'
                          ? { fontSize: 'calc(11px * var(--dy-fs, 1))', fontFamily: 'Arial, "Segoe UI", system-ui, sans-serif', letterSpacing: '0.005em', lineHeight: 1.55 }
                          : undefined}
                      >
                        {columnName === 'status' && tableName === 'assistance' ? (
                          <span
                            className="inline-flex h-6 items-center justify-center whitespace-nowrap rounded-full border px-2 text-[10px] font-black uppercase tracking-wide"
                            style={getAssistanceStatusBadgeStyle(
                              rawValue as string | number | null,
                              isDgnAssistanceSource(String((row as { sourceTable?: string | null }).sourceTable || '')) ? 'dgn' : 'default',
                            )}
                          >
                            {value || '-'}
                          </span>
                        ) : columnName === 'status' && !isRequestsStatusColumn ? <StatusPill>{value}</StatusPill> : (
                          <span
                            className={[
                              tableName === 'reports' && columnName === 'report'
                                // Kullanici istegi (2026-09-16): burada SABIT
                                // "leading-5" (20px) KASITLI OLARAK YOK -
                                // ust hucredeki (td) birimsiz "lineHeight"
                                // buraya MIRAS yoluyla gecer ve fontSize
                                // (--dy-fs ile) buyuyup kuculdukce SATIR
                                // ARALIGI DA ORANTILI degisir (eskiden sabit
                                // pixel yukseklik, yazi buyuyunce satirlarin
                                // ust uste binmis gibi gorunmesine sebep
                                // oluyordu).
                                ? 'block whitespace-pre-wrap break-words'
                                // Kullanici istegi (Ekim 2026, 10. tur): "konu
                                // alanındaki veri uzun ama 2. satıra
                                // geçmediği için tam okunmuyor" - bu ic
                                // <span>, DIŞ hucre (td) sarma kurallarindan
                                // BAGIMSIZ kendi "whitespace-nowrap"ini
                                // tasiyordu (asil kesilmenin GERCEK kaynagi
                                // buydu) - Raporlar tablosunun TUM
                                // sutunlari icin (sadece "report" DEGIL)
                                // artik "report" sutunuyla AYNI sekilde sarar.
                                // "date" burada ISTISNA - kisa/sabit bicimli
                                // (13.05.2026) oldugu icin sarilirsa ortasindan
                                // bolunuyordu, o yuzden nowrap kalir.
                                : tableName === 'reports' && columnName !== 'date'
                                  ? 'block whitespace-pre-wrap break-words'
                                  : isWrappingLongTextColumn
                                    ? 'line-clamp-2 whitespace-normal break-words leading-5'
                                    : 'block whitespace-nowrap',
                              COPYABLE_COLUMNS.has(columnName) ? 'cursor-copy' : '',
                              copiedCellKey === `${index}-${columnName}` ? 'font-black text-emerald-600' : '',
                            ].filter(Boolean).join(' ')}
                            title={
                              copiedCellKey === `${index}-${columnName}`
                                ? 'Kopyalandı ✓'
                                : COPYABLE_COLUMNS.has(columnName) && value
                                  ? `${value} (kopyalamak için çift tıklayın)`
                                  : (value || '-')
                            }
                            onDoubleClick={COPYABLE_COLUMNS.has(columnName) ? () => void handleCellDoubleClick(`${index}-${columnName}`, value) : undefined}
                          >
                            {copiedCellKey === `${index}-${columnName}` ? 'Kopyalandı ✓' : (value || '-')}
                          </span>
                        )}
                      </td>
                    )
                  })}
                  {/* Kullanici istegi (2026-09-30, devam): "Yazdır" sutunu
                      TEKRAR EN SONA tasindi. */}
                  {renderRowAction && <td className="border-b border-r border-slate-200 px-2 py-1.5 text-center align-middle">{renderRowAction(row, index)}</td>}
                </tr>
              )
            })
          ) : (
            <tr>
              {/* Kullanici istegi (2026-09-21): "eğer veri boşsa ... 4 cm
                  olarak kalacak" - bu "kayit yok" satiri eskiden py-12
                  (96px dikey dolgu) kullaniyordu, bu tek basina disaridaki
                  min-h-[4cm] tabanini (151px) asip sekmeyi hep ~200px+
                  yapiyordu - veri GERCEKTEN bos olsa bile taban asiliyordu.
                  Sadece reserveScrollGutter (4cm tabanli sekmeler) icin
                  dolgu kucultuldu ki bos bir tablo GERCEKTEN 4cm'de kalsin;
                  reserveScrollGutter kullanmayan DIGER DataTable cagrilari
                  (bu 4cm kisitina tabi olmayanlar) eski, daha ferah
                  gorunumunu KORUR. */}
              <td colSpan={orderedColumns.length + (renderRowAction ? 1 : 0)} className={`px-3 text-center text-base font-bold text-slate-500 ${reserveScrollGutter ? 'py-3' : 'py-12'}`}>
                {emptyText ?? 'Kayıt bulunamadı'}
              </td>
            </tr>
          )}
        </tbody>
        {tableName === 'reports' && colorTone === 'cyan' && rows.length > 0 && (
          <tfoot className="sticky bottom-0 z-10 border-t-2 border-cyan-300 bg-cyan-50 text-cyan-950 shadow-[0_-4px_10px_rgba(8,145,178,0.12)]">
            <tr>
              {orderedColumns.map((column) => {
                const columnName = String(column.key)
                return (
                  <td key={columnName} className={`px-3 py-3 text-[12px] font-black ${reportColumnClass(columnName)}`}>
                    {columnName === 'amount' ? `TOPLAM: ${new Intl.NumberFormat('tr-TR', { maximumFractionDigits: 2 }).format(externalAidTotal)}` : ''}
                  </td>
                )
              })}
            </tr>
          </tfoot>
        )}
      </table>
    </div>
  )
}

function FamilyRegistryTable({
  rows,
  emptyText,
  onTransfer,
  canTransfer,
  ownerAddressNo,
  predefinedValues = DEFAULT_PREDEFINED_VALUES,
  predefinedValueTitles = DEFAULT_PREDEFINED_VALUE_TITLES,
  showActions = true,
  disabledTransferText = 'BİREYİ EKLE',
}: {
  rows: FamilyRegistryRow[]
  emptyText?: string
  onTransfer?: (row: FamilyRegistryRow) => void
  canTransfer?: boolean
  ownerAddressNo?: string
  predefinedValues?: PredefinedValuesMap
  predefinedValueTitles?: PredefinedValueTitlesMap
  showActions?: boolean
  disabledTransferText?: string
}) {
  const relationLabel = (value?: string) => {
    const cleanValue = cleanDisplayValue(value)
    if (!cleanValue) return '-'
    return getRelationshipDisplayLabel(predefinedValues, predefinedValueTitles, cleanValue)
  }

  const cellClassName = 'border-b border-slate-100 px-1.5 py-2.5 align-top text-[12px] font-bold text-slate-900'
  const fileInfoCellClassName = 'border-b border-r-2 border-amber-300 bg-amber-100 px-1.5 py-2.5 align-top text-[12px] font-black text-amber-950'
  const fileRelationCellClassName = 'border-b border-r-2 border-cyan-300 bg-cyan-100 px-1.5 py-2.5 align-top text-[12px] font-black text-cyan-950'
  const themedCellClassName = (theme: 'death' | 'married' | 'address' | 'default', fallbackClassName = cellClassName) => {
    if (theme === 'death') return 'border-b border-slate-800 bg-slate-950 px-1.5 py-2.5 align-top text-[12px] font-bold text-white'
    if (theme === 'married') return 'border-b border-red-200 bg-red-100 px-1.5 py-2.5 align-top text-[12px] font-bold text-red-950'
    if (theme === 'address') return 'border-b border-blue-200 bg-blue-100 px-1.5 py-2.5 align-top text-[12px] font-bold text-blue-950'
    return fallbackClassName
  }

  return (
    <div className="overflow-x-auto rounded-lg border border-[#D7DEE3] bg-white shadow-inner">
      <table className="w-full min-w-[1320px] table-auto border-collapse text-left">
        <thead className="bg-[#1E2A38] text-[10px] font-extrabold uppercase leading-tight text-white">
          <tr>
            {showActions && <th className="sticky left-0 z-20 w-[118px] min-w-[118px] border-b border-[#2A3B4D] bg-[#2A3B4D] px-2 py-2.5 text-center text-white shadow-[3px_0_6px_rgba(15,23,42,0.12)]">İşlem</th>}
            <th className="w-[82px] border-b border-r-2 border-amber-300 bg-amber-300 px-1.5 py-2.5 text-amber-950">Kayıtlı Dosya</th>
            <th className="w-[82px] border-b border-r-2 border-cyan-300 bg-cyan-300 px-1.5 py-2.5 text-cyan-950">Dosya Yak.</th>
            <th className="w-9 border-b border-white/20 px-1 py-2.5 text-center">#</th>
            <th className="w-[66px] border-b border-white/20 px-1.5 py-2.5">NVİ Yak.</th>
            <th className="w-[102px] border-b border-white/20 px-1.5 py-2.5">TC Kimlik No</th>
            <th className="w-[76px] border-b border-white/20 px-1.5 py-2.5">Adı</th>
            <th className="w-[76px] border-b border-white/20 px-1.5 py-2.5">Soyadı</th>
            <th className="w-[78px] border-b border-white/20 px-1.5 py-2.5">D. Tarihi</th>
            <th className="w-[70px] border-b border-white/20 px-1.5 py-2.5">D. Yeri</th>
            <th className="w-[78px] border-b border-white/20 px-1.5 py-2.5">Baba Adı</th>
            <th className="w-[78px] border-b border-white/20 px-1.5 py-2.5">Ana Adı</th>
            <th className="w-[58px] border-b border-white/20 px-1.5 py-2.5">Cinsiyet</th>
            <th className="w-[64px] border-b border-white/20 px-1.5 py-2.5">Medeni</th>
            <th className="w-[78px] border-b border-white/20 px-1.5 py-2.5">Ölüm Tarihi</th>
            <th className="w-[94px] border-b border-white/20 px-1.5 py-2.5">Adres No</th>
            <th className="w-[250px] border-b border-white/20 px-1.5 py-2.5">Adres</th>
          </tr>
        </thead>
        <tbody>
          {rows.length > 0 ? (
            rows.map((row, index) => {
              const existingFileText = row.existingFileId
                ? (row.existingFileNo || row.existingFileId)
                : '-'
              const maritalStatusLabel = getMaritalStatusDisplayLabel(predefinedValues, predefinedValueTitles, row.maritalStatus)
              const rowAddressNo = cleanDisplayValue(row.existingAddressNo)
              const normalizedOwnerAddressNo = cleanDisplayValue(ownerAddressNo)
              const rowMaritalStatus = cleanDisplayValue(row.maritalStatus).toLocaleLowerCase('tr-TR')
              const rowDeathDate = cleanDisplayValue(row.deathDate) || cleanDisplayValue(row.existingDeathDate)
              const hasDeathDate = Boolean(rowDeathDate)
              const isMarriedPerson = rowMaritalStatus === '2' || rowMaritalStatus.includes('evli')
              const hasAddressNoMismatch = Boolean(normalizedOwnerAddressNo && (!rowAddressNo || rowAddressNo !== normalizedOwnerAddressNo))
              const rowTheme = hasDeathDate
                ? 'death'
                : isMarriedPerson
                  ? 'married'
                  : hasAddressNoMismatch
                    ? 'address'
                    : 'default'
              const canMoveRow = Boolean(canTransfer && !row.isInCurrentFile)

              return (
                <tr key={`${row.identityNumber}-${row.firstName}-${row.lastName}-${index}`} className={index % 2 === 0 ? 'bg-white' : 'bg-slate-50/60'}>
                  {showActions && (
                    <td className="sticky left-0 z-10 w-[118px] min-w-[118px] border-b border-emerald-200 bg-emerald-50 px-2 py-2.5 text-center align-top shadow-[3px_0_6px_rgba(15,23,42,0.08)]">
                      {row.isInCurrentFile ? (
                        <span className="inline-flex w-max rounded-lg bg-emerald-200 px-2 py-1 text-[11px] font-black text-emerald-800">EKLİ</span>
                      ) : (
                        <button
                          type="button"
                          onClick={() => onTransfer?.(row)}
                          disabled={!canMoveRow}
                          className="inline-flex w-max max-w-none items-center justify-center whitespace-nowrap rounded-lg bg-[#6fb744] px-2.5 py-1.5 text-[10px] font-black text-white shadow-sm hover:bg-[#5da237] disabled:cursor-not-allowed disabled:bg-slate-300"
                        >
                          {canTransfer ? 'BİREYİ EKLE' : disabledTransferText}
                        </button>
                      )}
                    </td>
                  )}
                  <td className={fileInfoCellClassName}>
                    <span className={row.isInCurrentFile ? 'rounded-lg bg-emerald-100 px-2 py-1 text-emerald-700' : ''} title={existingFileText}>
                      {existingFileText}
                    </span>
                  </td>
                  <td className={fileRelationCellClassName}>{row.existingBeneficiaryId ? relationLabel(row.existingRelation) : '-'}</td>
                  <td className={themedCellClassName(rowTheme)}>{index + 1}</td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={relationLabel(row.relation)}>{relationLabel(row.relation)}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.identityNumber}>{row.identityNumber || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.firstName}>{row.firstName || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.lastName}>{row.lastName || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.birthDate}>{row.birthDate || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.birthPlace}>{row.birthPlace || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.fatherName}>{row.fatherName || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.motherName}>{row.motherName || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.gender}>{row.gender || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={maritalStatusLabel}>{maritalStatusLabel}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className={`block truncate ${hasDeathDate ? 'font-black text-rose-300' : ''}`} title={rowDeathDate || '-'}>{rowDeathDate || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.existingAddressNo || '-'}>{row.existingAddressNo || '-'}</span></td>
                  <td className={themedCellClassName(rowTheme)}><span className="block truncate" title={row.existingAddress || '-'}>{row.existingAddress || '-'}</span></td>
                </tr>
              )
            })
          ) : (
            <tr>
              <td colSpan={showActions ? 16 : 15} className="px-3 py-12 text-center text-base font-bold text-slate-500">
                {emptyText ?? 'Kayıt bulunamadı'}
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  )
}

// Uygulama http:// (guvenli olmayan origin) uzerinden de calisiyor - bu
// durumda navigator.clipboard bazi taraycilarda hic mevcut olmayabilir
// (kamera erisiminde yasandigi gibi). Once modern Clipboard API denenir,
// calismazsa/yoksa eski execCommand('copy') yontemine (guvenli context
// gerektirmez) dusulur.
async function copyTextToClipboard(text: string): Promise<boolean> {
  if (!text) return false

  if (navigator.clipboard && window.isSecureContext) {
    try {
      await navigator.clipboard.writeText(text)
      return true
    } catch {
      // asagidaki eski yonteme dus
    }
  }

  try {
    const textarea = document.createElement('textarea')
    textarea.value = text
    textarea.style.position = 'fixed'
    textarea.style.top = '-1000px'
    textarea.style.opacity = '0'
    document.body.appendChild(textarea)
    textarea.focus()
    textarea.select()
    const success = document.execCommand('copy')
    document.body.removeChild(textarea)
    return success
  } catch {
    return false
  }
}

function Field({ label, value, copyable = false, callable = false }: { label: string; value: string; copyable?: boolean; callable?: boolean }) {
  const [justCopied, setJustCopied] = useState(false)

  const handleDoubleClick = async () => {
    if (!copyable || !value) return
    const success = await copyTextToClipboard(value)
    if (success) {
      setJustCopied(true)
      window.setTimeout(() => setJustCopied(false), 1200)
    }
  }

  // Kullanici istegi: tarayici yakinlastirma/uzaklastirma (zoom) yapildiginda
  // bu kutular birbirine gore ORANTISIZ buyuyup kucculuyor, gorunum
  // bozuluyordu. Iki ayri kok sebep tespit edilip DUZELTILDI:
  //  1) Etiket sutunu genisligi ekran genisligine gore IKI FARKLI deger
  //     (112px / sm: 124px) arasinda degisiyordu - tarayici zoom'u sayfanin
  //     "efektif" CSS-piksel genisligini degistirdigi icin, zoom sirasinda
  //     bazi kutular bu esigi FARKLI zoom seviyelerinde asip diger
  //     kutulardan BAGIMSIZ sekilde "ziplayarak" genislik degistiriyordu.
  //     Tek, sabit bir genislik (124px, artik ekran boyutundan bagimsiz)
  //     kullanilarak bu ziplama tamamen ortadan kaldirildi.
  //  2) Deger kismi bir <input> (tarayicinin kendi/native form kontrolu)
  //     idi - native form kontrolleri, yanindaki duz <span> etiketten
  //     FARKLI bir cizim (rendering) yolu izler ve kesirli zoom
  //     yuzdelerinde (ör. %90, %110, %133) bu ikisi arasinda piksel
  //     hizalama sapmasi/bulaniklik olusabiliyordu. Salt-okunur bir
  //     goruntuleme alani oldugu icin islevsel bir kayip olmadan <input>
  //     yerine ayni gorunumde duz bir <div> kullanildi - artik etiket ve
  //     deger AYNI turde kutu oldugu icin her zoom seviyesinde birebir
  //     ayni sekilde olceklenip hizali kaliyor.
  // Kullanici istegi (Ekim 2026): "dosya-yonetimi-redesign" referans
  // gorseline uygun sade alan gorunumu - eski "kutulu, sol tarafi renkli
  // etiket hucresi" grid yapisi yerine referanstaki gibi ETIKET USTTE
  // (kucuk, gri, buyuk harf) / DEGER ALTTA (koyu, yari-kalin), kenarliksiz,
  // ince alt cizgili duz bir satir. Davranis (cift tiklayinca kopyalama,
  // "Kopyalandı" geri bildirimi, print gorunumu) AYNEN korunuyor.
  return (
    <label
      onDoubleClick={handleDoubleClick}
      title={copyable ? 'Kopyalamak için çift tıklayın' : (value || undefined)}
      className={`group flex min-w-0 flex-col gap-0.5 border-b py-1.5 transition-colors print:border-slate-300 ${copyable ? 'cursor-copy' : ''} ${justCopied ? 'border-emerald-300' : 'border-[#E2E5DE] hover:border-teal-200'}`}
    >
      <span className="truncate text-[12.5px] font-bold uppercase tracking-wide text-[#3A4A55] print:text-slate-800">
        {label}
      </span>
      {/* Hata raporu (2026-09-12): "mobilde Kişi Bilgileri'ndeki yazılar
          diğerlerine göre çok büyük duruyor" - kok neden, bu deger metninin
          MOBILDE de (masaustuyle ayni ruhta ama olcegi) 16px font-black
          olmasiydi - sayfadaki geri kalan her sey (etiketler, butonlar,
          diger panellerin metinleri) 10-14px bandindayken, 10 satirlik bu
          alanin HER satirinin degeri belirgin sekilde daha buyuk/kalin
          kaliyor, "duzensiz" gorunuyordu. Mobilde 14px'e cekildi (masaustu -
          sm: - 18px aynen korunuyor, orada boyle bir sikayet yok). */}
      <span className="flex min-w-0 items-center gap-1.5">
        <span className={`min-w-0 truncate text-[13px] font-black leading-tight sm:text-[18px] print:text-black ${justCopied ? 'text-emerald-700' : 'text-black'}`}>
          {justCopied ? 'Kopyalandı ✓' : (value || '—')}
        </span>
        {/* Kullanici istegi (2026-10-08): "mobil tarafta telefon no'nun yanina
            ara iconu ekleyelim, basinca direk arama ekranina yonlendirsin" -
            sadece mobilde (callable=isDosyaYonetimiMobile ile cagiran taraftan
            kontrol edilir) ve deger varken gorunur, tel: linki native arama
            ekranini acar. */}
        {callable && value && (
          <a
            href={`tel:${value}`}
            onClick={(event) => event.stopPropagation()}
            onDoubleClick={(event) => event.stopPropagation()}
            title="Ara"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-emerald-300 bg-emerald-50 text-emerald-700 print:hidden"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="h-3.5 w-3.5">
              <path d="M3 5.5C3 4.67 3.67 4 4.5 4h2.6c.5 0 .93.34 1.04.82l.9 3.6c.1.4-.03.82-.33 1.1l-1.5 1.37a12.5 12.5 0 0 0 5.9 5.9l1.38-1.5c.28-.3.7-.43 1.1-.33l3.6.9c.47.11.81.54.81 1.04v2.6c0 .83-.67 1.5-1.5 1.5h-1C9.4 21 3 14.6 3 6.5v-1Z" />
            </svg>
          </a>
        )}
      </span>
    </label>
  )
}

function ExistingPersonRecordCard({
  status,
  relationLabel,
  predefinedValues = DEFAULT_PREDEFINED_VALUES,
  predefinedValueTitles = DEFAULT_PREDEFINED_VALUE_TITLES,
}: {
  status: PersonFileStatus
  relationLabel: string
  predefinedValues?: PredefinedValuesMap
  predefinedValueTitles?: PredefinedValueTitlesMap
}) {
  // Kullanici istegi (Ekim 2026): "bu alan cok genis/cok yer kapliyor, daha
  // dar ve profesyonel olsun, gerekirse ayri bir bildirim penceresinden
  // islem yapilsin" - varsayilan GORUNUM artik tek satirlik ozet bir uyari
  // cubugu; "Detaylar" butonuna basilinca tam bilgi karti acilir/kapanir.
  const [isDetailsOpen, setIsDetailsOpen] = useState(false)
  const isOwnFile = status.isInCurrentFile
  const toneClass = isOwnFile ? 'border-emerald-300 bg-emerald-50' : 'border-amber-300 bg-amber-50'
  const toneTextClass = isOwnFile ? 'text-emerald-800' : 'text-amber-800'
  const toneButtonClass = isOwnFile
    ? 'border-emerald-300 bg-white text-emerald-700 hover:bg-emerald-100'
    : 'border-amber-300 bg-white text-amber-700 hover:bg-amber-100'

  const fields = [
    ['Kayıtlı Dosya', status.fileNo || status.fileId || '-'],
    ['Eski Yakınlık', relationLabel],
    ['Adı Soyadı', `${status.firstName} ${status.lastName}`.trim() || '-'],
    ['Anne / Baba', [status.motherName, status.fatherName].filter(Boolean).join(' / ') || '-'],
    ['Doğum', [status.birthDate, status.birthPlace].filter(Boolean).join(' / ') || '-'],
    ['Cinsiyet / Medeni', [status.gender, getMaritalStatusDisplayLabel(predefinedValues, predefinedValueTitles, status.maritalStatus)].filter((value) => value && value !== '-').join(' / ') || '-'],
    ['Telefon', status.phone || '-'],
    ['Adres No', status.addressNo || '-'],
    ['Adres', status.address || '-'],
  ]

  const summaryName = `${status.firstName} ${status.lastName}`.trim() || '-'
  const summaryFile = status.fileNo || status.fileId || '-'

  return (
    <div className={`overflow-hidden rounded-lg border ${toneClass}`}>
      <div className="flex flex-wrap items-center justify-between gap-2 px-3 py-2">
        <div className={`flex min-w-0 items-center gap-2 text-[11px] font-black ${toneTextClass}`}>
          <ActionIcon name="idCard" className="h-3.5 w-3.5 shrink-0" />
          <span className="truncate uppercase">
            {isOwnFile ? 'Kişinin mevcut kaydı' : 'Başka dosyada kayıtlı'}:
          </span>
          <span className="truncate normal-case">{summaryName} · Dosya {summaryFile} · {relationLabel}</span>
        </div>
        <button
          type="button"
          onClick={() => setIsDetailsOpen((current) => !current)}
          className={`shrink-0 rounded-lg border px-2 py-1 text-[10px] font-black uppercase transition ${toneButtonClass}`}
        >
          {isDetailsOpen ? 'Kapat' : 'Detaylar'}
        </button>
      </div>
      {isDetailsOpen && (
        <div className={`border-t px-3 py-2.5 ${toneClass}`}>
          <div className="grid gap-2 md:grid-cols-3">
            {fields.map(([label, value]) => (
              <div key={label} className="rounded-lg border border-white/80 bg-white/80 px-2 py-1.5">
                <div className="text-[9px] font-black uppercase text-slate-400">{label}</div>
                <div className="truncate text-xs font-bold text-slate-800" title={value}>{value}</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

function SegmentedTabs<T extends string>({
  tabs,
  value,
  onChange,
}: {
  tabs: { id: T; label: string; count?: number }[]
  value: T
  onChange: (value: T) => void
}) {
  return (
    <div className="border-b border-slate-200 bg-white px-4 pt-3 print:hidden">
      <div className="flex gap-1 overflow-x-auto">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            onClick={() => onChange(tab.id)}
            className={`whitespace-nowrap rounded-t-lg border border-b-0 px-4 py-2.5 text-base font-bold transition ${
              value === tab.id
                ? 'border-[#9bd36f] bg-[#f1faed] text-[#3f7f28]'
                : 'border-transparent text-slate-500 hover:bg-[#f7fcff] hover:text-[#005f95]'
            }`}
          >
            {tab.label}
            {typeof tab.count === 'number' && (
              <span className="ml-2 rounded-full bg-white px-2 py-0.5 text-xs font-extrabold text-[#4f8f2f]">{tab.count}</span>
            )}
          </button>
        ))}
      </div>
    </div>
  )
}

