const DOCUMENTS_WORKSPACE_STORAGE_KEY = 'netsosyal:documents-workspace'

interface DocumentsWorkspaceFileRef {
  fileId: string
  cardNo: string
}

// ONEMLI: Bu ONCEDEN dogrudan window.history.replaceState(...) kullaniyordu -
// bu SADECE tarayicinin adres cubugunu temizliyordu, Next.js'in kendi
// yonlendirme (router) durumunu (usePathname/useSearchParams) HABERDAR
// ETMIYORDU. Sonuc: TabContext (bkz. lib/context/TabContext.tsx), "Dosya
// Yönetimi" sekmesinin path'ini hala "communication=open&openAt=..."
// PARAMETRELERINI TASIYOR sanip sekmeye HER TIKLANDIGINDA bu eski
// parametrelerle yeniden yonlendiriyor, bu da Kurum Ici Haberlesme
// penceresinin KENDILIGINDEN tekrar tekrar acilmasina sebep oluyordu
// (kullanicinin bildirdigi hata tam olarak buydu). router.replace(...)
// kullanmak, Next'in reaktif durumunu da DOGRU sekilde guncelleyip bu
// sekme kirlenmesini onluyor.
function clearCommunicationOpenParams(router: ReturnType<typeof useRouter>) {
  if (typeof window === 'undefined') return
  const url = new URL(window.location.href)
  url.searchParams.delete('communication')
  url.searchParams.delete('messageId')
  url.searchParams.delete('openAt')
  const query = url.searchParams.toString()
  router.replace(`${url.pathname}${query ? `?${query}` : ''}${url.hash}`, { scroll: false })
}

interface DocumentsWorkspaceState {
  openFiles: DocumentsWorkspaceFileRef[]
  activeFileId: string
}

function readDocumentsWorkspaceState(): DocumentsWorkspaceState | null {
  if (typeof window === 'undefined') {
    return null
  }

  try {
    const rawState = window.sessionStorage.getItem(DOCUMENTS_WORKSPACE_STORAGE_KEY)
    if (!rawState) {
      return null
    }

    const parsedState = JSON.parse(rawState) as { openFiles?: unknown[]; activeFileId?: unknown }
    const openFiles = Array.isArray(parsedState.openFiles)
      ? parsedState.openFiles
          .map((file) => {
            if (!file || typeof file !== 'object') return null
            const record = file as Record<string, unknown>
            const fileId = String(record.fileId ?? '').trim()
            const cardNo = String(record.cardNo ?? record.fileNo ?? '').trim()
            return fileId || cardNo ? { fileId, cardNo } : null
          })
          .filter((file): file is DocumentsWorkspaceFileRef => Boolean(file))
      : []

    return {
      openFiles,
      activeFileId: typeof parsedState.activeFileId === 'string' ? parsedState.activeFileId : '',
    }
  } catch {
    return null
  }
}

function cleanDisplayValue(value?: string | number | null) {
  if (value === null || value === undefined) return ''
  const text = String(value).trim()
  return text === '-' ? '' : text
}

function resolvePredefinedOptionId(options: PredefinedValue[], value?: string | number | null) {
  const text = cleanDisplayValue(value)
  if (!text) return ''

  const normalizedText = normalizeLookupKey(text)
  const match = options.find((option) => (
    option.id === text ||
    normalizeLookupKey(option.id) === normalizedText ||
    normalizeLookupKey(option.name) === normalizedText
  ))

  return match?.id ?? text
}

function escapeHtml(value?: string | number | null) {
  return cleanDisplayValue(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;')
}

function normalizePrinterConfigKey(value?: string | number | null) {
  return cleanDisplayValue(value)
    .replace(/\s+/g, ' ')
    .trim()
    .toLocaleLowerCase('tr-TR')
}

function readClientPrinterConfig(): ClientPrinterConfig {
  try {
    const rawConfig = window.localStorage.getItem(clientPrinterConfigStorageKey)
    return rawConfig ? (JSON.parse(rawConfig) as ClientPrinterConfig) : {}
  } catch {
    return {}
  }
}

function readClientPrinterPreferences() {
  try {
    const rawPreferences = window.localStorage.getItem(clientPrinterPreferencesStorageKey)
    return rawPreferences ? (JSON.parse(rawPreferences) as Record<string, string>) : {}
  } catch {
    return {}
  }
}

function resolveClientPrinterNameForDesign(design: FormDesign) {
  const preferences = readClientPrinterPreferences()
  const config = readClientPrinterConfig()
  const manualPrinter = preferences[design.id]?.trim()

  if (manualPrinter) return manualPrinter

  const normalizedDesignName = normalizePrinterConfigKey(design.name)
  const designPrinter = Object.entries(config.designPrinters || {}).find(([designName]) => normalizePrinterConfigKey(designName) === normalizedDesignName)?.[1]?.trim()

  if (designPrinter) return designPrinter

  return ''
}

function buildAgentPrintHtml(title: string, innerHtml: string, design: FormDesign) {
  const widthMm = Number(design.width || 80)
  const heightMm = Number(design.height || 40)
  const isFileApplicationDesign = normalizePrinterConfigKey(design.linkedAssistance) === normalizePrinterConfigKey('Dosya')
  const useExactPageSize = design.type !== 'a4' || isFileApplicationDesign
  const paperWidthMm = isFileApplicationDesign ? (widthMm > heightMm ? 297 : 210) : widthMm
  const paperHeightMm = isFileApplicationDesign ? (widthMm > heightMm ? 210 : 297) : heightMm
  const fileFormScale = isFileApplicationDesign
    ? Math.min(1, paperWidthMm / Math.max(1, widthMm), paperHeightMm / Math.max(1, heightMm))
    : 1
  const pageSize = useExactPageSize ? `${paperWidthMm}mm ${paperHeightMm}mm` : 'auto'
  const fixedPageStyle = useExactPageSize
    ? design.type === 'a4'
      ? `width: ${paperWidthMm}mm; min-width: ${paperWidthMm}mm; max-width: ${paperWidthMm}mm; min-height: ${paperHeightMm}mm; overflow: visible;`
      : `width: ${widthMm}mm; min-width: ${widthMm}mm; max-width: ${widthMm}mm; height: ${heightMm}mm; min-height: ${heightMm}mm; max-height: ${heightMm}mm; overflow: hidden;`
    : ''

  return `
    <!doctype html>
    <html>
      <head>
        <meta charset="utf-8" />
        <meta http-equiv="X-UA-Compatible" content="IE=edge" />
        <title>${escapeHtml(title)}</title>
        <style>
          @page { size: ${pageSize}; margin: 0; }
          * { box-sizing: border-box; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
          html, body { margin: 0 !important; padding: 0 !important; ${fixedPageStyle} background: #fff; color: #000; font-family: Arial, Helvetica, sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
          body > * { margin-left: 0 !important; margin-top: 0 !important; }
          .relative { position: relative; }
          .absolute { position: absolute; }
          .pointer-events-none { pointer-events: none; }
          .bg-white { background: #fff; }
          .bg-slate-950 { background: #020617; }
          .bg-slate-50 { background: #f8fafc; }
          .border { border: 1px solid #e2e8f0; }
          .border-none { border: 0; }
          .border-b { border-bottom: 1px solid #e2e8f0; }
          .border-dashed { border-style: dashed; }
          .last\\:border-b-0:last-child { border-bottom: 0; }
          .overflow-hidden { overflow: hidden; }
          .leading-tight { line-height: 1.25; }
          .break-words { overflow-wrap: break-word; }
          .whitespace-nowrap { white-space: nowrap; }
          .flex { display: flex; }
          .flex-col { flex-direction: column; }
          .items-center { align-items: center; }
          .gap-1 { gap: 0.25rem; }
          .flex-1 { flex: 1 1 0%; }
          .w-full { width: 100%; }
          .h-full { height: 100%; }
          .h-auto { height: auto; }
          .object-contain { object-fit: contain; }
          .agent-print-root {
            margin: 0 !important;
            padding: 0 !important;
            transform-origin: top left;
            zoom: ${fileFormScale};
          }
          .text-\\[10px\\] { font-size: 10px; }
          .text-\\[8px\\] { font-size: 8px; }
          .truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
          .text-center { text-align: center; }
          .min-h-\\[2rem\\] { min-height: 2rem; }
          .min-w-\\[3rem\\] { min-width: 3rem; }
          .min-h-\\[3rem\\] { min-height: 3rem; }
          .bg-\\[repeating-linear-gradient\\(90deg\\2c black\\2c black_2px\\2c transparent_2px\\2c transparent_4px\\)\\] {
            background: repeating-linear-gradient(90deg, black, black 2px, transparent 2px, transparent 4px);
          }
        </style>
      </head>
      <body><div class="agent-print-root">${innerHtml}</div></body>
    </html>
  `
}

function displayDateToInputDate(value?: string | null) {
  const text = cleanDisplayValue(value)
  if (!text) return ''

  const parts = text.split('.')
  if (parts.length === 3) {
    const [day, month, year] = parts
    return `${year.padStart(4, '0')}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`
  }

  return text
}

// Kullanici istegi (2026-09-30): "Dönem Bilgisi" sutununda Gıda Bankası/
// Destek Paketi gibi turler HAM "donem" degerini (ör. "Eylül" - o an
// odenen TAKVIM AYI, onay is akisinin ANAHTARI, DOKUNULMAMALI) gosteriyordu,
// Ekmek ise KENDI "donemadi/donemstr" alaninda zaten hazir bir SURE metni
// ("1 Ay") tutuyordu. Kullanici TUM turlerde Ekmek'teki gibi "kaç ay süre
// ile verildiği" gorunsun istedi. Ham "periodInfo"/"donem" DEGERI
// (approval-requests eslestirmesinde KULLANILAN bir anahtar oldugu icin)
// DEGISTIRILMEDI - bunun yerine baslangic/bitis tarihinden SADECE
// GORUNTULEME icin bir sure hesaplanir (bkz. displayedAssistance ->
// periodDurationDisplay, AssistanceRow.periodDurationDisplay).
function formatPeriodDurationInMonths(startDisplay?: string | null, endDisplay?: string | null) {
  const start = displayDateToInputDate(startDisplay)
  const end = displayDateToInputDate(endDisplay)
  if (!start || !end) return null

  const [startYear, startMonth, startDay] = start.split('-').map(Number)
  const [endYear, endMonth, endDay] = end.split('-').map(Number)
  if (!startYear || !startMonth || !endYear || !endMonth) return null

  let months = (endYear - startYear) * 12 + (endMonth - startMonth)
  if (endDay < startDay) months -= 1
  months = Math.max(1, months)
  return `${months} Ay`
}

// "Yazdır" butonunun rengini/durumunu belirler - Gıda Bankası, Destek
// Paketi ve Dönem Dışı Gıda DISINDAKI tum turler icin buton her zaman
// yesil (mevcut/eski davranis). Bu uc tur icin:
//  - Dönem Dışı Gıda: odeme penceresi kavrami yok, TEK sart onaylanmis
//    olmasi (bkz. Ayarlar > Yetkili Personeller).
//  - Gıda Bankası / Destek Paketi: bugun odeme penceresi icindeyse YEŞİL,
//    degilse (henuz baslamadi/suresi gecti) SARI - onaylanmışsa pencere
//    disinda olsa bile YEŞİL (bkz. handlePrintAssistance).
type PrintButtonState = { needsApproval: boolean; isGreen: boolean; isPending: boolean }

function getPrintButtonState(row: AssistanceRow | ApplicationRow): PrintButtonState {
  const sourceTable = 'sourceTable' in row ? row.sourceTable : undefined
  const isDonemDisiGida = sourceTable === 'yrd_ddgidadosyali'
  const isPaymentWindowType = sourceTable === 'yrd_gidabankasi' || sourceTable === 'yrd_destekpaketi'

  if (!isDonemDisiGida && !isPaymentWindowType) {
    return { needsApproval: false, isGreen: true, isPending: false }
  }

  const isPending = row.approvalStatus === 'pending'
  const isApproved = row.approvalStatus === 'approved'

  if (isDonemDisiGida) {
    return { needsApproval: true, isGreen: isApproved, isPending }
  }

  if (isApproved) return { needsApproval: true, isGreen: true, isPending }

  const assistanceRow = row as AssistanceRow
  const paymentStartDate = displayDateToInputDate(assistanceRow.paymentStartDate)
  const paymentEndDate = displayDateToInputDate(assistanceRow.paymentEndDate)
  const today = getTodayInputDate()
  const withinWindow = Boolean(paymentStartDate) && Boolean(paymentEndDate) && today >= paymentStartDate && today <= paymentEndDate

  return { needsApproval: true, isGreen: withinWindow, isPending }
}

// Kullanici istegi: "Yazdır" ve "Onaya Gönder" AYRI İKİ BUTON olarak
// duruyordu (biri satirin ana aksiyonu, digeri onun ALTINDA kucuk bir
// pill) - kullanici bunu TEK BUTONA indirmemizi istedi: onay
// gerekmiyorsa/zaten onaylanmissa buton YESIL (dolu) "Yazdır" olarak durur
// ve tiklaninca yazdirir; onay gerekiyor ve henuz istenmemisse buton TAM
// SARI (dolu arkaplan, Yazdır butonuyla ayni dolu stil) "Onaya Gönder"
// olarak durur ve tiklaninca onay talebi gonderir; talep gonderilip
// BEKLENIYORSA buton acik sari "Onay Bekliyor" olur ve tiklaninca (geri
// almak icin) talebi iptal eder; personel onaylayinca printState.isGreen
// true olur ve buton otomatik olarak YESIL "Yazdır"a DONER - boylece ayni
// buton, durumuna gore rol degistirir, ikinci bir buton/pill HIC gerekmez.
function PrintOrApprovalButton({
  printState,
  printLabel,
  onPrint,
  onRequestApproval,
  onCancelApproval,
}: {
  printState: PrintButtonState
  printLabel: string
  onPrint: (event: React.MouseEvent) => void
  onRequestApproval: (event: React.MouseEvent) => void
  onCancelApproval: (event: React.MouseEvent) => void
}) {
  // Kullanici istegi (2026-09-30, CANLI ekran goruntusuyle): "Onaya Gönder"
  // butonu alanin (sutunun) dar olmasi yuzunden metni ALT SATIRA sariyor,
  // ama buton yuksekligi SABIT (h-8) oldugundan ikinci satir KESILIYORDU.
  // Cozum: metin ARTIK ASLA sarmiyor (whitespace-nowrap) ve yukseklik
  // sabit degil min-height (butonun kendi genisligi, gerekirse sutunun
  // "min-w" degerinden daha genis olarak) buyuyebiliyor - boylece metin
  // HER ZAMAN tek satirda, tam okunur sekilde sigar.
  // Kullanici istegi (devam): "butonlar çok büyük duruyor, DURUMU
  // rozetiyle AYNI boyutta olsun" - kok neden: "min-h-6" bir TABAN
  // (minimum) degeriydi, icerik (ikon+yazi+dikey dolgu) bunu asip butonun
  // DURUMU rozetinden (StatusPill, SABIT h-6) daha uzun boy almasina yol
  // aciyordu. Artik buton da SABIT h-6 kullanir (StatusPill ile BIREBIR
  // ayni yukseklik/dolgu/yazi boyutu) - ikon kaldirildi (h-6 icinde ikon +
  // yazi rahat sigmiyordu), buton artik SADECE rozetle ozdes bir hap.
  if (!printState.needsApproval || printState.isGreen) {
    return (
      <button
        type="button"
        onClick={onPrint}
        className="inline-flex h-6 shrink-0 items-center justify-center whitespace-nowrap rounded-full border border-emerald-700 bg-emerald-600 px-2 text-[10px] font-black uppercase text-white shadow-md shadow-emerald-200 transition hover:bg-emerald-700"
        title={printLabel}
      >
        Yazdır
      </button>
    )
  }

  if (printState.isPending) {
    return (
      <button
        type="button"
        onClick={onCancelApproval}
        className="inline-flex h-6 shrink-0 items-center justify-center whitespace-nowrap rounded-full border border-amber-300 bg-amber-50 px-2 text-[10px] font-black uppercase text-amber-700 shadow-sm transition hover:bg-amber-100"
        title="Onay bekleniyor - gönderdiğiniz talebi iptal etmek için tıklayın"
      >
        Onay Bekliyor
      </button>
    )
  }

  return (
    <button
      type="button"
      onClick={onRequestApproval}
      className="inline-flex h-6 shrink-0 items-center justify-center whitespace-nowrap rounded-full border border-amber-600 bg-amber-500 px-2 text-[10px] font-black uppercase text-white shadow-md shadow-amber-200 transition hover:bg-amber-600"
      title="Bu kaydın yazdırılabilmesi için yetkili personelden onay isteyin"
    >
      Onaya Gönder
    </button>
  )
}

// "Yardım Hareketleri" modalindeki her yardım türü sekmesine kendi rengini
