const AID_TYPE_THEME_DEFAULT: AidTypeTheme = {
  tabActive: 'border-emerald-600 bg-emerald-600 text-white', tabInactive: 'border-emerald-200 bg-white text-emerald-800 hover:bg-emerald-50',
  headerBar: 'from-emerald-700 via-emerald-600 to-teal-500', panelBorder: 'border-emerald-200',
  headBg: 'bg-emerald-50', headText: 'text-emerald-900', badgeBg: 'bg-emerald-100', badgeText: 'text-emerald-800', amountText: 'text-emerald-800',
}

function getAidTypeTheme(type: string): AidTypeTheme {
  const normalized = normalizePredefinedText(type)
  const matchedKey = Object.keys(AID_TYPE_THEMES).find((key) => normalized.includes(normalizePredefinedText(key)))
  return matchedKey ? AID_TYPE_THEMES[matchedKey] : AID_TYPE_THEME_DEFAULT
}

// "Müracaat Türü" secimi icin her turun kendi rengini gosteren kucuk bir
// nokta - AID_TYPE_THEMES ile AYNI renk ailesi (ör. Ekmek = amber) kullanir,
// boylece kapali/acik liste ve modalin geri kalani (basliktan itibaren)
// GORSEL OLARAK TUTARLI kalir.
const APPLICATION_TYPE_OPTION_DOT: Record<string, string> = {
  ekmek: 'bg-amber-500',
  'gida bankasi': 'bg-lime-500',
  giyim: 'bg-violet-500',
  'hazir yemek': 'bg-fuchsia-500',
  'destek paketi': 'bg-cyan-500',
  'ayni nakdi': 'bg-rose-500',
  'donem disi gida': 'bg-orange-500',
}

type ApplicationTypeOption = { value: string; label: string; themeKey: string }

// Tarayicinin KENDI native <select> acilir listesi (isletim sistemine gore
// sade/beyaz render edilir, CSS ile ozellestirilemez) yerine kullanilan,
// uygulamanin renk temasina uygun ozel acilir liste. Kapali haldeyken bir
// <select> gibi davranir (disabled durumda da ayni gorunur) - acik haldeyken
// her secenegi kendi rengiyle (nokta) ve secili olani bir onay isaretiyle
// gosteren, yuzen (floating) bir panel acar.
// Kullanici istegi: acilir/kapanir bir liste yerine, TUM yardim turleri
// SOLDA her zaman gorunur bir liste halinde durur - hangisine tiklanirsa
// secim ANINDA degisir (kesme/kaydirma/tasma sorunu prensipte olusmaz,
// cunku artik hicbir sey "acilip kapanmiyor", her zaman tam gorunurdur).
function ApplicationTypeList({
  value,
  options,
  disabled,
  onSelect,
}: {
  value: string
  options: ApplicationTypeOption[]
  disabled: boolean
  onSelect: (value: string) => void
}) {
  return (
    <div className={`flex flex-col gap-1 rounded-xl border-2 border-slate-200 bg-white p-1.5 shadow-sm ${disabled ? 'opacity-60' : ''}`}>
      {options.map((option) => {
        const isSelected = option.value === value
        const optionTheme = option.value ? getAidTypeTheme(option.value) : null
        return (
          <button
            key={option.value}
            type="button"
            disabled={disabled}
            onClick={() => onSelect(option.value)}
            className={`flex items-center gap-2.5 rounded-lg px-3 py-3 text-left text-[15px] font-bold uppercase tracking-wide transition ${
              disabled ? 'cursor-not-allowed' : ''
            } ${
              isSelected && optionTheme
                ? `${optionTheme.badgeBg} ${optionTheme.headText} font-black ring-2 ring-inset ${optionTheme.panelBorder}`
                : 'text-slate-700 hover:bg-slate-50'
            }`}
          >
            <span className={`h-3 w-3 shrink-0 rounded-full ${APPLICATION_TYPE_OPTION_DOT[option.themeKey] || 'bg-slate-400'}`} />
            <span className="min-w-0 flex-1 truncate">{option.label}</span>
            {isSelected && (
              <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="shrink-0">
                <path d="M5 10.5l3 3 7-8" />
              </svg>
            )}
          </button>
        )
      })}
    </div>
  )
}

// "Yardım türüne göre kayıtlar" altindaki genel (Ekmek/Dönem Dışı Gıda/Giyim/
// Ayni-Nakdi vb.) tablonun baslik-tiklaninca-sirala ozelligi icin. Modul
// seviyesinde tanimli - bilesen icinde tanimlanan bir fonksiyon olsaydi her
// render'da yeniden olusturulup useMemo'nun bagimlilik listesine "eksik
// bagimlilik" uyarisi olarak girecekti (bkz. AID_TYPE_THEMES/getAidTypeTheme
// icin ayni sebeple modul seviyesine tasinma karari).
type AidAssistanceSortKey =
  | 'date' | 'startDate' | 'endDate' | 'status' | 'amount' | 'shoppingAmount' | 'periodInfo'
  | 'stage' | 'label' | 'paymentStartDate' | 'paymentEndDate' | 'paymentDescription'
  | 'muracaatDescription' | 'description'

function aidAssistanceSortValue(row: AssistanceRow, key: AidAssistanceSortKey) {
  if (key === 'date' || key === 'startDate' || key === 'endDate' || key === 'paymentStartDate' || key === 'paymentEndDate') {
    return displayDateToInputDate(row[key] as string) || ''
  }
  if (key === 'amount' || key === 'shoppingAmount') {
    const numeric = Number(String(row[key]).replace(/[^0-9.-]/g, '')) || 0
    return String(numeric).padStart(15, '0')
  }
  if (key === 'status') return row.status || ''
  if (key === 'periodInfo') return row.periodInfo || ''
  if (key === 'stage') return row.stage || ''
  if (key === 'label') return row.label || ''
  if (key === 'paymentDescription') return row.paymentDescription || ''
  if (key === 'muracaatDescription') return row.muracaatDescription || ''
  return row.description || ''
}

function addMonthsToInputDate(value: string, months: number) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || months <= 0) return ''
  const [year, month, day] = value.split('-').map(Number)
  const date = new Date(year, month - 1, day)
  date.setMonth(date.getMonth() + months)

  if (Number.isNaN(date.getTime())) return ''

  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, '0'),
    String(date.getDate()).padStart(2, '0'),
  ].join('-')
}

// Kullanici istegi: "Yardıma Dönüştür" tiklaninca dogrudan donusturmek
// yerine once yardimin miktar/baslangic/bitis tarihini gosteren bir
// bilgilendirme penceresi acilsin. Bu fonksiyon, app/api/documents/
// convert-application/route.ts'deki GERCEK donusum SQL mantigini (bastarih
// HER ZAMAN bugune sabitlenir; bittarih SADECE Ekmek/Hazır Yemek gibi
// "N Ay" bicimindeki donem alanina sahip turlerde bugune gore yeniden
// hesaplanir, Gıda Bankası/Destek Paketi gibi takvim-ay-adi donemli
// turlerde DOKUNULMAZ) BIREBIR client tarafinda ayna gosterir - boylece
// onizleme, gercek donusumde olusacak degerlerle HER ZAMAN tutarlidir.
function computeApplicationConvertPreview(row: ApplicationRow) {
  const startDate = new Date().toLocaleDateString('tr-TR')
  const isDurationBasedType = row.sourceTable === 'yrd_ekmek' || row.sourceTable === 'yrd_haziryemek'
  const periodText = cleanDisplayValue(row.period).trim()
  const durationMatch = isDurationBasedType ? periodText.match(/^(\d+)\s*[Aa]y/) : null

  let endDate = cleanDisplayValue(row.endDate) || '-'
  if (durationMatch) {
    const months = parseInt(durationMatch[1], 10) || 0
    const newEndInputDate = addMonthsToInputDate(getTodayInputDate(), months)
    if (newEndInputDate) endDate = newEndInputDate.split('-').reverse().join('.')
  }

  return {
    amount: cleanDisplayValue(row.amount) || '-',
    startDate,
    endDate,
  }
}

function inferMonthPeriod(startDate?: string | null, endDate?: string | null) {
  const startText = displayDateToInputDate(startDate)
  const endText = displayDateToInputDate(endDate)

  if (!/^\d{4}-\d{2}-\d{2}$/.test(startText) || !/^\d{4}-\d{2}-\d{2}$/.test(endText)) return ''

  for (let month = 1; month <= 6; month += 1) {
    if (addMonthsToInputDate(startText, month) === endText) return `${month} Ay`
  }

  return ''
}

function inputDateToEndOfDay(value?: string | null) {
  const text = cleanDisplayValue(value)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return null
  const [year, month, day] = text.split('-').map(Number)
  const date = new Date(year, month - 1, day, 23, 59, 59, 999)
  return Number.isNaN(date.getTime()) ? null : date
}

function isPastDisplayDate(value?: string | null) {
  const endOfDay = inputDateToEndOfDay(displayDateToInputDate(value))
  return Boolean(endOfDay && Date.now() > endOfDay.getTime())
}

function displayDateTime(value?: string | null) {
  const text = cleanDisplayValue(value)
  if (!text) return '-'
  const date = new Date(text)
  return Number.isNaN(date.getTime()) ? text : date.toLocaleString('tr-TR')
}

function dateTimeToInputDate(value?: string | null) {
  const text = cleanDisplayValue(value)
  if (!text) return getTodayInputDate()
  const date = new Date(text)
  if (!Number.isNaN(date.getTime())) {
    const year = date.getFullYear()
    const month = String(date.getMonth() + 1).padStart(2, '0')
    const day = String(date.getDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
  }
  return displayDateToInputDate(text) || getTodayInputDate()
}

function displayBelgeTip(value?: string | number | null) {
  return String(value ?? '0') === '1' ? 'UYGUN DEĞİL' : 'UYGUNDUR'
}

function getBelgeMetaValue(record: BelgeRecord, key: string) {
  const prefix = `${key}:`
  return (record.icerik || '')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .find((line) => line.toLocaleLowerCase('tr-TR').startsWith(prefix.toLocaleLowerCase('tr-TR')))
    ?.slice(prefix.length)
    .trim() || ''
}

function displayBelgeDurumu(record: BelgeRecord) {
  // Belge tablosundaki "etiket" kolonu, bu belgenin gercek/ozel durumunu
  // (ör. "GELİRİ YÜKSEK - UYGUN DEĞİL", "ARAÇ KAYDI VAR - UYGUN DEĞİL")
  // tutuyor - genel UYGUNDUR/UYGUN DEĞİL metninden cok daha bilgilendirici.
  // Varsa DURUMU sutununda oncelikli olarak bu gosterilir.
  const etiket = record.etiket?.trim()
  if (etiket) return etiket
  return getBelgeMetaValue(record, 'Istenen evrak') || displayBelgeTip(record.tipi)
}

function displayGenderToCode(value?: string | null) {
  const normalized = cleanDisplayValue(value).toLocaleUpperCase('tr-TR')
  if (normalized === 'ERKEK' || normalized === 'E') return 'E'
  if (normalized === 'KADIN' || normalized === 'K') return 'K'
  return cleanDisplayValue(value)
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function normalizeLookupKey(value: string) {
  return value
    .toLocaleLowerCase('tr-TR')
    .replaceAll('ı', 'i')
    .replaceAll('ğ', 'g')
    .replaceAll('ü', 'u')
    .replaceAll('ş', 's')
    .replaceAll('ö', 'o')
    .replaceAll('ç', 'c')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '')
}

function findPredefinedOptions(
  values: PredefinedValuesMap,
  titles: PredefinedValueTitlesMap,
  candidates: string[]
) {
  const category = findPredefinedCategoryByCandidates(values, titles, candidates)

  return category ? values[category] ?? [] : []
}

function primitiveToText(value: unknown): string {
  if (value === null || value === undefined) return ''
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value).trim()
  if (isPlainRecord(value)) {
    const description = readRecordText(value, ['Aciklama', 'Açıklama', 'Ad', 'Adi', 'Adı', 'Value', 'Deger', 'De?er'])
    if (description) return description

    const day = readRecordText(value, ['Gun', 'Gün', 'Day'])
    const month = readRecordText(value, ['Ay', 'Month'])
    const year = readRecordText(value, ['Yil', 'Yıl', 'Year'])
    if (day || month || year) return [day, month, year].filter(Boolean).join('.')
  }
  return ''
}

function readRecordText(record: Record<string, unknown>, keys: string[]) {
  const normalizedKeys = keys.map(normalizeLookupKey)
  const entry = Object.entries(record).find(([key]) => normalizedKeys.includes(normalizeLookupKey(key)))
  return entry ? primitiveToText(entry[1]) : ''
}

function readRecordValue(record: Record<string, unknown>, keys: string[]) {
  const normalizedKeys = keys.map(normalizeLookupKey)
  return Object.entries(record).find(([key]) => normalizedKeys.includes(normalizeLookupKey(key)))?.[1]
}

function readRecordTextDeep(record: Record<string, unknown>, keys: string[], depth = 2): string {
  const direct = readRecordText(record, keys)
  if (direct || depth <= 0) return direct

  for (const value of Object.values(record)) {
    if (!isPlainRecord(value)) continue
    const nested = readRecordTextDeep(value, keys, depth - 1)
    if (nested) return nested
  }

  return ''
}

function readFamilyRegistryRelation(record: Record<string, unknown>) {
  const relationKeys = [
    'Yakinlik',
    'Yakınlık',
    'YakinlikDurumu',
    'YakinlikAciklama',
    'YakinlikAdi',
    'YakinlikDerecesi',
    'YakınlıkDerecesi',
    'YakinlikDerecesiAciklama',
    'YakinlikKodu',
    'YakinlikKod',
    'YakinlikTuru',
    'AkrabalikDerecesi',
  ]
  const directValue = readRecordValue(record, relationKeys)
  const directText = primitiveToText(directValue)

  if (directText) return directText
  if (isPlainRecord(directValue)) {
    const nestedText = readRecordText(directValue, ['Aciklama', 'Açıklama', 'Ad', 'Adi', 'Adı', 'Value', 'Deger', 'De?er', 'Kod'])
    if (nestedText) return nestedText
  }

  return readRecordTextDeep(record, relationKeys)
}

function familyRegistryIdentityKey(row: Pick<FamilyRegistryRow, 'identityNumber'>) {
  const identityNumber = cleanDisplayValue(row.identityNumber).replace(/\D/g, '')
  return /^\d{11}$/.test(identityNumber) ? identityNumber : ''
}

function familyRegistryDemographicKey(row: Pick<FamilyRegistryRow, 'firstName' | 'lastName' | 'birthDate' | 'fatherName' | 'motherName'>) {
  return [
    row.firstName,
    row.lastName,
    displayDateToInputDate(row.birthDate),
    row.fatherName,
    row.motherName,
  ]
    .map((value) => normalizeLookupKey(cleanDisplayValue(value)))
    .filter(Boolean)
    .join('|')
}

function householdIdentityKey(row: Pick<HouseholdRow, 'identityNumber'>) {
  const identityNumber = cleanDisplayValue(row.identityNumber).replace(/\D/g, '')
  return /^\d{11}$/.test(identityNumber) ? identityNumber : ''
}

function householdDemographicKey(row: Pick<HouseholdRow, 'firstName' | 'lastName' | 'birthDate' | 'fatherName' | 'motherName'>) {
  return [
    row.firstName,
    row.lastName,
    displayDateToInputDate(row.birthDate),
    row.fatherName,
    row.motherName,
  ]
    .map((value) => normalizeLookupKey(cleanDisplayValue(value)))
    .filter(Boolean)
    .join('|')
}

function mergePreservedHouseholdRows(rows: HouseholdRow[], preservedRows?: HouseholdRow[]) {
  if (!preservedRows || preservedRows.length === 0) return rows

  const identityKeys = new Set(rows.map(householdIdentityKey).filter(Boolean))
  const demographicKeys = new Set(rows.map(householdDemographicKey).filter(Boolean))
  const preservedOnlyRows = preservedRows.filter((row) => {
    const identityKey = householdIdentityKey(row)
    if (identityKey && identityKeys.has(identityKey)) return false

    const demographicKey = householdDemographicKey(row)
    return !(demographicKey && demographicKeys.has(demographicKey))
  })

  return [...rows, ...preservedOnlyRows].map((row, index) => ({
    ...row,
    no: String(index + 1),
  }))
}

function newFilePersonIdentityKey(person: Pick<NewFilePersonForm, 'tc'>) {
  const identityNumber = cleanDisplayValue(person.tc).replace(/\D/g, '')
  return /^\d{11}$/.test(identityNumber) ? identityNumber : ''
}

function newFilePersonDemographicKey(person: Pick<NewFilePersonForm, 'firstName' | 'lastName' | 'birthDate' | 'fatherName' | 'motherName'>) {
  return [
    person.firstName,
    person.lastName,
    person.birthDate,
    person.fatherName,
    person.motherName,
  ]
    .map((value) => normalizeLookupKey(cleanDisplayValue(value)))
    .filter(Boolean)
    .join('|')
}

function findFamilyRegistryRowInNewFileForm(row: FamilyRegistryRow, form: NewFileFormState) {
  const rowIdentityKey = familyRegistryIdentityKey(row)
  const rowDemographicKey = familyRegistryDemographicKey(row)
  const people = [form.applicant, ...form.household]

  return people.find((person) => {
    const personIdentityKey = newFilePersonIdentityKey(person)
    if (rowIdentityKey && personIdentityKey && rowIdentityKey === personIdentityKey) return true

    const personDemographicKey = newFilePersonDemographicKey(person)
    return Boolean(rowDemographicKey && personDemographicKey && rowDemographicKey === personDemographicKey)
  })
}

function syncFamilyRegistryRowsWithNewFileForm(rows: FamilyRegistryRow[], form: NewFileFormState, currentFileId?: string) {
  return rows.map((row) => {
    const matchedPerson = findFamilyRegistryRowInNewFileForm(row, form)

    if (matchedPerson) {
      return {
        ...row,
        existingBeneficiaryId: matchedPerson.id || row.existingBeneficiaryId,
        existingFileId: currentFileId || row.existingFileId || '',
        existingFileNo: currentFileId ? form.fileNo : row.existingFileNo || form.fileNo,
        existingRelation: matchedPerson.relation || row.existingRelation,
        isInCurrentFile: true,
      }
    }

    return {
      ...row,
      isInCurrentFile: false,
    }
  })
}

function preferFamilyRegistryValue(current: string, next: string) {
  const currentValue = cleanDisplayValue(current)
  const nextValue = cleanDisplayValue(next)
  return currentValue || !nextValue ? current : next
}

function extractFamilyRegistryRows(value: unknown): FamilyRegistryRow[] {
  const rows: FamilyRegistryRow[] = []

  const visit = (node: unknown) => {
    if (Array.isArray(node)) {
      node.forEach(visit)
      return
    }

    if (!isPlainRecord(node)) return

    const identityNumber = readRecordTextDeep(node, ['TCKimlikNo', 'TcKimlikNo', 'TcKimlikNO', 'KimlikNo', 'Tc', 'TC'])
    const fullName = readRecordTextDeep(node, ['AdSoyad', 'AdiSoyadi', 'AdSoyadi', 'AdıSoyadı'])
    const firstName = readRecordTextDeep(node, ['Ad', 'Adi', 'Adı']) || fullName.split(' ').slice(0, -1).join(' ')
    const lastName = readRecordTextDeep(node, ['Soyad', 'Soyadi', 'Soyadı']) || fullName.split(' ').slice(-1).join(' ')

    if (identityNumber || firstName || lastName) {
      const nextRow: FamilyRegistryRow = {
        no: String(rows.length + 1),
        relation: readFamilyRegistryRelation(node) || '-',
        identityNumber: identityNumber || '-',
          firstName: firstName || '-',
        lastName: lastName || '-',
        birthDate: readRecordTextDeep(node, ['DogumTarihi', 'DogumTarih', 'Do?umTarihi']) || '-',
        birthPlace: readRecordTextDeep(node, ['DogumYeri', 'DogumYer', 'Do?umYeri']) || '-',
        fatherName: readRecordTextDeep(node, ['BabaAdi', 'BabaAd', 'BabaAdı']) || '-',
        motherName: readRecordTextDeep(node, ['AnneAdi', 'AnneAd', 'AnaAdi', 'AnaAdı']) || '-',
        gender: readRecordTextDeep(node, ['Cinsiyet', 'Cinsiyeti']) || '-',
        maritalStatus: readRecordTextDeep(node, ['MedeniHal', 'MedeniHali']) || '-',
        status: readRecordTextDeep(node, ['Durum', 'KayitDurum', 'KayitDurumu', 'Aciklama', 'Açıklama']) || '-',
        deathDate: readRecordTextDeep(node, ['OlumTarih', '�lümTarih', 'OlumTarihi', '�lümTarihi']) || '',
      }
      const identityKey = familyRegistryIdentityKey(nextRow)
      const demographicKey = familyRegistryDemographicKey(nextRow)
      const existingIndex = rows.findIndex((row) => {
        const rowIdentityKey = familyRegistryIdentityKey(row)
        const rowDemographicKey = familyRegistryDemographicKey(row)
        return Boolean(identityKey && rowIdentityKey === identityKey) || Boolean(demographicKey && rowDemographicKey === demographicKey)
      })

      if (existingIndex >= 0) {
        const currentRow = rows[existingIndex]
        rows[existingIndex] = {
          ...currentRow,
          relation: preferFamilyRegistryValue(currentRow.relation, nextRow.relation),
          identityNumber: preferFamilyRegistryValue(currentRow.identityNumber, nextRow.identityNumber),
          firstName: preferFamilyRegistryValue(currentRow.firstName, nextRow.firstName),
          lastName: preferFamilyRegistryValue(currentRow.lastName, nextRow.lastName),
          birthDate: preferFamilyRegistryValue(currentRow.birthDate, nextRow.birthDate),
          birthPlace: preferFamilyRegistryValue(currentRow.birthPlace, nextRow.birthPlace),
          fatherName: preferFamilyRegistryValue(currentRow.fatherName, nextRow.fatherName),
          motherName: preferFamilyRegistryValue(currentRow.motherName, nextRow.motherName),
          gender: preferFamilyRegistryValue(currentRow.gender, nextRow.gender),
          maritalStatus: preferFamilyRegistryValue(currentRow.maritalStatus, nextRow.maritalStatus),
          status: preferFamilyRegistryValue(currentRow.status, nextRow.status),
          deathDate: preferFamilyRegistryValue(currentRow.deathDate || '', nextRow.deathDate || ''),
        }
      } else {
        rows.push(nextRow)
      }
    }

    Object.values(node).forEach(visit)
  }

  visit(value)
  return rows.map((row, index) => ({ ...row, no: String(index + 1) }))
}

