function familyRegistryRelationToFileRelation(value?: string) {
  const text = cleanDisplayValue(value)
  const normalized = normalizeLookupKey(text)

  if (!text) return ''
  if (normalized === 'kendisi' || text === '1') return '0'
  if (normalized === 'esi' || normalized === 'es' || text === '5') return '1'
  if (normalized === 'oglu' || normalized === 'ogul' || normalized === 'olu' || text === '7') return '2'
  if (normalized === 'kizi' || normalized === 'kiz' || normalized === 'kz' || text === '9') return '3'
  if (normalized === 'annesi' || normalized === 'anne') return '4'
  if (normalized === 'babasi' || normalized === 'baba') return '5'

  return text
}

function householdRelationSortWeight(value?: string) {
  const text = cleanDisplayValue(value)
  const normalized = normalizeLookupKey(text)

  if (!text || normalized === 'kendisi') return 99
  if (text === '1' || normalized === 'esi' || normalized === 'es' || normalized.includes('esi') || normalized.includes('eai')) return 1
  if (text === '2' || normalized === 'oglu' || normalized === 'ogul' || normalized === 'olu') return 2
  if (text === '3' || normalized === 'kizi' || normalized === 'kiz' || normalized === 'kz') return 3
  if (text === '4' || normalized === 'annesi' || normalized === 'anne') return 4
  if (text === '5' || normalized === 'babasi' || normalized === 'baba') return 5

  const mappedRelation = Number(familyRegistryRelationToFileRelation(text))
  return Number.isFinite(mappedRelation) && mappedRelation > 0 ? mappedRelation : 99
}

function familyRegistryRowToFilePerson(row: FamilyRegistryRow): NewFilePersonForm {
  return {
    ...emptyNewFilePerson,
    id: row.existingBeneficiaryId,
    tc: cleanDisplayValue(row.identityNumber),
    firstName: cleanDisplayValue(row.firstName),
    lastName: cleanDisplayValue(row.lastName),
    fatherName: cleanDisplayValue(row.fatherName),
    motherName: cleanDisplayValue(row.motherName),
    birthPlace: cleanDisplayValue(row.birthPlace),
    birthDate: displayDateToInputDate(row.birthDate),
    deathDate: displayDateToInputDate(cleanDisplayValue(row.deathDate) || cleanDisplayValue(row.existingDeathDate)),
    gender: displayGenderToCode(row.gender),
    maritalStatus: cleanDisplayValue(row.maritalStatus),
    nationality: 'TC',
    relation: familyRegistryRelationToFileRelation(row.relation),
    addressNo: cleanDisplayValue(row.existingAddressNo),
    address: cleanDisplayValue(row.existingAddress),
  }
}

