  const [communicationSubject, setCommunicationSubject] = useState('')
  const [communicationContent, setCommunicationContent] = useState('')
  const [communicationModalLoading, setCommunicationModalLoading] = useState(false)
  const [communicationSending, setCommunicationSending] = useState(false)
  const [communicationModalError, setCommunicationModalError] = useState('')
  const [communicationFiles, setCommunicationFiles] = useState<File[]>([])
  const communicationFileInputRef = useRef<HTMLInputElement>(null)
  const communicationAutoOpenKeyRef = useRef('')
  const [communicationWindowRect, setCommunicationWindowRect] = useState({ x: 24, y: 24, width: 1000, height: 680 })
  // Kullanici istegi (Ekim 2026): "sag ust kosesine ekrani kapla/kucult
  // butonlari ekleyelim" - diger 4 pencere useFloatingWindow icindeki
  // toggleMaximize'i kullaniyor; bu pencere ayri state tuttugu icin ayni
  // mantik burada paralel tutuluyor.
  const [isCommunicationMaximized, setIsCommunicationMaximized] = useState(false)
  const preMaximizeCommunicationRectRef = useRef(communicationWindowRect)
  const toggleCommunicationMaximize = () => {
    if (isCommunicationMaximized) {
      setCommunicationWindowRect(preMaximizeCommunicationRectRef.current)
      setIsCommunicationMaximized(false)
      return
    }
    preMaximizeCommunicationRectRef.current = communicationWindowRect
    setCommunicationWindowRect({ x: 4, y: 4, width: Math.max(320, window.innerWidth - 8), height: Math.max(240, window.innerHeight - 8) })
    setIsCommunicationMaximized(true)
  }
  const communicationDragRef = useRef<{ pointerId: number; startX: number; startY: number; originX: number; originY: number; width: number; height: number } | null>(null)
  // Kullanici istegi (Ekim 2026): "pencerenin köşesinden tutup boyutunu
  // degistirince icindeki yazi/alan boyutlari da pencereye sigacak sekilde
  // buyusun/kucusun" - diger 4 pencere useFloatingWindow uzerinden bunu
  // ZATEN yapiyor (bkz. o hook'taki ayni teknik); bu pencere kendi ayri
  // state'ini kullandigi icin (communicationWindowRect) olcek burada
  // paralel/ayri bir ResizeObserver ile tutuluyor.
  const communicationContainerRef = useRef<HTMLDivElement>(null)
  const [communicationScale, setCommunicationScale] = useState(1)
  useEffect(() => {
    const element = communicationContainerRef.current
    if (!element) return
    const designWidth = 1000
    const designHeight = 680
    const compute = () => {
      const next = Math.min(element.clientWidth / designWidth, element.clientHeight / designHeight)
      setCommunicationScale((prev) => {
        const clamped = Math.min(1.6, Math.max(0.55, next))
        return Math.abs(prev - clamped) < 0.01 ? prev : +clamped.toFixed(3)
      })
    }
    compute()
    const ro = new ResizeObserver(compute)
    ro.observe(element)
    return () => ro.disconnect()
  }, [])
  // Kullanici istegi (Ekim 2026): Belgeler / Dosya Yönetimi (Yeni Dosya/
  // Güncelle) / Yardım Hareketleri / Müracaat pencereleri de "Kurum İçi
