  useEffect(() => {
    if (!isPrintModalOpen || !selectedPrintDesign) return

    let cancelled = false
    const configuredPrinter = resolveClientPrinterNameForDesign(selectedPrintDesign)
    const configuredPrinters = readClientPrinterConfig().printers || []

    setSelectedPreviewPrinter(configuredPrinter)
    // Kullanici istegi (2026-09-28): Sanal Yazici, o bilgisayarda gercek
    // yazici/agent olsun ya da olmasin HER ZAMAN listede - fiziksel bir
    // yaziciya ihtiyaci yok.
    setAvailablePrintPrinters(Array.from(new Set([VIRTUAL_PRINTER_NAME, configuredPrinter, ...configuredPrinters].map((name) => String(name || '').trim()).filter(Boolean))))
    setDetectedPrintAgentVersion('')
    setPrinterDiscoveryStatus('Bu bilgisayardaki yazıcılar okunuyor...')

    void fetch(localPrintAgentPrintersUrl)
      .then(async (response) => {
        const payload = await response.json().catch(() => ({}))
        if (!response.ok || payload?.success === false || !Array.isArray(payload?.data?.printers)) {
          throw new Error(payload?.error || 'Yazıcı listesi alınamadı.')
        }
        if (cancelled) return

        const agentVersion = String(payload?.agentVersion || '').trim()
        const printers = [VIRTUAL_PRINTER_NAME, ...Array.from(new Set(payload.data.printers.map((name: unknown) => String(name || '').trim()).filter(Boolean)))] as string[]
        setDetectedPrintAgentVersion(agentVersion)
        setAvailablePrintPrinters(printers)
        setSelectedPreviewPrinter((current) => current && printers.includes(current) ? current : printers[0] || '')
        setPrinterDiscoveryStatus(
          agentVersion !== requiredPrintAgentVersion
            ? `Agent güncel değil: ${agentVersion || 'sürüm bilgisi yok'}. Gerekli sürüm: ${requiredPrintAgentVersion}`
            : printers.length > 0
              ? `${printers.length} yazıcı bulundu. Agent ${agentVersion}`
              : 'Bu bilgisayarda yazıcı bulunamadı.',
        )
      })
      .catch((error) => {
        if (!cancelled) {
          setPrinterDiscoveryStatus(`Yerel yazıcı listesi alınamadı: ${error instanceof Error ? error.message : 'Bilinmeyen hata'}`)
        }
      })

    return () => {
      cancelled = true
    }
  }, [isPrintModalOpen, selectedPrintDesign])

