  // degistirebilme - ofset, pencere HER ACILISINDA sifirlanir (kalici
  // DEGIL, sadece o oturumdaki goruntuleme icin).
  const [searchModalOffset, setSearchModalOffset] = useState({ x: 0, y: 0 })
  const searchModalDragRef = useRef<{ startX: number; startY: number; baseX: number; baseY: number } | null>(null)
  const handleSearchModalDragStart = (e: React.MouseEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest('button')) return // kapat butonuna tiklayinca surukleme baslamasin
    e.preventDefault()
    searchModalDragRef.current = { startX: e.clientX, startY: e.clientY, baseX: searchModalOffset.x, baseY: searchModalOffset.y }
    const onMove = (ev: MouseEvent) => {
      const drag = searchModalDragRef.current
      if (!drag) return
      setSearchModalOffset({ x: drag.baseX + (ev.clientX - drag.startX), y: drag.baseY + (ev.clientY - drag.startY) })
    }
    const onUp = () => {
      searchModalDragRef.current = null
      window.removeEventListener('mousemove', onMove)
      window.removeEventListener('mouseup', onUp)
    }
    window.addEventListener('mousemove', onMove)
    window.addEventListener('mouseup', onUp)
  }
  const [isReportModalOpen, setIsReportModalOpen] = useState(false)
  const [reportSaveStatus, setReportSaveStatus] = useState<'idle' | 'saving'>('idle')
  const reportSaveLockRef = useRef(false)
