  const [printNotice, setPrintNotice] = useState<{ title: string; message: string; tone: 'warning' | 'error' | 'success'; action?: { label: string; onClick: () => void } } | null>(null)
  // "Onaya Gönder" penceresi - Ayarlar > Yetkili Personeller listesinden
  // secilebilecek bir kisi + opsiyonel aciklama iceren ozel bir dialog
  // (basit promptDialog yerine, kullanicinin acikca istegi uzerine).
  const [approvalRequestTarget, setApprovalRequestTarget] = useState<AssistanceRow | ApplicationRow | null>(null)
  const [approvalRequestApprovers, setApprovalRequestApprovers] = useState<{ id: string; name: string; title: string }[]>([])
  const [approvalRequestSelectedApproverId, setApprovalRequestSelectedApproverId] = useState('')
  const [approvalRequestReason, setApprovalRequestReason] = useState('')
  const [approvalRequestStatus, setApprovalRequestStatus] = useState<'idle' | 'loading' | 'saving'>('idle')
  // "Uygun Görüş İste" - İnceleme Raporu penceresindeki ayri bir onay akisi.
  // Rapor once kaydedilir (yoksa olusturulur), sonra Yetkili Personellerden
  // biri secilerek ayni onay altyapisina (yardim_onay_talepleri, kayit_turu
  // = 'tahkikat_raporu') bir talep dusulur (bkz. requestReportOpinion /
  // submitReportOpinionRequest).
  const [reportOpinionTarget, setReportOpinionTarget] = useState<{ reportId: string; subject: string } | null>(null)
  const [reportOpinionApprovers, setReportOpinionApprovers] = useState<{ id: string; name: string; title: string }[]>([])
  const [reportOpinionSelectedApproverId, setReportOpinionSelectedApproverId] = useState('')
  const [reportOpinionNote, setReportOpinionNote] = useState('')
  const [reportOpinionStatus, setReportOpinionStatus] = useState<'idle' | 'loading' | 'saving'>('idle')
  const [isAidMovementsModalOpen, setIsAidMovementsModalOpen] = useState(false)
  // Kullanici istegi: "Dosya Analizi" bir sure Tasarim Modu izgarasindaki
  // (digerleriyle ayni) kalici bir panel olarak denendi, ama kullanici bunu
  // ISTEMEDI - Dosya Yonetimi alaninin EN ALTINDA fazladan yer kaplamasin
  // diye eski haline, arac cubugundaki dugmeyle acilan bir POP-UP/MODAL'a
  // geri donduruldu (bkz. asagida isFileAnalysisModalOpen kullanan JSX).
  const [isFileAnalysisModalOpen, setIsFileAnalysisModalOpen] = useState(false)
  // Kullanici istegi: "Müracaatlar"/"Yardımlar" tablolarindaki sutun
  // siralama/boyutlandirma SADECE Tasarim Modu ACIKKEN calissin - normal
  // kullanimda kullanicinin bir basligi yanlislikla surukleyip/daraltip
  // duzeni bozmasini onlemek icin. LocalDesignGrid'in KENDI ic Tasarim Modu
  // durumu buraya (documents/page.tsx) tasinir ki asagidaki DataTable
  // cagrilarinda da (reorderTableId) kullanilabilsin - bkz.
  // components/shared/LocalDesignGrid.tsx "designMode"/"onDesignModeChange"
  // (disaridan kontrol) notlari.
  // Kullanici istegi (Ekim 2026): Tasarim Modu ac/kapa dugmesi sayfa
  // icindeki bilgi cubugundan ust menuye (kullanici adinin yanina) tasindi -
  // durum artik global DesignModeContext'te tutulur; bu kanca, Dosya
  // Yonetimi sayfasi acikken ust menudeki dugmeyi gorunur kilar.
  const [isDosyaYonetimiDesignMode, setIsDosyaYonetimiDesignMode] = useDesignModeHost()
  // Kullanici istegi (Agustos 2026): SADECE mobil gorunumde "Raporlar ve
  // Tahkikatlar" paneli ile altindaki sekme (Hane/Müracaatlar/Yardımlar...)
  // alaninin yeri degistirilir - mobilde once sekmeler, sonra Raporlar. Web
  // (>= 900px) HIC etkilenmez. LocalDesignGrid mobil yigin esigi de 900.
  const [isDosyaYonetimiMobile, setIsDosyaYonetimiMobile] = useState(false)
  useEffect(() => {
    const mq = window.matchMedia('(max-width: 899px)')
    const update = () => setIsDosyaYonetimiMobile(mq.matches)
    update()
    mq.addEventListener('change', update)
    return () => mq.removeEventListener('change', update)
  }, [])

  // Kullanici istegi (Eylul 2026): "ekrani buyutunce gorunum bozuluyor - onun
  // yerine yazi fontunu buyutelim, Tasarim Modu'nda kullanici yuzdeyle
  // secsin". Bu carpan (%90-%170), sayfa kokundeki ".dy-base-16" tabanina
  // (bkz. app/globals.css "--dy-fs" kurallari) inline stil olarak yazilir -
  // TUM sayfa metni (etiket, deger, baslik, tablo) orantili buyur/kucculur;
  // duzen (LocalDesignGrid izgarasi) etkilenmez, sigmayan icerik Tasarim
  // Modu'nda panel boyutlandirilarak cozulur. Hesaba ozel sunucuda saklanir
  // (bkz. app/api/documents/text-scale/route.ts - dashboard-layout ile ayni
  // desen).
  const [dosyaYonetimiTextScale, setDosyaYonetimiTextScale] = useState(1)
  const textScaleLoadedRef = useRef(false)
  const textScaleSaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => {
    let cancelled = false
    fetch('/api/documents/text-scale')
      .then((res) => res.json())
      .then((payload) => {
        if (cancelled) return
        const scale = Number(payload?.data?.scale)
        if (Number.isFinite(scale) && scale > 0) setDosyaYonetimiTextScale(scale)
      })
      .catch(() => {})
      .finally(() => { if (!cancelled) textScaleLoadedRef.current = true })
    return () => { cancelled = true }
  }, [])
  const dosyaYonetimiTextScaleRef = useRef(1)
  const saveDosyaYonetimiTextScale = useCallback((value: number) => {
    if (!textScaleLoadedRef.current) return
    fetch('/api/documents/text-scale', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ scale: value }),
    }).catch(() => {})
  }, [])
  const handleDosyaYonetimiTextScaleChange = useCallback((next: number) => {
    setDosyaYonetimiTextScale(next)
    dosyaYonetimiTextScaleRef.current = next
    if (!textScaleLoadedRef.current) return
    if (textScaleSaveTimerRef.current) clearTimeout(textScaleSaveTimerRef.current)
    textScaleSaveTimerRef.current = setTimeout(() => saveDosyaYonetimiTextScale(next), 500)
  }, [saveDosyaYonetimiTextScale])

  // Kullanici istegi (Eylul 2026): "Tasarim Modu'ndan cikinca yaptigim TUM
  // degisiklikleri kaydetsin" - yazi boyutu da (kaydirici/butonlar) zaten
  // her degisiklikte 500ms geciken kayda yaziliyor; ama kullanici son
  // tiktan hemen sonra moddan cikarsa bekleyen kayit kaybolmasin diye
  // Tasarim Modu KAPANIRKEN bekleyen kayit aninda flush edilir.
  useEffect(() => {
    if (isDosyaYonetimiDesignMode) return
    if (textScaleSaveTimerRef.current) {
      clearTimeout(textScaleSaveTimerRef.current)
      textScaleSaveTimerRef.current = null
      saveDosyaYonetimiTextScale(dosyaYonetimiTextScaleRef.current)
    }
  }, [isDosyaYonetimiDesignMode, saveDosyaYonetimiTextScale])

  // Kullanici istegi (29 Agustos 2026): "Hızlı İşlemler" paneli - kullanici
  // sik kullandigi dosya islemi butonlarini ekler, oradan kullanir. Secim
  // hesaba ozel saklanir (bkz. app/api/documents/quick-actions/route.ts).
  const [quickActionIds, setQuickActionIds] = useState<string[]>([])
  const [quickActionsEditing, setQuickActionsEditing] = useState(false)
  const [quickActionsLoaded, setQuickActionsLoaded] = useState(false)
  useEffect(() => {
    let cancelled = false
    fetch('/api/documents/quick-actions')
      .then((res) => res.json())
      .then((payload) => {
        if (cancelled) return
        if (payload?.success && Array.isArray(payload.data?.ids)) setQuickActionIds(payload.data.ids)
      })
      .catch(() => {})
      .finally(() => { if (!cancelled) setQuickActionsLoaded(true) })
    return () => { cancelled = true }
  }, [])
  const persistQuickActions = (ids: string[]) => {
    setQuickActionIds(ids)
    fetch('/api/documents/quick-actions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ids }),
    }).catch(() => {})
  }
  const toggleQuickAction = (id: string) => {
    persistQuickActions(quickActionIds.includes(id)
      ? quickActionIds.filter((x) => x !== id)
      : [...quickActionIds, id])
  }
  // Kullanici istegi (Ekim 2026): "Hane Bilgileri", "Müracaatlar",
  // "Yardımlar" ve "Raporlar ve Tahkikatlar" artik ana sayfada (Tasarim
  // Modu izgarasinda) DEGIL, ayri bir SEKME cubugunda gosterilir - tek
  // seferde bir sekme secilir, o sekme tam genislik/detayli gorunur.
  // İcerikleri (DataTable'lar, ActionDropdown'lar, mantik) AYNEN korunur,
  // sadece nasil ACILDIKLARI degisti (izgara paneli yerine sekme).
  // Kullanici istegi (2026-10-07): "sayfa yenilenince alttaki hangi sekme
  // aciksa o acik kalsin" - oncesinde bu SADECE React state'ti, F5/sayfa
  // yenilemede her zaman 'hane'ye donerdi. Artik URL'deki "detailTab"
  // parametresinden okunur (ilk render'da) ve her degisiminde (asagidaki
  // useEffect) GERI URL'e yazilir (router.replace, gecmise yeni kayit
  // EKLEMEDEN - geri tusu kirlenmesin diye) - sayfa yenilenince tarayici
  // zaten ayni URL'i (query dahil) tekrar istedigi icin sekme korunur.
  const DETAIL_TAB_VALUES = ['hane', 'muracaatlar', 'yardimlar', 'disKurum', 'notlar'] as const
  const [activeDetailTab, setActiveDetailTab] = useState<'hane' | 'muracaatlar' | 'yardimlar' | 'disKurum' | 'notlar'>(() => {
    const fromUrl = searchParams.get('detailTab')
    return (DETAIL_TAB_VALUES as readonly string[]).includes(fromUrl || '') ? (fromUrl as typeof DETAIL_TAB_VALUES[number]) : 'hane'
  })
  useEffect(() => {
    if (searchParams.get('detailTab') === activeDetailTab) return
    const params = new URLSearchParams(searchParams.toString())
    params.set('detailTab', activeDetailTab)
    router.replace(`${window.location.pathname}?${params.toString()}`, { scroll: false })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeDetailTab])
  const [selectedAidMovementType, setSelectedAidMovementType] = useState('')
  const [selectedAidMovementTableType, setSelectedAidMovementTableType] = useState('')
  const [gulkartMovementFilters, setGulkartMovementFilters] = useState<Record<string, string>>({})
  const [gulkartMovementSortKey, setGulkartMovementSortKey] = useState<'tarih' | 'kartno' | 'miktar' | 'firmatip' | 'firmaAdi' | 'yardimtip' | null>(null)
  const [gulkartMovementSortDir, setGulkartMovementSortDir] = useState<'asc' | 'desc'>('desc')
  const [aidMovementRows, setAidMovementRows] = useState<AidMovementTableRow[]>([])
  const [aidMovementRowsStatus, setAidMovementRowsStatus] = useState<'idle' | 'loading'>('idle')
  const [aidMovementRowsMessage, setAidMovementRowsMessage] = useState('')
  const [aidHistoryRows, setAidHistoryRows] = useState<AidHistoryRow[]>([])
  const [aidHistoryStatus, setAidHistoryStatus] = useState<'idle' | 'loading'>('idle')
  const [cashAidMovementRows, setCashAidMovementRows] = useState<AssistanceRow[]>([])
  const [cashAidMovementStatus, setCashAidMovementStatus] = useState<'idle' | 'loading'>('idle')
  const [aidAssistanceSortKey, setAidAssistanceSortKey] = useState<AidAssistanceSortKey | null>(null)
  const [aidAssistanceSortDir, setAidAssistanceSortDir] = useState<'asc' | 'desc'>('desc')
  const [aidHistoryFilters, setAidHistoryFilters] = useState<Record<string, string>>({})
  const [aidHistorySortKey, setAidHistorySortKey] = useState<'islemtarihi' | 'islemadi' | 'aciklama' | 'gerekce' | 'miktar' | 'donem' | 'alisveris_miktari' | null>(null)
  const [aidHistorySortDir, setAidHistorySortDir] = useState<'asc' | 'desc'>('desc')
  const [activeReports, setActiveReports] = useState<InvestigationRow[]>([])
  const [activeHomeVisitReports, setActiveHomeVisitReports] = useState<InvestigationRow[]>([])
  const [isAddApplicationModalOpen, setIsAddApplicationModalOpen] = useState(false)
  const [addApplicationForm, setAddApplicationForm] = useState({
    type: '',
    date: '',
    period: '',
    startDate: '',
    endDate: '',
    amount: '',
    breakfastAmount: '',
    description: '',
    beneficiaryTc: '',
    // Nakit Yardımı ?zel Alanları (3.png bazlı)
    subType: '',
    paymentFrequency: 'Süreli',
    paymentChannel: 'Banka',
    // Kullanici istegi: Telefon artik salt-okunur turetilmis bir deger degil,
    // gercek/duzenlenebilir bir form alani - bkz. Ayni/Nakdi Telefon input'u
    // (nakit-telefon) ve handleSaveApplication. Yeni ekte secilen kisinin
    // kendi telefonuyla, duzenlemede ise muracaatin KENDI ceptel bilgisiyle
    // (serviceRow.phone) doldurulur.
    phone: '',
    // Kullanici istegi: TC Kimlikno da artik salt-okunur degil - muracaatin
    // ait oldugu birey, dosyanin GUNCEL hane listesinde bulunamadigi
    // durumlarda (ör. birey baska bir dosyaya tasindi/silindi) TC elle
    // duzeltilebilsin diye. "Müracaat Eden" acilir menusunden secim
    // yapildiginda bu alan o kisinin TC'siyle senkronize edilir, ama elle
    // de degistirilebilir (bkz. nakit-tc input'u, handleSaveApplication).
    tc: '',
    iban: '',
    householdIncome: '',
    applicantBirthDate: '',
    propertyInfo: '',
    vehicleInfo: '',
    label: '',
    specialCode: '',
    stageStatus: '',
    stageDescription: '',
    stageCode: '',
    // Kullanici istegi: "Otomatik Red İptal" tiki - isaretliyse bu muracaat
    // Otomatik Red kontrolune (bkz. cashAidAutoRejectCheck ve asagidaki iki
    // auto-persist efekti) bir daha HIC dahil edilmez, kullanicinin elle
    // sectigi Durumu/Asama degeri korunur.
    otomatikRedIptal: false,
    // Kullanici istegi: Miktar alaninin sagina "Yardım Kişi Sayısı" eklendi -
    // buraya girilen rakam kadar 11 haneli TC kimlik no input'u dinamik
    // olarak listelenir (bkz. nakit-yardim-kisi-sayisi ve asagidaki TC
    // input'lari). Kaydedince bu TC'ler "-" ile birlestirilip
    // yardimkisitc kolonuna yazilir (bkz. handleSaveApplication).
    assistPersonCount: '',
    assistPersonTcs: [] as string[],
  })
  const [addApplicationStatus, setAddApplicationStatus] = useState<'idle' | 'saving'>('idle')
  const [editingApplicationRow, setEditingApplicationRow] = useState<ApplicationRow | null>(null)
  // Kullanici istegi: Yardım Hareketleri penceresinden cift tiklanarak
  // acilan Nakit Yardimi muracaat formu, "requests.update" yetkisi olmayan
  // kullanicilar icin SALT OKUNUR (goruntuleme amacli) acilir - alanlar
  // duzenlenemez, sadece "Kapat" ile kapatilabilir.
  const [isApplicationModalReadOnly, setIsApplicationModalReadOnly] = useState(false)
  // Kullanici istegi: "Yardıma Dönüştür" artik DOGRUDAN donusturmuyor -
  // once miktar/baslangic/bitis tarihini gosteren bir bilgilendirme
  // penceresi aciliyor. Kullanici "Onayla" derse mevcut bilgilerle
  // donusur; "Güncelle" derse mevcut Duzenle formu acilir, kullanici
  // bilgileri degistirip kaydettiginde (convertAfterEditRecord eslesirse)
  // kayit YENI bilgilerle otomatik olarak yardima donusturulur.
  const [convertPreviewRow, setConvertPreviewRow] = useState<ApplicationRow | null>(null)
  const [isConvertPreviewModalOpen, setIsConvertPreviewModalOpen] = useState(false)
  const [convertPreviewStatus, setConvertPreviewStatus] = useState<'idle' | 'converting'>('idle')
  const [convertAfterEditRecord, setConvertAfterEditRecord] = useState<{ recordId: string; sourceTable: string } | null>(null)
  // Kullanici istegi: "Yardım Kişileri (TC)" alanina girilen bir TC, HALEN
  // BEKLEYEN (durumu = 0) BASKA bir muracaatta zaten kayitliysa, hangi
  // dosyada oldugunu gosteren bir uyari verilir (bkz. asagidaki useEffect
  // ve app/api/documents/applications/check-person-tc). TC -> {dosyaNo,
  // applicantName} seklinde, sadece CAKISAN TC'ler icin dolu tutulur.
  const [assistPersonTcConflicts, setAssistPersonTcConflicts] = useState<Record<string, { dosyaNo: string; applicantName: string }>>({})

  const openAddApplicationModal = () => {
    if (!displayedPerson.fileId) return
    const today = new Date()
    const todayStr = today.toISOString().split('T')[0]
    
    setEditingApplicationRow(null)
    setAddApplicationForm({
      type: '',
      date: todayStr,
      // Kullanici istegi: "1 Ay" gibi sabit bir varsayilan artik Ayni/Nakdi
      // Dönem alaniyla UYUMSUZ - bu alan artik Hazır Değerler > Yardım
      // Dönemi icinde tanimli ISIMLI donemleri (ör. "2026 Kırtasiye
      // Yardımı") kullaniyor, sabit sure degil. Bos birakilirsa, listede
      // olmayan bir deger secili gorunmez, kullanici gercek donemlerden
      // birini secmek zorunda kalir.
      period: '',
      startDate: todayStr,
      endDate: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
      amount: '',
      breakfastAmount: '',
      description: '',
      beneficiaryTc: displayedPerson.identityNumber,
      subType: '',
      paymentFrequency: 'Süreli',
      paymentChannel: 'Banka',
      phone: displayedPerson.mobilePhone || '',
      tc: displayedPerson.identityNumber || '',
      iban: '',
      householdIncome: '',
      applicantBirthDate: '',
      propertyInfo: '',
      vehicleInfo: '',
      label: '',
      specialCode: '',
      stageStatus: '',
      stageDescription: '',
      stageCode: '',
      otomatikRedIptal: false,
      assistPersonCount: '',
      assistPersonTcs: [],
    })
    setAssistPersonTcConflicts({})
    setIsApplicationModalReadOnly(false)
    setIsAddApplicationModalOpen(true)
  }

  const handlePeriodChange = (periodVal: string) => {
    const today = new Date()
    const todayStr = today.toISOString().split('T')[0]

    // "Kış Dönemi": baslangic = icinde bulunulan yilin 01 Kasim, bitis = bir
    // sonraki yilin 30 Nisan - ikisi de sabit, kullanici elle degistiremez
    // (bkz. tarih input'larindaki isAutoFilledPeriod readOnly kontrolu).
    if (periodVal === KIS_DONEMI_PERIOD_LABEL) {
      const yil = today.getFullYear()
      const bas = `${yil}-11-01`
      const bit = `${yil + 1}-04-30`
      setAddApplicationForm(prev => ({ ...prev, period: periodVal, startDate: bas, endDate: bit }))
      return
    }

    const months = parseInt(periodVal) || 0

    let endDateStr = ''
    if (months > 0) {
      const end = new Date()
      end.setMonth(end.getMonth() + months)
      endDateStr = end.toISOString().split('T')[0]
    }

    setAddApplicationForm(prev => ({
      ...prev,
      period: periodVal,
      startDate: todayStr,
      endDate: endDateStr
    }))
  }

  const openEditApplicationModal = async (row: ApplicationRow | null, options?: { readOnly?: boolean }) => {
    if (!displayedPerson.fileId || !row) {
      alert('Düzenlenecek müracaat seçili değil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(row, 'müracaat') as ApplicationRow

    if (!serviceRow.recordId || !serviceRow.sourceTable) {
      alert('Bu müracaat kaydı veritabanı bilgisi taşımıyor, düzenlenemedi.')
      return
    }

    const beneficiaryTc =
      cleanDisplayValue(serviceRow.identityNumber) ||
      [displayedPerson, ...(displayedPerson.household || [])].find((person) => {
        const fullName = `${person.firstName} ${person.lastName}`.trim()
        return fullName === cleanDisplayValue(serviceRow.fullName)
      })?.identityNumber ||
      displayedPerson.identityNumber

    setEditingApplicationRow(serviceRow)
    setSelectedApplicationRow(serviceRow)
    const isCashApplication = serviceRow.type === 'Ayni/Nakdi'

    setAddApplicationForm({
      type: serviceRow.type,
      date: displayDateToInputDate(serviceRow.applicationDate) || getTodayInputDate(),
      period: isCashApplication
        ? resolvePredefinedOptionId(cashPeriodOptions, serviceRow.period)
        : cleanDisplayValue(serviceRow.period) || '1 Ay',
      startDate: displayDateToInputDate(serviceRow.startDate) || getTodayInputDate(),
      endDate: displayDateToInputDate(serviceRow.endDate),
      amount: cleanDisplayValue(serviceRow.mealAmount || serviceRow.amount),
      breakfastAmount: cleanDisplayValue(serviceRow.breakfastAmount),
      description: cleanDisplayValue(serviceRow.description),
      beneficiaryTc,
      subType: '',
      paymentFrequency: 'SÒ¼reli',
      paymentChannel: 'Banka',
      // Kullanici istegi: muracaat duzenlenirken Telefon, muracaatin KENDI
      // ceptel bilgisinden (serviceRow.phone - bkz. app/api/documents/
      // fetch/route.ts "COALESCE(t.ceptel, b.ceptel)") doldurulsun - artik
      // secili hane bireyinin bireyler.ceptel'ine SABIT bagli degil.
      phone: cleanDisplayValue(serviceRow.phone),
      // Kullanici istegi: muracaatin KENDI tckimlikno'suna (serviceRow.
      // identityNumber) gore doldurulur - artik sadece o an hane
      // listesinde eslesen bireyin TC'sine BAGIMLI degil, boylece "birey
      // hane listesinde bulunamiyor" durumunda bile dogru/duzeltilebilir
      // bir TC gorunur.
      tc: cleanDisplayValue(serviceRow.identityNumber),
      iban: cleanDisplayValue(serviceRow.iban),
      householdIncome: cleanDisplayValue(serviceRow.householdIncome),
      applicantBirthDate: displayDateToInputDate(serviceRow.applicantBirthDate),
      propertyInfo: cleanDisplayValue(serviceRow.propertyInfo),
      // Kullanici istegi: "Araç Bilgisi" (Evet/Hayır + model) artik sadece
      // "Araç Modeli" (yil, rakam) alanina indirgendi - eski kayitlarda
      // "Evet - 2015", "VAR 2015", duz "2015" gibi FARKLI bicimlerde
      // saklanmis olabilecek metinden extractYearFromText ile GUVENILIR
      // sekilde yil cikarilir, boylece eski/farkli bicimli kayitlarda da
      // alan BOS gorunmez.
      vehicleInfo: (() => {
        const year = extractYearFromText(serviceRow.vehicleInfo)
        return year !== null ? String(year) : ''
      })(),
      label: isCashApplication
        ? resolvePredefinedOptionId(cashLabelOptions, serviceRow.label)
        : cleanDisplayValue(serviceRow.label),
      specialCode: '',
      stageStatus: isCashApplication
        ? resolvePredefinedOptionId(cashStageOptions, serviceRow.stage)
        : cleanDisplayValue(serviceRow.stage),
      stageDescription: '',
      stageCode: '',
      otomatikRedIptal: Boolean(serviceRow.otomatikRedIptal),
      // Kullanici istegi: mevcut "TC1-TC2-TC3" seklinde kayitli deger
      // acilirken tekrar sayi + ayri TC input'larina bolunerek gosterilir.
      assistPersonTcs: (() => {
        const raw = cleanDisplayValue(serviceRow.assistPersonTcList)
        return raw ? raw.split('-').map((tc) => tc.trim()).filter(Boolean) : []
      })(),
      // Kullanici istegi: kayitli "yardimkisisayisi" kolonu esas alinir -
      // yoksa (ör. eski kayit) TC listesinin uzunlugundan turetilir.
      assistPersonCount: (() => {
        const storedCount = cleanDisplayValue(serviceRow.assistPersonCount)
        if (storedCount) return storedCount
        const raw = cleanDisplayValue(serviceRow.assistPersonTcList)
        const list = raw ? raw.split('-').map((tc) => tc.trim()).filter(Boolean) : []
        return list.length > 0 ? String(list.length) : ''
      })(),
    })
    setAssistPersonTcConflicts({})
    setIsApplicationModalReadOnly(Boolean(options?.readOnly))
    setIsAddApplicationModalOpen(true)
  }

  // Kullanici istegi: Yardım Hareketleri penceresinde (bkz. "AYNİ/NAKDİ"
  // sekmesi) bir kayda cift tiklandiginda, o kaydin muracaat formu SALT
  // OKUNUR (requests.update yetkisi yoksa) ya da duzenlenebilir (yetki
  // varsa) olarak acilir. Bu liste ODENMIS/IPTAL EDILMIS gibi ZATEN
  // SONUCLANMIS kayitlari da gosterdiginden (Müracaatlar sekmesindeki
  // openEditApplicationModal'in dayandigi "applications" verisi SADECE
  // durumu=0/beklemede kayitlari icerir), ayri bir uc noktadan (bkz.
  // app/api/documents/applications GET) TEKIL kayit cekilir.
  const openCashApplicationFromMovement = async (row: AssistanceRow) => {
    if (!displayedPerson.fileId || !row.recordId || row.sourceTable !== 'yrd_ayninakti') return

    try {
      const response = await fetch(`/api/documents/applications?id=${encodeURIComponent(row.recordId)}&fileId=${encodeURIComponent(displayedPerson.fileId)}`)
      const payload = await response.json() as { success: boolean; data?: ApplicationRow; error?: string }

      if (!response.ok || !payload.success || !payload.data) {
        throw new Error(payload.error || 'Müracaat kaydı alınamadı.')
      }

      await openEditApplicationModal(payload.data, { readOnly: !canUseAction('requests.update') })
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Müracaat kaydı alınamadı.')
    }
  }

  const handleSaveApplication = async () => {
    if (!displayedPerson.fileId || !addApplicationForm.type || !addApplicationForm.date || !addApplicationForm.beneficiaryTc) {
      alert('Lütfen tüm zorunlu alanları (Kişi, Tür ve Tarih) doldurun.')
      return
    }

    // "Uygun Görüş İste" akışından açılmışsa, dropdown zaten daraltılmıştı -
    // burada da (savunma amaçlı) aynı kısıt tekrar uygulanır.
    if (reportOpinionTarget && !OPINION_FLOW_ASSISTANCE_TYPES.has(addApplicationForm.type)) {
      alert('Uygun Görüş İste akışında sadece Ekmek, Gıda Bankası, Destek Paketi ve Hazır Yemek türleri eklenebilir.')
      return
    }

    // Seçilen ki?iyi bul
    const targetPerson = addApplicationForm.beneficiaryTc === displayedPerson.identityNumber
      ? displayedPerson
      : (displayedPerson.household || []).find(h => h.identityNumber === addApplicationForm.beneficiaryTc)
    const isEditingApplication = Boolean(editingApplicationRow?.recordId && editingApplicationRow?.sourceTable)
    // Kullanici istegi: Ayni/Nakdi muracaatinin sahibi ARTIK dosyanin
    // GUNCEL hane listesinde bulunmayabilir (ör. birey baska bir dosyaya
    // tasindi/silindi, ya da muracaat "yetim" kaldi) - bu durumda "Seçilen
    // müracaatçı bilgisi bulunamadı" diyerek DUZENLEMEYI TAMAMEN
    // engellemek yerine, muracaatin KENDI (zaten kayitli) ad/TC bilgisi
    // kullanilarak diger alanlar (telefon, dönem, durum, aciklama vb.)
    // yine de duzeltilebilsin diye izin verilir. YENI kayit eklerken
    // (editingApplicationRow yok) bu esneklik uygulanmaz - o zaman gercekten
    // gecerli bir kisi secilmis olmali.
    const canFallBackToExistingRecord = isEditingApplication && addApplicationForm.type === 'Ayni/Nakdi'

    if (!targetPerson && !canFallBackToExistingRecord) {
      alert('Seçilen müracaatçı bilgisi bulunamadı.')
      return
    }

    if (addApplicationForm.type === 'Hazır Yemek' && !addApplicationForm.amount.trim() && !addApplicationForm.breakfastAmount.trim()) {
      alert('Hazır Yemek için yemek miktarı veya kahvaltı miktarından en az birini girin.')
      return
    }

    // Kullanici istegi: "Yardım Kişi Sayısı" belirlenmisse (0'dan buyukse),
    // o kadar GECERLI (resmi kontrol basamagi algoritmasina uyan, sadece
    // 11 haneli olmasi YETERLI DEGIL - bkz. lib/utils/tcKimlikNo.ts) TC
    // kimlik no girilmesi ZORUNLU - belirlenmemisse (bos) hicbir TC
    // girilmesi zorunlu degil. Ayrica GIRILMIS (bos birakilmamis) ama
    // GECERSIZ bir TC varsa, kisi sayisi kosulundan BAGIMSIZ olarak
    // kaydetme engellenir.
    if (addApplicationForm.type === 'Ayni/Nakdi') {
      const nonEmptyTcs = addApplicationForm.assistPersonTcs.map((tc) => tc.trim()).filter(Boolean)
      const invalidTc = nonEmptyTcs.find((tc) => !isValidTcKimlikNo(tc))
      if (invalidTc) {
        alert(`"${invalidTc}" geçerli bir TC Kimlik No değil - lütfen kontrol edip tekrar girin.`)
        return
      }

      const requiredPersonCount = parseInt(addApplicationForm.assistPersonCount, 10) || 0
      if (requiredPersonCount > 0) {
        const validTcCount = nonEmptyTcs.filter((tc) => isValidTcKimlikNo(tc)).length
        if (validTcCount < requiredPersonCount) {
          alert(`Yardım Kişi Sayısı ${requiredPersonCount} olarak belirlendi - lütfen ${requiredPersonCount} adet geçerli TC kimlik numarasının tamamını girin.`)
          return
        }
      }

      // Kullanici istegi: her TC icin EN FAZLA 1 yardim yapilabilir - bu
      // yuzden HALEN BEKLEYEN (durumu = 0) BASKA bir muracaatta zaten
      // kayitli bir TC varsa, sadece ekranda uyari GOSTERMEKLE
      // YETINILMEZ, KAYDETME/GUNCELLEME TAMAMEN ENGELLENIR. Ekrandaki
      // (bkz. assistPersonTcConflicts) uyari 400ms gecikmeli calistigindan
      // (ve stale kalabileceginden) burada TEKRAR, TAM O ANKI veriyle
      // sunucuya sorulur - kullanici "Güncelle"ye cok hizli basarsa bile
      // eksik/yanlis bilgiyle kaydetmenin onune gecilir.
      if (nonEmptyTcs.length > 0) {
        try {
          const conflictResponse = await fetch('/api/documents/applications/check-person-tc', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              tcs: nonEmptyTcs,
              excludeRecordId: editingApplicationRow?.sourceTable === 'yrd_ayninakti' ? editingApplicationRow.recordId : undefined,
            }),
          })
          const conflictPayload = await conflictResponse.json() as { success: boolean; matches?: { tc: string; dosyaNo: string; applicantName: string }[] }
          if (conflictResponse.ok && conflictPayload.success && (conflictPayload.matches?.length ?? 0) > 0) {
            const details = (conflictPayload.matches ?? [])
              .map((match) => `${match.tc} - Dosya No: ${match.dosyaNo} (${match.applicantName})`)
              .join('\n')
            alert(`Her TC kimlik no için en fazla 1 nakit yardımı yapılabilir. Aşağıdaki TC(ler) halen beklemede olan başka bir müracaatta zaten kayıtlı, kaydetmeden önce çıkarın veya düzeltin:\n\n${details}`)
            return
          }
        } catch {
          // Baglanti sorununda kaydetmeyi ENGELLEMEYIZ - sunucu tarafi zaten
          // ayni kontrolu tekrar yapamadigimizdan burada sadece "iyi niyetli"
          // bir ON kontrol; asil veri butunlugu gerekirse ayrica saglanir.
        }
      }
    }

    setAddApplicationStatus('saving')
    try {
      const fullName = targetPerson
        ? `${targetPerson.firstName} ${targetPerson.lastName}`
        : (cleanDisplayValue(editingApplicationRow?.fullName) || 'Bilinmeyen Müracaatçı')
      // Kullanici istegi: Telefon ve TC Kimlikno artik formda duzenlenebilir
      // alanlar (ozellikle Ayni/Nakdi muracaatinin KENDI ceptel/tckimlikno
      // bilgisini koruyabilmek icin) - doluysa onlar kullanilir, bos
      // birakilmissa secili kisinin kendi bilgisine (varsa) geri dusulur.
      const phone = addApplicationForm.phone.trim() || (targetPerson && 'mobilePhone' in targetPerson ? targetPerson.mobilePhone : '')
      const identityNumber = addApplicationForm.tc.trim() || targetPerson?.identityNumber || cleanDisplayValue(editingApplicationRow?.identityNumber)
      // Kullanici istegi: girilen TC kimlik no'lari "-" ile birlestirilerek
      // tek bir metin kolonunda (yardimkisitc) saklanir; bos birakilan
      // input'lar atlanir.
      const assistPersonTcList = addApplicationForm.assistPersonTcs.map((tc) => tc.trim()).filter(Boolean).join('-')
      const response = await fetch('/api/documents/applications', {
        method: isEditingApplication ? 'PATCH' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...addApplicationForm,
          fileId: displayedPerson.fileId,
          recordId: editingApplicationRow?.recordId,
          sourceTable: editingApplicationRow?.sourceTable,
          applicantName: fullName,
          identityNumber,
          phone,
          assistPersonTcList,
        }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Müracaat kaydı veritabanına eklenemedi.')
      }

      setEditingApplicationRow(null)
      setIsAddApplicationModalOpen(false)
      // Kullanici istegi (bug fix): kaydet -> ayni kaydi HEMEN tekrar ac ->
      // "eski haliyle aciyor" sikayeti. Kok neden: kayit sunucuda dogru
      // guncelleniyordu ama yerel "displayedPerson.applications" listesi
      // eskiden refreshFileDetailsInBackground ile SESSIZCE (fire-and-forget,
      // beklenmeden) tazeleniyordu - kullanici basari mesajini kapatir
      // kapatmaz ayni kaydi tekrar acarsa (openEditApplicationModal ->
      // resolveServiceRecordRow, recordId/sourceTable zaten dolu oldugundan
      // sunucuya SORMADAN elindeki satiri dogrudan kullanir), tazeleme henuz
      // bitmemis olabiliyor ve ESKI satir gosteriliyordu. Artik bu tazeleme
      // ALERT'TEN (kullanicinin en az bir tikla kapatmasi gereken, bu arada
      // aga isteginin tamamlanmasi icin dogal bir bekleme payi sunan) ONCE
      // BEKLENIYOR - boylece kullanici uyariyi kapatip kaydi tekrar actiginda
      // liste zaten guncel olur.
      await fetchFileDetails(displayedPerson.fileId, undefined, { silent: true })

      // Kullanici istegi: "Yardıma Dönüştür" onizleme penceresinden
      // "Güncelle" secilip bu forma gelinmisse (bkz. convertAfterEditRecord,
      // openConvertPreviewModal), kaydetme basarili olur olmaz kayit YENI
      // bilgilerle OTOMATIK olarak yardima donusturulur - ayrica "Yardıma
      // Dönüştür"e tekrar tiklamaya gerek kalmaz.
      if (
        convertAfterEditRecord &&
        editingApplicationRow?.recordId === convertAfterEditRecord.recordId &&
        editingApplicationRow?.sourceTable === convertAfterEditRecord.sourceTable
      ) {
        setConvertAfterEditRecord(null)
        await performConvertApplicationToAssistance(
          convertAfterEditRecord.recordId,
          convertAfterEditRecord.sourceTable,
          { successMessage: 'Müracaat güncellendi ve yeni bilgilerle yardıma dönüştürüldü.' },
        )
      } else {
        alert(isEditingApplication ? 'Müracaat kaydı başarıyla güncellendi.' : 'Müracaat kaydı veritabanına başarıyla eklendi.')
      }
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Kayıt eklenirken bir hata oluştu.')
    } finally {
      setAddApplicationStatus('idle')
    }
  }

  const CONVERTIBLE_APPLICATION_TABLES = new Set(['yrd_ekmek', 'yrd_gidabankasi', 'yrd_destekpaketi', 'yrd_haziryemek'])

  // Gercek donusum cagrisi - hem onizleme penceresindeki "Onayla" hem de
  // "Güncelle" sonrasi otomatik zincirleme (bkz. handleSaveApplication
  // icindeki convertAfterEditRecord kontrolu) tarafindan kullanilir.
  const performConvertApplicationToAssistance = async (
    recordId: string,
    sourceTable: string,
    options?: { successMessage?: string },
  ) => {
    if (!displayedPerson.fileId) return false

    setConvertPreviewStatus('converting')
    try {
      const response = await fetch('/api/documents/convert-application', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fileId: displayedPerson.fileId, recordId, sourceTable }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Müracaat yardıma dönüştürülemedi.')
      }

      setSelectedApplicationRow(null)
      setConvertPreviewRow(null)
      setIsConvertPreviewModalOpen(false)
      await fetchFileDetails(displayedPerson.fileId, undefined, { silent: true })
      alert(options?.successMessage || 'Müracaat yardıma dönüştürüldü.')
      return true
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Müracaat yardıma dönüştürülürken hata oluştu.')
      return false
    } finally {
      setConvertPreviewStatus('idle')
    }
  }

  // Kullanici istegi: "Yardıma Dönüştür" artik DOGRUDAN donusturmuyor -
  // once miktar/baslangic/bitis tarihini gosteren bir onay penceresi acilir
  // (bkz. computeApplicationConvertPreview, isConvertPreviewModalOpen JSX
  // blogu). Kullanici "Onayla" derse mevcut bilgilerle, "Güncelle" derse
  // duzenleme formundan girilen YENI bilgilerle donusur.
  const openConvertPreviewModal = async () => {
    if (!displayedPerson.fileId || !selectedApplicationRow) {
      alert('Yardıma dönüştürülecek müracaat seçili değil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(selectedApplicationRow, 'müracaat') as ApplicationRow

    if (!serviceRow.recordId || !serviceRow.sourceTable || !CONVERTIBLE_APPLICATION_TABLES.has(serviceRow.sourceTable)) {
      alert('Sadece Gıda Bankası, Ekmek, Destek Paketi ve Hazır Yemek müracaatları yardıma dönüştürülebilir.')
      return
    }

    setConvertPreviewRow(serviceRow)
    setIsConvertPreviewModalOpen(true)
  }

  const openFoodBankPaymentModal = async () => {
    if (!displayedPerson.fileId || !selectedAssistanceRow) {
      alert('Odenecek yardim secili degil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(selectedAssistanceRow, 'yardım') as AssistanceRow

    if (!serviceRow.recordId || !['yrd_gidabankasi', 'yrd_destekpaketi'].includes(serviceRow.sourceTable || '')) {
      alert('Odeme islemi sadece Gida Bankasi ve Destek Paketi yardimlari icin kullanilabilir.')
      return
    }

    if (cleanDisplayValue(serviceRow.periodInfo).toLocaleLowerCase('tr-TR').includes('ödendi')) {
      alert('Bu yardim kaydinin odemesi bu donem icin daha once yapilmis.')
      return
    }

    setSelectedAssistanceRow(serviceRow)
    setFoodBankPaymentForm({
      date: displayDateToInputDate(serviceRow.paymentStartDate) || getTodayInputDate(),
      description: cleanDisplayValue(serviceRow.paymentDescription),
    })
    setIsFoodBankPaymentModalOpen(true)
  }

  const handleSaveFoodBankPayment = async () => {
    if (!displayedPerson.fileId || !selectedAssistanceRow) {
      alert('Odenecek yardim secili degil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(selectedAssistanceRow, 'yardım') as AssistanceRow

    if (!serviceRow.recordId || !['yrd_gidabankasi', 'yrd_destekpaketi'].includes(serviceRow.sourceTable || '')) {
      alert('Odeme islemi sadece Gida Bankasi ve Destek Paketi yardimlari icin kullanilabilir.')
      return
    }

    if (cleanDisplayValue(serviceRow.periodInfo).toLocaleLowerCase('tr-TR').includes('ödendi')) {
      alert('Bu yardim kaydinin odemesi bu donem icin daha once yapilmis.')
      return
    }

    if (!foodBankPaymentForm.date || !foodBankPaymentForm.description.trim()) {
      alert('Tarih ve aciklama alanlari zorunludur.')
      return
    }

    setFoodBankPaymentStatus('saving')
    try {
      const paymentEndpoint = serviceRow.sourceTable === 'yrd_destekpaketi'
        ? '/api/documents/support-package-payment'
        : '/api/documents/food-bank-payment'

      const response = await fetch(paymentEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fileId: displayedPerson.fileId,
          recordId: serviceRow.recordId,
          paymentDate: foodBankPaymentForm.date,
          description: foodBankPaymentForm.description,
        }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Odeme kaydedilemedi.')
      }

      setIsFoodBankPaymentModalOpen(false)
      setSelectedAssistanceRow(null)
      refreshFileDetailsInBackground(displayedPerson.fileId)
      alert('Odeme bilgisi kaydedildi.')
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Odeme kaydedilemedi.')
    } finally {
      setFoodBankPaymentStatus('idle')
    }
  }

  const openBreadCardModal = async (row = selectedAssistanceRow) => {
    if (!displayedPerson.fileId || !row) {
      alert('Kart no atanacak yardım seçili değil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(row, 'yardım') as AssistanceRow

    if (!serviceRow.recordId || serviceRow.sourceTable !== 'yrd_ekmek') {
      alert('Kart no işlemi sadece Ekmek yardımı için kullanılabilir.')
      return
    }

    setSelectedAssistanceRow(serviceRow)
    setBreadCardRow(serviceRow)
    const initialCardNo = cleanDisplayValue(serviceRow.breadCardNo)
    setBreadCardForm({
      date: displayDateToInputDate(serviceRow.breadCardDate) || getTodayInputDate(),
      cardNo: initialCardNo,
      description: cleanDisplayValue(serviceRow.breadCardDescription),
    })
    resetCardScanTracker(breadCardScanTrackerRef.current, initialCardNo)
    setBreadCardError('')
    setIsBreadCardModalOpen(true)
  }

  const saveBreadCard = async (force = false) => {
    if (!displayedPerson.fileId || !breadCardRow?.recordId) return

    // Yardim iptal edildiginde kart numarasi da temizlenebilsin diye, kart
    // no alani BOS birakilarak kaydetmeye izin veriliyor (bu durumda tarih
    // zorunlu degil - kart bilgisi tamamen temizlenir). Kart no GIRILMISSE
    // tarih hala zorunludur.
    if (breadCardForm.cardNo.trim() && !breadCardForm.date) {
      setBreadCardError('Tarih ve kart no zorunludur.')
      return
    }

    setBreadCardStatus('saving')
    setBreadCardError('')

    try {
      const response = await fetch('/api/documents/bread-card', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fileId: displayedPerson.fileId,
          recordId: breadCardRow.recordId,
          cardDate: breadCardForm.date,
          cardNo: breadCardForm.cardNo,
          description: breadCardForm.description,
          force,
        }),
      })
      const payload = await response.json()

      if (response.status === 409 && payload.conflict) {
        // Bu kart no baska bir dosyada/yardimda zaten kayitli - direkt
        // kaydetmek yerine kullaniciya bilgi verip onay istiyoruz.
        setCardNoConflict(payload.existingFile)
        return
      }

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Kart no kaydedilemedi.')
      }

      setIsBreadCardModalOpen(false)
      setBreadCardRow(null)
      setCardNoConflict(null)
      refreshFileDetailsInBackground(displayedPerson.fileId)
    } catch (error) {
      setBreadCardError(error instanceof Error ? error.message : 'Kart no kaydedilemedi.')
    } finally {
      setBreadCardStatus('idle')
    }
  }

  const confirmCardNoReassign = () => {
    setCardNoConflict(null)
    void saveBreadCard(true)
  }

  const cancelCardNoReassign = () => {
    setCardNoConflict(null)
    setBreadCardForm((prev) => ({ ...prev, cardNo: '' }))
    resetCardScanTracker(breadCardScanTrackerRef.current)
    setBreadCardError('Bu kart no başka bir dosyada kayıtlı. Lütfen yeni bir kart no giriniz.')
  }

  const deleteBreadCard = async () => {
    if (!displayedPerson.fileId || !breadCardRow?.recordId) return

    const confirmed = await confirmDialog('Kart no bilgisi silinsin mi?')
    if (!confirmed) return

    setBreadCardStatus('saving')
    setBreadCardError('')

    try {
      const response = await fetch('/api/documents/bread-card', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mode: 'delete',
          fileId: displayedPerson.fileId,
          recordId: breadCardRow.recordId,
        }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Kart no silinemedi.')
      }

      setIsBreadCardModalOpen(false)
      setBreadCardRow(null)
      refreshFileDetailsInBackground(displayedPerson.fileId)
    } catch (error) {
      setBreadCardError(error instanceof Error ? error.message : 'Kart no silinemedi.')
    } finally {
      setBreadCardStatus('idle')
    }
  }

  const openApplicationPaymentModal = async () => {
    if (!displayedPerson.fileId || !selectedApplicationRow) {
      alert('Odenecek muracaat secili degil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(selectedApplicationRow, 'müracaat') as ApplicationRow

    if (!serviceRow.recordId || !['yrd_ddgidadosyali', 'yrd_giyim'].includes(serviceRow.sourceTable || '')) {
      alert('Odeme islemi sadece Donem Disi Gida ve Giyim muracaatlari icin kullanilabilir.')
      return
    }

    setSelectedApplicationRow(serviceRow)
    setApplicationPaymentForm({
      date: getTodayInputDate(),
      description: cleanDisplayValue(serviceRow.description),
    })
    setIsApplicationPaymentModalOpen(true)
  }

  const handleSaveApplicationPayment = async () => {
    if (!displayedPerson.fileId || !selectedApplicationRow) {
      alert('Odenecek muracaat secili degil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(selectedApplicationRow, 'müracaat') as ApplicationRow

    if (!serviceRow.recordId || !['yrd_ddgidadosyali', 'yrd_giyim'].includes(serviceRow.sourceTable || '')) {
      alert('Odeme islemi sadece Donem Disi Gida ve Giyim muracaatlari icin kullanilabilir.')
      return
    }

    if (!applicationPaymentForm.date || !applicationPaymentForm.description.trim()) {
      alert('Tarih ve aciklama alanlari zorunludur.')
      return
    }

    setApplicationPaymentStatus('saving')
    try {
      const response = await fetch('/api/documents/service-record', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mode: 'application-payment',
          fileId: displayedPerson.fileId,
          recordId: serviceRow.recordId,
          sourceTable: serviceRow.sourceTable,
          paymentDate: applicationPaymentForm.date,
          description: applicationPaymentForm.description,
        }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Odeme kaydedilemedi.')
      }

      setIsApplicationPaymentModalOpen(false)
      setSelectedApplicationRow(null)
      refreshFileDetailsInBackground(displayedPerson.fileId)
      alert('Odeme bilgisi kaydedildi.')
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Odeme kaydedilemedi.')
    } finally {
      setApplicationPaymentStatus('idle')
    }
  }

  const openFileStatusModal = () => {
    if (!displayedPerson.fileId) {
      setSearchError('Durumu guncellenecek dosya bulunamadi.')
      return
    }

    const currentStatus = cleanDisplayValue(displayedPerson.fileStatus)
    const selectedStatus = fileStatusOptions.some((option) => option.value === currentStatus)
      ? currentStatus
      : fileStatusOptions[0]?.value ?? '0'

    setFileStatusForm({
      date: getTodayInputDate(),
      status: selectedStatus,
      description: '',
    })
    setFileStatusError('')
    setIsFileStatusModalOpen(true)
  }

  const handleSaveFileStatus = async () => {
    if (!displayedPerson.fileId) return

    // Kullanici istegi (13 Eylul 2026): "aciklama alani zorunlu olmasin,
    // istenirse bos olarak kaydedilebilsin" - sadece Tarih ve Dosya Durumu
    // zorunlu kaldi, Aciklama artik opsiyonel.
    if (!fileStatusForm.date || !fileStatusForm.status) {
      setFileStatusError('Tarih ve dosya durum bilgisi zorunludur.')
      return
    }

    // Dosya "ON INCELEME YAPILMIS" (status '5') durumuna aliniyorsa ve Ayarlar'da
    // Guncelleme Formu icin en az bir soru tanimlanmissa, durumu dogrudan kaydetmek
    // yerine once guncelleme formunu acariz. Dosya durumu, form kaydedilip
    // "Kaydet" ile onaylandiktan sonra degisir (bkz. handleSaveUpdateForm).
    // Form hic yapilandirilmamissa (updateFormSections bos) bu adim atlanir ve
    // asagidaki eski davranis aynen calisir.
    if (fileStatusForm.status === '5' && updateFormSections.length > 0) {
      setIsFileStatusModalOpen(false)
      openUpdateFormModal()
      return
    }

    setFileStatusSaveStatus('saving')
    setFileStatusError('')
    try {
      const response = await fetch('/api/documents/file-status', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fileId: displayedPerson.fileId,
          date: fileStatusForm.date,
          status: fileStatusForm.status,
          description: fileStatusForm.description,
        }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Dosya durumu guncellenemedi.')
      }

      setIsFileStatusModalOpen(false)
      refreshFileDetailsInBackground(displayedPerson.fileId)
    } catch (error) {
      setFileStatusError(error instanceof Error ? error.message : 'Dosya durumu guncellenirken hata olustu.')
    } finally {
      setFileStatusSaveStatus('idle')
    }
  }

  const handleCreateManualPeriod = async () => {
    if (!displayedPerson.fileId || !selectedAssistanceRow) {
      alert('Donem olusturulacak yardim secili degil.')
      return
    }

    const serviceRow = await resolveServiceRecordRow(selectedAssistanceRow, 'yardım') as AssistanceRow

    if (!serviceRow.recordId || !['yrd_gidabankasi', 'yrd_destekpaketi'].includes(serviceRow.sourceTable || '')) {
      alert('Manuel donem sadece Gida Bankasi ve Destek Paketi yardimlari icin kullanilabilir.')
      return
    }

    try {
      const response = await fetch('/api/documents/manual-period', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fileId: displayedPerson.fileId,
          recordId: serviceRow.recordId,
          sourceTable: serviceRow.sourceTable,
        }),
      })
      const payload = await response.json()

      if (!response.ok || !payload.success) {
        throw new Error(payload.error || 'Manuel donem olusturulamadi.')
      }

      setSelectedAssistanceRow(null)
      refreshFileDetailsInBackground(displayedPerson.fileId)
      alert('Manuel donem olusturuldu.')
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Manuel donem olusturulamadi.')
    }
  }
  const [reportForm, setReportForm] = useState({ id: '', source: 'reports', date: getTodayInputDate(), title: '', content: '' })
